@app.errorhandler(413)
def _too_big(e):
    return jsonify({"error": "That file is too large.", "error_code": "too_large"}), 413


MAX_ATTACHMENT_BYTES = 10 * 1024 * 1024  # 10MB - comfortably more than a scanned invoice PDF needs


def _content_disposition(filename, fallback="download"):
    """Builds a Content-Disposition header that works for any filename.
    HTTP headers can only carry Latin-1 text, so a raw Arabic (or Chinese)
    filename in the header crashed the response and the file could never
    be downloaded. Standard fix (RFC 6266/5987): an ASCII-only filename=
    for old clients plus a UTF-8 filename*= that every modern browser
    prefers, so the user still gets the real name."""
    name = str(filename or "").replace("\r", " ").replace("\n", " ").strip() or fallback
    stem, dot, ext = name.rpartition(".")
    if not dot:
        stem, ext = name, ""
    fb_stem, fb_dot, fb_ext = fallback.rpartition(".")
    if not fb_dot:
        fb_stem, fb_ext = fallback, ""
    ascii_stem = re.sub(r"[^A-Za-z0-9_ -]+", "_", stem).strip(" _") or fb_stem
    ascii_ext = re.sub(r"[^A-Za-z0-9]+", "", ext) or fb_ext
    ascii_name = ascii_stem + ("." + ascii_ext if ascii_ext else "")
    return f"attachment; filename=\"{ascii_name}\"; filename*=UTF-8''{url_quote(name, safe='')}"


def init_db():
    conn = psycopg2.connect(DATABASE_URL)
    cur = conn.cursor()
    cur.execute("SELECT pg_advisory_lock(7105002)")  # only one starter-upper at a time; released when the connection closes
    cur.execute(
        """CREATE TABLE IF NOT EXISTS users (
            id SERIAL PRIMARY KEY,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            role TEXT DEFAULT 'staff',
            created_at TEXT DEFAULT ''
        )"""
    )
    # Company-email accounts + two-step verification (Google/Microsoft Authenticator).
    for _col, _ddl in (("email", "TEXT DEFAULT ''"), ("full_name", "TEXT DEFAULT ''"), ("totp_secret", "TEXT DEFAULT ''"),
                       ("totp_enabled", "INTEGER DEFAULT 0"), ("totp_last_step", "BIGINT DEFAULT 0"), ("recovery_codes", "TEXT DEFAULT ''")):
        cur.execute(f"ALTER TABLE users ADD COLUMN IF NOT EXISTS {_col} {_ddl}")
    # Owner / Manager / Staff. Staff report to a manager (manager_id). The first admin becomes
    # the Owner (there is only one); any other admin becomes a Manager.
    cur.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS manager_id INTEGER")
    cur.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS features TEXT")
    cur.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_color INTEGER DEFAULT 0")   # profile picture colour (0 = Compass blue)
    cur.execute("CREATE TABLE IF NOT EXISTS user_avatars (user_id INTEGER PRIMARY KEY, data BYTEA NOT NULL, v BIGINT NOT NULL DEFAULT 0)")
    cur.execute("""CREATE TABLE IF NOT EXISTS consignee_book (
        ckey TEXT PRIMARY KEY, name TEXT DEFAULT '', email TEXT DEFAULT '', attn TEXT DEFAULT '', updated_at TEXT DEFAULT '')""")
    cur.execute("""CREATE TABLE IF NOT EXISTS notice_log (
        id SERIAL PRIMARY KEY, port TEXT DEFAULT '', vessel TEXT DEFAULT '', ckey TEXT DEFAULT '', consignee TEXT DEFAULT '',
        sent_to TEXT DEFAULT '', bls TEXT DEFAULT '', kind TEXT DEFAULT '', sent_by TEXT DEFAULT '', sent_at TEXT DEFAULT '', test INTEGER DEFAULT 0)""")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_notice_log_vessel ON notice_log (port, vessel, ckey)")
    # What each notice said about the vessel (NULL on notices sent before this was kept), further addresses for a consignee,
    # whether a person has confirmed an address, and one row per manifest added in the Manifest Desk (for its report and Undo).
    cur.execute("ALTER TABLE notice_log ADD COLUMN IF NOT EXISTS eta TEXT")
    cur.execute("ALTER TABLE notice_log ADD COLUMN IF NOT EXISTS berth TEXT")
    cur.execute("ALTER TABLE consignee_book ADD COLUMN IF NOT EXISTS more_emails TEXT DEFAULT ''")
    cur.execute("ALTER TABLE consignee_book ADD COLUMN IF NOT EXISTS verified INTEGER DEFAULT 0")
    cur.execute("""CREATE TABLE IF NOT EXISTS desk_uploads (
        id SERIAL PRIMARY KEY, port TEXT DEFAULT '', vessel TEXT DEFAULT '', filename TEXT DEFAULT '', by_user TEXT DEFAULT '',
        at TEXT DEFAULT '', added INTEGER DEFAULT 0, skipped INTEGER DEFAULT 0, left_out INTEGER DEFAULT 0,
        report TEXT DEFAULT '', bls TEXT DEFAULT '', undone INTEGER DEFAULT 0, ack INTEGER DEFAULT 0)""")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_desk_uploads_vessel ON desk_uploads (port, vessel)")
    cur.execute("SELECT 1 FROM users WHERE role = 'owner' LIMIT 1")
    if not cur.fetchone():
        cur.execute("UPDATE users SET role = 'owner' WHERE id = (SELECT MIN(id) FROM users WHERE role = 'admin')")
    cur.execute("UPDATE users SET role = 'manager' WHERE role = 'admin'")
    cur.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_users_email ON users (LOWER(email)) WHERE email <> ''")
    # One row per signed-in browser. The cookie only carries this row's id, so signing out,
    # removing a user or resetting their password ends the session on the server - a copied
    # cookie, bookmark or desktop shortcut can't get back in.
    cur.execute(
        """CREATE TABLE IF NOT EXISTS user_sessions (
            id TEXT PRIMARY KEY,
            user_id INTEGER NOT NULL,
            remember INTEGER DEFAULT 0,
            created_at BIGINT NOT NULL,
            last_seen BIGINT NOT NULL,
            ip TEXT DEFAULT '',
            agent TEXT DEFAULT ''
        )"""
    )
    cur.execute("CREATE INDEX IF NOT EXISTS idx_user_sessions_user ON user_sessions (user_id)")
    # Failed sign-ins, for the 15-minute lockout (in the database so restarts don't reset it).
    cur.execute(
        """CREATE TABLE IF NOT EXISTS login_failures (
            id SERIAL PRIMARY KEY,
            kind TEXT NOT NULL,
            key TEXT NOT NULL,
            at BIGINT NOT NULL
        )"""
    )
    cur.execute("CREATE INDEX IF NOT EXISTS idx_login_failures_key ON login_failures (kind, key, at)")
    # Port line-ups: berths per port, each day's line-up, and the vessels on it.
    cur.execute(
        """CREATE TABLE IF NOT EXISTS lu_berths (
            id SERIAL PRIMARY KEY,
            port TEXT NOT NULL,
            name TEXT NOT NULL,
            max_draft REAL,
            active INTEGER DEFAULT 1,
            sort INTEGER DEFAULT 0
        )"""
    )
    cur.execute(
        """CREATE TABLE IF NOT EXISTS lu_snapshots (
            id SERIAL PRIMARY KEY,
            port TEXT NOT NULL,
            lineup_date TEXT NOT NULL,
            source TEXT DEFAULT '',
            created_by TEXT DEFAULT '',
            created_at TEXT DEFAULT ''
        )"""
    )
    cur.execute("CREATE INDEX IF NOT EXISTS idx_lu_snapshots_port ON lu_snapshots (port, lineup_date)")
    cur.execute(
        """CREATE TABLE IF NOT EXISTS lu_vessels (
            id SERIAL PRIMARY KEY,
            snapshot_id INTEGER NOT NULL REFERENCES lu_snapshots(id) ON DELETE CASCADE,
            seq INTEGER DEFAULT 0,
            vessel TEXT NOT NULL,
            agent TEXT DEFAULT '',
            cargo TEXT DEFAULT '',
            qty DOUBLE PRECISION,
            loa REAL,
            draft REAL,
            arrived TEXT DEFAULT '',
            eta TEXT DEFAULT '',
            etb TEXT DEFAULT '',
            berth TEXT DEFAULT '',
            berthed TEXT DEFAULT '',
            etd TEXT DEFAULT '',
            status TEXT DEFAULT 'anchor',
            ours INTEGER DEFAULT 0,
            principal TEXT DEFAULT '',
            remarks TEXT DEFAULT ''
        )"""
    )
    cur.execute("CREATE INDEX IF NOT EXISTS idx_lu_vessels_snap ON lu_vessels (snapshot_id)")
    cur.execute("ALTER TABLE lu_vessels ADD COLUMN IF NOT EXISTS vtype TEXT DEFAULT ''")
    cur.execute("ALTER TABLE lu_vessels ADD COLUMN IF NOT EXISTS rob DOUBLE PRECISION")
    cur.execute("ALTER TABLE lu_vessels ADD COLUMN IF NOT EXISTS transit DOUBLE PRECISION")
    cur.execute("ALTER TABLE lu_berths ADD COLUMN IF NOT EXISTS cargo_use TEXT DEFAULT ''")
    cur.execute("ALTER TABLE lu_berths ADD COLUMN IF NOT EXISTS kind TEXT DEFAULT ''")
    cur.execute(
        """CREATE TABLE IF NOT EXISTS lu_predictions (
            id SERIAL PRIMARY KEY,
            port TEXT NOT NULL,
            vessel TEXT NOT NULL,
            made_on TEXT NOT NULL,
            pred_start TEXT DEFAULT '',
            pred_berth TEXT DEFAULT ''
        )"""
    )
    cur.execute("CREATE INDEX IF NOT EXISTS idx_lu_predictions ON lu_predictions (port, made_on)")
    cur.execute(
        """CREATE TABLE IF NOT EXISTS records (
            bl_number TEXT PRIMARY KEY,
            consignee TEXT DEFAULT '',
            port TEXT DEFAULT '',
            vessel TEXT DEFAULT '',
            invoice_issued INTEGER DEFAULT 0,
            invoice_by TEXT DEFAULT '',
            invoice_at TEXT DEFAULT '',
            approval_received INTEGER DEFAULT 0,
            approval_by TEXT DEFAULT '',
            approval_at TEXT DEFAULT '',
            do_issued INTEGER DEFAULT 0,
            do_by TEXT DEFAULT '',
            do_at TEXT DEFAULT '',
            remarks TEXT DEFAULT '',
            created_at TEXT DEFAULT ''
        )"""
    )
    # Existing databases (already deployed) won't have these columns yet -
    # add them if missing, so this upgrade doesn't require wiping the data.
    cur.execute("ALTER TABLE records ADD COLUMN IF NOT EXISTS port TEXT DEFAULT ''")
    cur.execute("ALTER TABLE records ADD COLUMN IF NOT EXISTS vessel TEXT DEFAULT ''")
    # Each record is owned by whichever staff account created it - DO Tracker
    # is per-staff (admin sees everything, staff only see their own).
    cur.execute("ALTER TABLE records ADD COLUMN IF NOT EXISTS created_by TEXT DEFAULT ''")
    # Set per-vessel (same value on every BL in that vessel's group), not
    # per-BL - lets the board sort "arriving soonest first" instead of
    # alphabetically, and surfaces an ETA without a separate vessels table.
    cur.execute("ALTER TABLE records ADD COLUMN IF NOT EXISTS eta TEXT DEFAULT ''")
    # Where the vessel is in its call, set once per vessel group like the ETA:
    # vessel_status '' / 'anch' (waiting at anchorage, with an ETB date) /
    # 'berth' (alongside, with a berth number and an ETC/D date). Shown to
    # the customer on the QR / tracking page.
    for _col in ("vessel_status", "etb", "berth_no", "etcd"):
        cur.execute(f"ALTER TABLE records ADD COLUMN IF NOT EXISTS {_col} TEXT DEFAULT ''")
    # A vessel group that's fully complete and old can be archived off the
    # main board (manually, from the UI) without deleting its data - it's
    # still searchable/exportable, just out of the day-to-day view.
    cur.execute("ALTER TABLE records ADD COLUMN IF NOT EXISTS archived INTEGER DEFAULT 0")
    # Customer sharing: who to notify about this BL (consignee and/or their
    # customs broker - which one varies per BL), and the secret code behind
    # its public tracking link (/t/<token>). The token is random, never the
    # BL number, so nobody can look up someone else's cargo by guessing.
    for col in ("loading_port", "packages", "cargo_desc", "notify_name"):
        cur.execute(f"ALTER TABLE records ADD COLUMN IF NOT EXISTS {col} TEXT DEFAULT ''")
    for col in ("consignee_email", "consignee_phone", "broker_email", "broker_phone", "track_token"):
        cur.execute(f"ALTER TABLE records ADD COLUMN IF NOT EXISTS {col} TEXT DEFAULT ''")
    # Paid (the DO charges) and DO sent (the Delivery Order has reached the consignee): who,
    # when, and how - 'receipt' (a paid receipt was attached), 'email' (sent from Compass),
    # 'manual' (ticked by hand), 'before' (already done before these steps existed).
    cur.execute("SELECT 1 FROM information_schema.columns WHERE table_name = 'records' AND column_name = 'do_sent'")
    _had_sent = cur.fetchone() is not None
    for col in ("paid", "do_sent"):
        cur.execute(f"ALTER TABLE records ADD COLUMN IF NOT EXISTS {col} INTEGER DEFAULT 0")
    for col in ("paid_by", "paid_at", "paid_via", "do_sent_by", "do_sent_at", "do_sent_via", "do_sent_to"):
        cur.execute(f"ALTER TABLE records ADD COLUMN IF NOT EXISTS {col} TEXT DEFAULT ''")
    if not _had_sent:
        # B/Ls whose DO was already issued before these two steps existed stay complete.
        cur.execute("UPDATE records SET paid = 1, paid_via = 'before', do_sent = 1, do_sent_via = 'before' WHERE do_issued = 1")
    cur.execute(
        "CREATE UNIQUE INDEX IF NOT EXISTS idx_records_track_token ON records (track_token) "
        "WHERE track_token IS NOT NULL AND track_token <> ''"
    )
    cur.execute(
        """CREATE TABLE IF NOT EXISTS audit_log (
            id SERIAL PRIMARY KEY,
            bl_number TEXT NOT NULL,
            action TEXT NOT NULL,
            field TEXT DEFAULT '',
            old_value TEXT DEFAULT '',
            new_value TEXT DEFAULT '',
            by_user TEXT DEFAULT '',
            at TEXT DEFAULT ''
        )"""
    )
    cur.execute("CREATE INDEX IF NOT EXISTS idx_audit_log_bl ON audit_log (bl_number)")
    # The bell (alerts between an operator and the DO team), the importer no. a B/L's invoice is raised against,
    # when the DO team was asked for that invoice, and when the consignee pressed "I have paid" on the tracking page (and when
    # that report was cleared), and when the DO team was told a B/L is ready for its Delivery Order. A DO-team account is one the Owner ticked in Admin.
    cur.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS do_team INTEGER DEFAULT 0")
    for _col in ("importer_no", "inv_requested_at", "inv_requested_by", "pay_reported_at", "pay_cleared_at", "do_ready_at"):
        cur.execute(f"ALTER TABLE records ADD COLUMN IF NOT EXISTS {_col} TEXT DEFAULT ''")
    cur.execute("""CREATE TABLE IF NOT EXISTS notifications (
        id SERIAL PRIMARY KEY, user_id INTEGER NOT NULL, kind TEXT DEFAULT 'info', title TEXT DEFAULT '', body TEXT DEFAULT '',
        bl_number TEXT DEFAULT '', created_at TEXT DEFAULT '', read_at TEXT DEFAULT '')""")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications (user_id, id DESC)")
    cur.execute("DELETE FROM notifications WHERE created_at < %s", ((datetime.utcnow() - timedelta(days=90)).strftime("%Y-%m-%d %H:%M"),))
    cur.execute(
        """CREATE TABLE IF NOT EXISTS vessels (
            name TEXT PRIMARY KEY,
            mmsi TEXT DEFAULT '',
            updated_by TEXT DEFAULT '',
            updated_at TEXT DEFAULT ''
        )"""
    )
    # "operator" is set once, when the vessel is first added, and never
    # overwritten afterward - it's whoever entered the vessel originally.
    cur.execute("ALTER TABLE vessels ADD COLUMN IF NOT EXISTS operator TEXT DEFAULT ''")
    # Direct Delivery Classifier - its own table, completely separate from
    # DO Tracker's records. A BL gets a row here the moment it's classified,
    # whether or not it's ever been on the DO Tracker board.
    cur.execute(
        """CREATE TABLE IF NOT EXISTS direct_delivery (
            bl_number TEXT PRIMARY KEY,
            is_direct INTEGER NOT NULL,
            reason TEXT DEFAULT '',
            classified_by TEXT DEFAULT '',
            classified_at TEXT DEFAULT ''
        )"""
    )
    # needs_review: the classifier flags a BL instead of silently trusting
    # a shaky read - a value close enough to the 30MT/12m line that a small
    # parsing slip could flip the verdict, a header where more than one
    # column plausibly looked like "the" weight column, or a weight so
    # large it got dropped by the sanity cap rather than risk misreading
    # it. None of these mean the answer is wrong - just that it's worth a
    # human glance rather than blind trust.
    cur.execute("ALTER TABLE direct_delivery ADD COLUMN IF NOT EXISTS needs_review INTEGER DEFAULT 0")
    cur.execute("ALTER TABLE direct_delivery ADD COLUMN IF NOT EXISTS review_note TEXT DEFAULT ''")

    # Invoice / Delivery Order file attachments - one PDF per BL per kind
    # ('invoice' or 'do'), stored as bytea rather than on disk because
    # Render's app filesystem isn't persistent across deploys/restarts, but
    # Postgres already is. ON CONFLICT (bl_number, kind) lets a re-upload
    # simply replace the previous file (correcting a mistake) instead of
    # piling up duplicates. CASCADE so deleting a BL cleans up its files too.
    cur.execute(
        """CREATE TABLE IF NOT EXISTS record_attachments (
            id SERIAL PRIMARY KEY,
            bl_number TEXT NOT NULL REFERENCES records(bl_number) ON DELETE CASCADE,
            kind TEXT NOT NULL,
            filename TEXT DEFAULT '',
            content_type TEXT DEFAULT 'application/pdf',
            data BYTEA NOT NULL,
            file_size INTEGER DEFAULT 0,
            uploaded_by TEXT DEFAULT '',
            uploaded_at TEXT DEFAULT '',
            UNIQUE (bl_number, kind)
        )"""
    )
    # Holding area for a removed BL's Invoice/DO files. Removing a BL
    # cascade-deletes its attachments, so "Undo" used to bring the row back
    # with its files gone for good (while still showing Invoice/DO as
    # issued). The files are now copied here first and moved back on Undo;
    # anything left unclaimed is purged after 7 days. No foreign key on
    # purpose - the parent record no longer exists while files sit here.
    cur.execute(
        """CREATE TABLE IF NOT EXISTS record_attachments_trash (
            id SERIAL PRIMARY KEY,
            bl_number TEXT NOT NULL,
            kind TEXT NOT NULL,
            filename TEXT DEFAULT '',
            content_type TEXT DEFAULT 'application/pdf',
            data BYTEA NOT NULL,
            file_size INTEGER DEFAULT 0,
            uploaded_by TEXT DEFAULT '',
            uploaded_at TEXT DEFAULT '',
            deleted_by TEXT DEFAULT '',
            deleted_at TEXT DEFAULT ''
        )"""
    )
    cur.execute("CREATE INDEX IF NOT EXISTS idx_attachments_trash_bl ON record_attachments_trash (bl_number)")
    # small picture of a B/L copy's front page, for the hover preview on the board
    cur.execute("ALTER TABLE record_attachments ADD COLUMN IF NOT EXISTS preview BYTEA")

    # PDA / FDA (Proforma / Final Disbursement Account) - a per-port charge
    # template (port dues, pilotage, towage, agency fee, ...) that pre-fills
    # a new PDA for a vessel call; the agent adjusts amounts per vessel.
    # When the vessel sails, the same document is "finalized" into an FDA by
    # filling in actual amounts alongside the original estimate - one record
    # carries both, rather than two documents that can drift apart.
    cur.execute(
        """CREATE TABLE IF NOT EXISTS pda_templates (
            id SERIAL PRIMARY KEY,
            port TEXT NOT NULL,
            name TEXT NOT NULL,
            default_amount NUMERIC DEFAULT 0,
            sort_order INTEGER DEFAULT 0,
            created_at TEXT DEFAULT ''
        )"""
    )
    cur.execute(
        """CREATE TABLE IF NOT EXISTS pda_documents (
            id SERIAL PRIMARY KEY,
            port TEXT DEFAULT '',
            vessel TEXT DEFAULT '',
            reference TEXT DEFAULT '',
            currency TEXT DEFAULT 'SAR',
            status TEXT DEFAULT 'draft',
            notes TEXT DEFAULT '',
            created_by TEXT DEFAULT '',
            created_at TEXT DEFAULT '',
            sent_at TEXT DEFAULT '',
            finalized_by TEXT DEFAULT '',
            finalized_at TEXT DEFAULT ''
        )"""
    )
    cur.execute(
        """CREATE TABLE IF NOT EXISTS pda_line_items (
            id SERIAL PRIMARY KEY,
            pda_id INTEGER NOT NULL REFERENCES pda_documents(id) ON DELETE CASCADE,
            name TEXT NOT NULL,
            estimated_amount NUMERIC DEFAULT 0,
            actual_amount NUMERIC,
            sort_order INTEGER DEFAULT 0
        )"""
    )
    cur.execute("CREATE INDEX IF NOT EXISTS idx_pda_line_items_pda ON pda_line_items (pda_id)")

    # Small generic key/value store - currently just the overdue-ETA alert
    # settings (recipient list + on/off), so it doesn't need its own table
    # and its own migration every time a new setting shows up.
    cur.execute(
        """CREATE TABLE IF NOT EXISTS app_settings (
            key TEXT PRIMARY KEY,
            value TEXT DEFAULT ''
        )"""
    )

    # What Compass has learned about manifests: the layouts it has met, and cargo names people confirmed per consignee.
    cur.execute(
        """CREATE TABLE IF NOT EXISTS mf_layouts (
            fingerprint TEXT PRIMARY KEY, label TEXT DEFAULT '', header TEXT DEFAULT '',
            seen INTEGER DEFAULT 0, first_seen TEXT DEFAULT '', last_seen TEXT DEFAULT '', last_file TEXT DEFAULT '',
            ai_helped INTEGER DEFAULT 0, pkgs_ok INTEGER DEFAULT 0, pkgs_bad INTEGER DEFAULT 0
        )"""
    )
    for _c, _d in (("colmap", "TEXT DEFAULT ''"), ("trusted", "INTEGER DEFAULT 0"), ("trusted_reads", "INTEGER DEFAULT 0"), ("learned_at", "TEXT DEFAULT ''")):
        cur.execute(f"ALTER TABLE mf_layouts ADD COLUMN IF NOT EXISTS {_c} {_d}")
    cur.execute(
        """CREATE TABLE IF NOT EXISTS mf_filecache (
            hash TEXT PRIMARY KEY, data TEXT DEFAULT '', created_at TEXT DEFAULT ''
        )"""
    )
    cur.execute("ALTER TABLE mf_filecache ADD COLUMN IF NOT EXISTS claimed INTEGER DEFAULT 0")
    cur.execute(
        """CREATE TABLE IF NOT EXISTS mf_memory (
            id SERIAL PRIMARY KEY, kind TEXT DEFAULT 'cargo', consignee TEXT DEFAULT '', match_key TEXT DEFAULT '',
            old_value TEXT DEFAULT '', new_value TEXT DEFAULT '', created_by TEXT DEFAULT '', created_at TEXT DEFAULT '',
            uses INTEGER DEFAULT 0
        )"""
    )

    # One shared log of where Compass needed help or learned something, for every feature (the Learning room reads it).
    cur.execute(
        """CREATE TABLE IF NOT EXISTS ai_events (
            id SERIAL PRIMARY KEY, feature TEXT DEFAULT '', kind TEXT DEFAULT '', title TEXT DEFAULT '',
            detail TEXT DEFAULT '', created_at TEXT DEFAULT '', created_by TEXT DEFAULT '', dismissed INTEGER DEFAULT 0
        )"""
    )

    # --- Disbursement Accounts v2: customer/voyage/vessel details, grouped rate x qty charges,
    # USD + SAR totals, automatic PDA numbers. Everything is additive, so existing PDAs stay as they were
    # (each old charge becomes rate = its amount, qty = 1).
    for _col, _ddl in (
        ("pda_no", "TEXT DEFAULT ''"), ("load_port", "TEXT DEFAULT ''"), ("load_code", "TEXT DEFAULT ''"),
        ("dis_port", "TEXT DEFAULT ''"), ("dis_code", "TEXT DEFAULT ''"), ("customer_name", "TEXT DEFAULT ''"),
        ("customer_address", "TEXT DEFAULT ''"), ("customer_phone", "TEXT DEFAULT ''"), ("customer_email", "TEXT DEFAULT ''"),
        ("sales_exec", "TEXT DEFAULT ''"), ("sales_phone", "TEXT DEFAULT ''"), ("sales_email", "TEXT DEFAULT ''"),
        ("load_type", "TEXT DEFAULT ''"), ("term", "TEXT DEFAULT ''"), ("trade", "TEXT DEFAULT ''"), ("operation", "TEXT DEFAULT ''"),
        ("eta", "TEXT DEFAULT ''"), ("receiver", "TEXT DEFAULT ''"), ("cargo_type", "TEXT DEFAULT ''"), ("cargo_note", "TEXT DEFAULT ''"),
        ("updated_at", "TEXT DEFAULT ''"), ("port_stay", "NUMERIC"), ("cargo_frt", "NUMERIC"), ("cargo_units", "NUMERIC"),
        ("grt", "NUMERIC"), ("nrt", "NUMERIC"), ("dwt", "NUMERIC"), ("fx_rate", "NUMERIC DEFAULT 3.75"),
        # quotation-style fields (service type, payment, validity, pricing person, optional sections ...)
        ("service_type", "TEXT DEFAULT ''"), ("lead_no", "TEXT DEFAULT ''"), ("payment_type", "TEXT DEFAULT ''"),
        ("entry_date", "TEXT DEFAULT ''"), ("validity_date", "TEXT DEFAULT ''"), ("pricing_person", "TEXT DEFAULT ''"),
        ("cargo_insurance", "TEXT DEFAULT ''"), ("remarks", "TEXT DEFAULT ''"),
        ("sailing_schedule", "TEXT DEFAULT ''"), ("terms", "TEXT DEFAULT ''"),
    ):
        cur.execute(f"ALTER TABLE pda_documents ADD COLUMN IF NOT EXISTS {_col} {_ddl}")
    # --- Jobs (Compass v2): a job is the PDA number itself. Everything below is additive.
    for _col, _ddl in (
        ("job_stage", "INTEGER DEFAULT 0"), ("appointed_at", "TEXT DEFAULT ''"), ("alongside_at", "TEXT DEFAULT ''"),
        ("sail_date", "TEXT DEFAULT ''"), ("invoiced_at", "TEXT DEFAULT ''"), ("closed_at", "TEXT DEFAULT ''"),
        ("time_bar_days", "INTEGER DEFAULT 60"), ("instructions", "TEXT DEFAULT ''"), ("imo", "TEXT DEFAULT ''"),
        ("voyage", "TEXT DEFAULT ''"), ("principal_ref", "TEXT DEFAULT ''"), ("client_id", "INTEGER"),
        ("one_off", "INTEGER DEFAULT 0"), ("vessel_type", "TEXT DEFAULT ''"), ("flag", "TEXT DEFAULT ''"),
        ("built", "TEXT DEFAULT ''"), ("loa", "NUMERIC"), ("beam", "NUMERIC"), ("call_sign", "TEXT DEFAULT ''"),
    ):
        cur.execute(f"ALTER TABLE pda_documents ADD COLUMN IF NOT EXISTS {_col} {_ddl}")
    cur.execute(
        """CREATE TABLE IF NOT EXISTS pda_clients (
            id SERIAL PRIMARY KEY, name TEXT NOT NULL, operator TEXT DEFAULT '', country TEXT DEFAULT '',
            address TEXT DEFAULT '', phone TEXT DEFAULT '', email TEXT DEFAULT '', contacts TEXT DEFAULT '',
            notes TEXT DEFAULT '', created_by TEXT DEFAULT '', created_at TEXT DEFAULT ''
        )""")
    cur.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_pda_clients_name ON pda_clients (UPPER(name))")
    cur.execute(
        """CREATE TABLE IF NOT EXISTS pda_client_docs (
            id SERIAL PRIMARY KEY, client_id INTEGER NOT NULL REFERENCES pda_clients(id) ON DELETE CASCADE,
            kind TEXT DEFAULT 'other', filename TEXT DEFAULT '', mime TEXT DEFAULT '', data BYTEA,
            uploaded_by TEXT DEFAULT '', uploaded_at TEXT DEFAULT ''
        )""")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_pda_client_docs_client ON pda_client_docs (client_id)")
    cur.execute(
        """CREATE TABLE IF NOT EXISTS pda_vessels (
            id SERIAL PRIMARY KEY, imo TEXT UNIQUE NOT NULL, name TEXT DEFAULT '', vtype TEXT DEFAULT '',
            flag TEXT DEFAULT '', built TEXT DEFAULT '', grt NUMERIC, nrt NUMERIC, dwt NUMERIC, loa NUMERIC,
            beam NUMERIC, call_sign TEXT DEFAULT '', updated_at TEXT DEFAULT ''
        )""")
    cur.execute(
        """CREATE TABLE IF NOT EXISTS pda_history (
            id SERIAL PRIMARY KEY, pda_id INTEGER NOT NULL REFERENCES pda_documents(id) ON DELETE CASCADE,
            at TEXT DEFAULT '', who TEXT DEFAULT '', text TEXT DEFAULT '', doc TEXT DEFAULT ''
        )""")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_pda_history_pda ON pda_history (pda_id)")
    cur.execute(
        """CREATE TABLE IF NOT EXISTS pda_services (
            id SERIAL PRIMARY KEY, pda_id INTEGER NOT NULL REFERENCES pda_documents(id) ON DELETE CASCADE,
            name TEXT NOT NULL, status TEXT DEFAULT 'Requested', cost NUMERIC DEFAULT 0, invoice_no TEXT DEFAULT '',
            note TEXT DEFAULT '', created_by TEXT DEFAULT '', created_at TEXT DEFAULT ''
        )""")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_pda_services_pda ON pda_services (pda_id)")
    cur.execute(
        """CREATE TABLE IF NOT EXISTS pda_invoices (
            id SERIAL PRIMARY KEY, pda_id INTEGER NOT NULL REFERENCES pda_documents(id) ON DELETE CASCADE,
            no TEXT DEFAULT '', kind TEXT DEFAULT 'main', description TEXT DEFAULT '', amount NUMERIC DEFAULT 0,
            paid INTEGER DEFAULT 0, paid_at TEXT DEFAULT '', created_by TEXT DEFAULT '', created_at TEXT DEFAULT ''
        )""")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_pda_invoices_pda ON pda_invoices (pda_id)")
    for _c, _t in (("bill_to", "TEXT DEFAULT ''"), ("bill_address", "TEXT DEFAULT ''"), ("bill_vat_no", "TEXT DEFAULT ''"),
                   ("attention", "TEXT DEFAULT ''"), ("issue_date", "TEXT DEFAULT ''"), ("remarks", "TEXT DEFAULT ''"),
                   ("currency", "TEXT DEFAULT 'SAR'"), ("fx_rate", "NUMERIC DEFAULT 3.75"), ("prepared_by", "TEXT DEFAULT ''"),
                   ("finance_mgr", "TEXT DEFAULT ''"), ("acct_job_no", "TEXT DEFAULT ''"), ("is_draft", "INTEGER DEFAULT 0")):
        cur.execute(f"ALTER TABLE pda_invoices ADD COLUMN IF NOT EXISTS {_c} {_t}")
    cur.execute(
        """CREATE TABLE IF NOT EXISTS pda_invoice_lines (
            id SERIAL PRIMARY KEY, invoice_id INTEGER NOT NULL REFERENCES pda_invoices(id) ON DELETE CASCADE,
            pos INTEGER DEFAULT 0, description TEXT DEFAULT '', unit TEXT DEFAULT '', qty NUMERIC DEFAULT 1,
            rate NUMERIC DEFAULT 0, vat_pct NUMERIC DEFAULT 0
        )""")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_pda_invoice_lines_inv ON pda_invoice_lines (invoice_id)")
    cur.execute(
        """CREATE TABLE IF NOT EXISTS pda_costs (
            id SERIAL PRIMARY KEY, pda_id INTEGER NOT NULL REFERENCES pda_documents(id) ON DELETE CASCADE,
            supplier TEXT DEFAULT '', supplier_inv_no TEXT DEFAULT '', inv_date TEXT DEFAULT '', description TEXT DEFAULT '',
            unit TEXT DEFAULT '', qty NUMERIC DEFAULT 1, rate NUMERIC DEFAULT 0, vat_pct NUMERIC DEFAULT 0,
            paid INTEGER DEFAULT 0, paid_at TEXT DEFAULT '', created_by TEXT DEFAULT '', created_at TEXT DEFAULT ''
        )""")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_pda_costs_pda ON pda_costs (pda_id)")
    cur.execute(
        """CREATE TABLE IF NOT EXISTS pda_job_docs (
            id SERIAL PRIMARY KEY, pda_id INTEGER NOT NULL REFERENCES pda_documents(id) ON DELETE CASCADE,
            title TEXT DEFAULT '', filename TEXT DEFAULT '', mime TEXT DEFAULT '', data BYTEA,
            uploaded_by TEXT DEFAULT '', uploaded_at TEXT DEFAULT ''
        )""")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_pda_job_docs_pda ON pda_job_docs (pda_id)")
    cur.execute("CREATE TABLE IF NOT EXISTS pda_pins (username TEXT NOT NULL, pda_id INTEGER NOT NULL, PRIMARY KEY (username, pda_id))")
    # PDAs made before jobs existed: sent ones are 'Quotation sent', finalized ones are Invoiced; drafts stay stage 0
    cur.execute("SELECT 1 FROM app_settings WHERE key = 'jobs_backfilled'")
    if not cur.fetchone():
        cur.execute("UPDATE pda_documents SET job_stage = 4 WHERE status = 'finalized'")
        cur.execute("INSERT INTO app_settings (key, value) VALUES ('jobs_backfilled', '1') ON CONFLICT (key) DO NOTHING")
    # master list of charge names (the searchable "Charge Description" list); admins can add to it
    cur.execute("CREATE TABLE IF NOT EXISTS pda_charge_catalog (id SERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL)")
    cur.execute("SELECT COUNT(*) FROM pda_charge_catalog")
    _n_catalog = cur.fetchone()[0]
    cur.execute("SELECT 1 FROM app_settings WHERE key = 'pda_catalog_seeded'")
    if _n_catalog == 0 and not cur.fetchone():
        for _nm in PDA_CATALOG_SEED:
            cur.execute("INSERT INTO pda_charge_catalog (name) VALUES (%s) ON CONFLICT (name) DO NOTHING", (_nm,))
        cur.execute("INSERT INTO app_settings (key, value) VALUES ('pda_catalog_seeded', '1') ON CONFLICT (key) DO NOTHING")
    for _col, _ddl in (
        ("group_name", "TEXT DEFAULT 'Port Charges'"), ("unit", "TEXT DEFAULT 'PER SHIPMENT'"), ("currency", "TEXT DEFAULT 'SAR'"),
        ("rate", "NUMERIC"), ("qty", "NUMERIC DEFAULT 1"), ("qty_basis", "TEXT DEFAULT 'fixed'"),
        ("qty_manual", "INTEGER DEFAULT 0"), ("remarks", "TEXT DEFAULT ''"),
    ):
        cur.execute(f"ALTER TABLE pda_line_items ADD COLUMN IF NOT EXISTS {_col} {_ddl}")
    for _col, _ddl in (
        ("group_name", "TEXT DEFAULT 'Port Charges'"), ("unit", "TEXT DEFAULT 'PER SHIPMENT'"), ("currency", "TEXT DEFAULT 'SAR'"),
        ("qty_basis", "TEXT DEFAULT 'fixed'"), ("default_qty", "NUMERIC DEFAULT 1"),
    ):
        cur.execute(f"ALTER TABLE pda_templates ADD COLUMN IF NOT EXISTS {_col} {_ddl}")
    cur.execute(
        "UPDATE pda_line_items li SET currency = CASE WHEN UPPER(d.currency) = 'USD' THEN 'USD' ELSE 'SAR' END, "
        "rate = li.estimated_amount, qty = 1 FROM pda_documents d WHERE d.id = li.pda_id AND li.rate IS NULL"
    )
    cur.execute("UPDATE pda_line_items SET rate = estimated_amount, qty = 1 WHERE rate IS NULL")
    cur.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_pda_no ON pda_documents (pda_no) WHERE pda_no <> ''")
    # number the PDAs made before numbering existed (oldest first)
    cur.execute("SELECT id, created_at FROM pda_documents WHERE pda_no IS NULL OR pda_no = '' ORDER BY id")
    _old = cur.fetchall()
    if _old:
        cur.execute("SELECT value FROM app_settings WHERE key = 'pda_prefix'")
        _r = cur.fetchone()
        _prefix = (_r[0] if _r and _r[0] else "5101")
        _next = {}
        for _id, _created in _old:
            _yy = (_created or "")[2:4] if len(_created or "") >= 4 and (_created or "")[:2] == "20" else datetime.utcnow().strftime("%y")
            if _yy not in _next:
                cur.execute("SELECT pda_no FROM pda_documents WHERE pda_no LIKE %s", (f"{_prefix}/PDA/{_yy}/%",))
                _tails = [x[0].rsplit("/", 1)[-1] for x in cur.fetchall()]
                _next[_yy] = max([int(t) for t in _tails if t.isdigit()] or [0]) + 1
            cur.execute("UPDATE pda_documents SET pda_no = %s WHERE id = %s", (f"{_prefix}/PDA/{_yy}/{_next[_yy]}", _id))
            _next[_yy] += 1
    # a first-time rate card (from Sea Power's own PDA) so a new install isn't empty; never re-added once deleted
    cur.execute("SELECT COUNT(*) FROM pda_templates")
    _n_templates = cur.fetchone()[0]
    cur.execute("SELECT 1 FROM app_settings WHERE key = 'pda_seeded'")
    if _n_templates == 0 and not cur.fetchone():
        _now = datetime.utcnow().strftime("%Y-%m-%d %H:%M")
        for _i, (_grp, _name, _rate, _unit, _basis, _q) in enumerate([
            ("Port Charges", "ARRIVAL/DEPARTURE DUES", 535, "PER SHIPMENT", "fixed", 1),
            ("Port Charges", "GARBAGE COLLECTION DUES", 27, "PER DAY", "days", 1),
            ("Port Charges", "TUG/PILOTAGE/MOORING/UN-MOORING (IN & OUT)", 5027, "PER SHIPMENT", "fixed", 1),
            ("Port Charges", "BERTH HIRE", 535, "PER DAY", "days", 1),
            ("Port Charges", "STEVEDORING CHARGES", 5.35, "PER FRT", "frt", 1),
            ("Port Charges", "ESTIMATED FORKLIFT CHARGES", 10000, "PER SHIPMENT", "fixed", 1),
            ("Port Charges", "LIFTING GEAR CHARGES", 12000, "PER SHIPMENT", "fixed", 1),
            ("Port Charges", "UNITS OVER 03 TONS UPTO 10 TONS", 161, "PER UNIT", "manual", 0),
            ("Port Charges", "UNITS OVER 10 TONS UPTO 40 TONS", 433, "PER UNIT", "manual", 0),
            ("Port Charges", "TRAILERS OVER 40 FEET", 198, "PER UNIT", "manual", 0),
            ("Agency Charges", "AGENCY FEES", 3000, "PER SHIPMENT", "fixed", 1),
            ("Agency Charges", "DOCUMENTATION FOR NATIONAL SECURITY", 150, "PER SHIPMENT", "fixed", 1),
        ]):
            cur.execute(
                "INSERT INTO pda_templates (port, name, default_amount, sort_order, created_at, group_name, unit, currency, qty_basis, default_qty) "
                "VALUES ('YANBU COMMERCIAL PORT', %s, %s, %s, %s, %s, %s, 'USD', %s, %s)",
                (_name, _rate, _i, _now, _grp, _unit, _basis, _q),
            )
        cur.execute("INSERT INTO app_settings (key, value) VALUES ('pda_seeded', '1') ON CONFLICT (key) DO NOTHING")

    # Statement of Facts - one row per vessel call, matching the company's
    # actual SOF template field-for-field (see SOF_COLUMNS) rather than a
    # generic event log, so the PDF this produces is a drop-in replacement
    # for the Word template, not an approximation of it. Every field is
    # plain text (not a real timestamp column) because the source document
    # itself writes times as free text ("26.06.26 AT 0648 HRS") and is
    # routinely saved with some of them still blank while the port call is
    # in progress - a strict datetime type would reject exactly the
    # half-filled state this form normally sits in.
    sof_cols_sql = ",\n            ".join(f"{col} TEXT DEFAULT ''" for col in SOF_COLUMNS)
    cur.execute(
        f"""CREATE TABLE IF NOT EXISTS sof_documents (
            id SERIAL PRIMARY KEY,
            {sof_cols_sql},
            created_by TEXT DEFAULT '',
            created_at TEXT DEFAULT '',
            updated_at TEXT DEFAULT ''
        )"""
    )
    conn.commit()
    cur.close()
    conn.close()


def fmt_money(value):
    try:
        return "{:,.2f}".format(float(value or 0))
    except (TypeError, ValueError):
        return "0.00"


class SafeFPDF(FPDF):
    """FPDF that never crashes on text its built-in font can't draw.

    The PDA/SOF PDFs use fpdf's built-in Helvetica, which only covers
    basic Latin. Plain FPDF raised an exception - and the whole download
    failed - on a single en dash or curly quote pasted from Word, or any
    Arabic word. Two changes:
      - windows-1252 encoding instead of latin-1, so the usual Word
        punctuation (– — ‘ ’ “ ” … • €) prints correctly as-is;
      - anything still outside that (e.g. Arabic) is swapped for "?"
        rather than aborting the document.
    Printing real Arabic would need a bundled Arabic font file."""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.core_fonts_encoding = "windows-1252"

    def normalize_text(self, text):
        if not self.is_ttf_font and self.core_fonts_encoding:
            text = str(text).encode(self.core_fonts_encoding, errors="replace").decode(self.core_fonts_encoding)
        return super().normalize_text(text)


class PdaPDF(SafeFPDF):
    def footer(self):
        self.set_y(-11)
        self.set_font("Helvetica", "B", 8)
        self.set_text_color(40, 40, 40)
        self.cell(0, 5, f"Page {self.page_no()} of {{nb}}", align="R")


def _pda_num(v, places=2):
    try:
        return "{:,.{p}f}".format(float(v or 0), p=places)
    except (TypeError, ValueError):
        return "0.00"


def _pda_qty_text(v):
    f = float(v or 0)
    return "{:,.3f}".format(f)


def build_pda_pdf(doc, items, _pda_calc=None, letterhead="", banks=""):
    """Sea Power's Proforma Disbursement Account (or the Final Disbursement Account once
    finalized): letterhead, From/To, customer, vessel particulars, voyage terms, grouped charges
    (rate x qty, USD and SAR), sub totals per group, grand total, notes and bank details."""
    calc = _pda_calc or _pda_compute(doc, items)
    is_fda = doc.get("status") == "finalized"
    NAVY, GREY, LINE = (18, 58, 86), (120, 130, 140), (214, 220, 226)
    L, W = 12, 186
    pdf = PdaPDF(format="A4")
    pdf.alias_nb_pages()
    pdf.set_auto_page_break(False)
    pdf.set_margins(L, 10, L)
    pdf.add_page()

    def txt(x, y, w, h, s, size=8.5, style="", color=(0, 0, 0), align="L"):
        pdf.set_xy(x, y)
        pdf.set_font("Helvetica", style, size)
        pdf.set_text_color(*color)
        pdf.cell(w, h, str(s), align=align)

    def lines_for(s, w, size, style=""):
        pdf.set_font("Helvetica", style, size)
        out = []
        for para in str(s or "").replace("\r", "").split("\n"):
            out.extend(pdf.multi_cell(w, 4, para or " ", split_only=True) or [""])
        return out or [""]

    def box(x, y, w, h):
        pdf.set_draw_color(120, 135, 150)
        pdf.set_line_width(0.25)
        pdf.rect(x, y, w, h)

    # ---- letterhead
    try:
        pdf.image(io.BytesIO(base64.b64decode(LOGO_B64)), x=L, y=8, w=24)
    except Exception:
        pass
    pdf.set_font("Helvetica", "", 7)
    pdf.set_text_color(70, 80, 90)
    pdf.set_xy(L + 90, 8)
    pdf.multi_cell(W - 90, 3.3, str(letterhead or "").strip()[:600], align="R")

    # ---- title + number
    y = 34
    txt(L, y, 110, 8, "Final Disbursement Account" if is_fda else "Proforma Disbursement Account", 15, "B", (20, 20, 20))
    txt(L + 112, y, 22, 8, "PDA No.", 12, "", GREY)
    txt(L + 134, y, W - 134, 8, doc.get("pda_no") or f"#{doc.get('id', '')}", 12, "B", (20, 20, 20), "R")

    # ---- From / To   |   file date, contact
    y = 44
    box(L, y, 112, 21)
    txt(L + 3, y + 2, 20, 4, "From", 7, "", GREY)
    txt(L + 3, y + 6.5, 52, 4, (doc.get("load_port") or "-").upper()[:34], 8.5)
    txt(L + 3, y + 11.5, 52, 4, (doc.get("load_code") or "").upper(), 7.5, "", GREY)
    txt(L + 60, y + 2, 20, 4, "To", 7, "", GREY)
    to_lines = lines_for((doc.get("dis_port") or doc.get("port") or "-").upper(), 48, 8.5)[:2]
    for i, ln in enumerate(to_lines):
        txt(L + 60, y + 6.5 + i * 4, 48, 4, ln, 8.5)
    txt(L + 60, y + (11.5 if len(to_lines) == 1 else 15), 48, 4, (doc.get("dis_code") or "").upper(), 7.5, "", GREY)
    box(L + 116, y, 70, 21)
    rows = [("File Date", doc.get("file_date") or (doc.get("created_at") or "")[:10]), ("Sales Mngr / Exec", doc.get("sales_exec") or "-"),
            ("Tel / Mob #", doc.get("sales_phone") or ""), ("Email", doc.get("sales_email") or "")]
    try:
        rows[0] = ("File Date", datetime.strptime((doc.get("entry_date") or (doc.get("created_at") or ""))[:10], "%Y-%m-%d").strftime("%d-%b-%Y"))
    except ValueError:
        pass
    for i, (k, v) in enumerate(rows):
        txt(L + 118, y + 1.5 + i * 4.9, 26, 4, k, 7, "", GREY)
        txt(L + 144, y + 1.5 + i * 4.9, 41, 4, str(v)[:34], 7.5)

    # ---- customer (left) / voyage terms (right, tall)
    y = 68
    cust_lines = [(doc.get("customer_name") or "-", "B")]
    for ln in lines_for(doc.get("customer_address") or "", 106, 8):
        if ln.strip():
            cust_lines.append((ln, ""))
    contact = "   ".join(x for x in (("Tel : " + doc["customer_phone"]) if doc.get("customer_phone") else "",
                                      ("Email : " + doc["customer_email"]) if doc.get("customer_email") else "") if x)
    if contact:
        cust_lines.append((contact, ""))
    cust_h = max(24, 8 + 4.2 * len(cust_lines[:7]))
    box(L, y, 112, cust_h)
    txt(L + 3, y + 1.5, 20, 4, "Customer :", 8, "")
    cy = y + 5.5
    for ln, st in cust_lines[:7]:
        txt(L + 3, cy, 106, 4, ln[:70], 8.5 if st else 8, st)
        cy += 4.2
    vy = y + cust_h + 3
    box(L, vy, 112, 29)
    txt(L + 3, vy + 1.5, 40, 4, "Vessel Particulars:", 8.5)
    vp = [("Name:", (doc.get("vessel") or "-").upper()), ("GRT:", _pda_num(doc.get("grt"), 0) if doc.get("grt") else "-"),
          ("NRT:", _pda_num(doc.get("nrt"), 0) if doc.get("nrt") else "-"), ("DWT:", f"{float(doc['dwt']):,.1f}".rstrip("0").rstrip(".") if doc.get("dwt") else "-")]
    for i, (k, v) in enumerate(vp):
        txt(L + 3, vy + 7 + i * 5, 14, 4, k, 7.5, "", GREY)
        txt(L + 18, vy + 7 + i * 5, 90, 4, v, 8.5)
    right_h = cust_h + 3 + 29
    box(L + 116, y, 70, right_h)
    eta_txt = doc.get("eta") or ""
    try:
        eta_txt = datetime.strptime(eta_txt, "%Y-%m-%d").strftime("%d-%b-%Y")
    except ValueError:
        pass
    stay = doc.get("port_stay")
    cargo = (doc.get("cargo_type") or "").strip()
    if doc.get("cargo_frt"):
        cargo = (cargo + " " + _pda_num(doc["cargo_frt"], 0) + " frt").strip()
    if doc.get("cargo_units"):
        cargo += "\n" + _pda_num(doc["cargo_units"], 0) + " units"
    if doc.get("cargo_note"):
        cargo += "\n" + doc["cargo_note"]
    if doc.get("cargo_insurance"):
        cargo += "\nCARGO INSURANCE REQUIRED"
    vt = [("Load Type", doc.get("load_type") or ""), ("Term", doc.get("term") or ""),
          ("Trade", doc.get("trade") or ""), ("Port Stay", (f"{float(stay):g} DAYS") if stay else ""),
          ("Origin", doc.get("operation") or ""), ("ETA", eta_txt), ("Receiver", doc.get("receiver") or "")]
    ry = y + 2
    for k, v in vt:
        txt(L + 118, ry, 22, 4, k, 7, "", GREY)
        txt(L + 141, ry, 44, 4, str(v)[:30], 7.5)
        ry += 5.2
    txt(L + 118, ry, 22, 4, "Cargo Details", 7, "", GREY)
    cy2 = ry
    for ln in lines_for(cargo, 44, 7.5)[:5]:
        txt(L + 141, cy2, 44, 3.8, ln, 7.5)
        cy2 += 3.8

    # ---- charges table
    y = vy + 29 + 6
    route = f"{(doc.get('load_port') or '').upper()} to {(doc.get('dis_port') or doc.get('port') or '').upper()}".strip()
    if is_fda:
        cols = [("#", 7, "L"), ("Charge Description", 66, "L"), ("Charged Per", 25, "L"), ("Cur", 10, "L"),
                ("Estimate", 26, "R"), ("Actual", 26, "R"), ("Variance", 26, "R")]
    else:
        cols = [("#", 7, "L"), ("Charge Description", 46, "L"), ("Charged Per", 27, "L"), ("Cur", 9, "L"), ("Rate", 20, "R"),
                ("Qty.", 18, "R"), ("Total (USD)", 22, "R"), ("Total (SAR)", 24, "R"), ("Remarks", 13, "L")]
    xs = [L]
    for _, w, _a in cols:
        xs.append(xs[-1] + w)

    def table_head(y):
        txt(L, y, 22, 6, "Charges", 10, "B")
        txt(L + 21, y, W - 21, 6, route, 10, "B", (70, 110, 160))
        y += 8
        pdf.set_fill_color(*NAVY)
        pdf.rect(L, y, W, 6.5, "F")
        for (name, w, al), x0 in zip(cols, xs):
            txt(x0 + 1, y + 0.8, w - 2, 5, name, 7, "B", (255, 255, 255), al)
        return y + 8

    def ensure(y, need):
        if y + need > 280:
            pdf.add_page()
            return table_head(10)
        return y

    y = table_head(y)

    def money_cols(usd, sar):
        return _pda_num(usd), _pda_num(sar)

    shown_any = False
    for gi, g in enumerate(calc["groups"], 1):
        src = {i["id"]: i for i in items}
        visible = []
        for line in g["items"]:
            it = src.get(line["id"], {})
            est = float(it.get("estimated_amount") or 0)
            act = it.get("actual_amount")
            if (not is_fda and est == 0) or (is_fda and est == 0 and not float(act or 0)):
                continue                                  # lines with nothing to charge don't print
            visible.append((it, line))
        if not visible:
            continue
        y = ensure(y, 22)
        pdf.set_fill_color(238, 242, 246)
        pdf.rect(L, y - 1, W, 6.5, "F")
        txt(L + 1, y, 8, 4.5, str(gi), 9, "B", NAVY)
        txt(L + 9, y, 100, 4.5, g["name"], 9, "B", NAVY)
        y += 7
        for n, (it, line) in enumerate(visible, 1):
            d_lines = lines_for(it.get("name"), cols[1][1] - 2, 7.5)
            p_lines = lines_for(it.get("unit"), cols[2][1] - 2, 7.5)
            r_lines = lines_for(it.get("remarks"), cols[-1][1] - 2, 7) if not is_fda else [""]
            h = max(len(d_lines), len(p_lines), len(r_lines)) * 3.7 + 2.2
            y = ensure(y, h + 2)
            txt(xs[0] + 1, y + 1, 6, 4, str(n), 7.5)
            for i, ln in enumerate(d_lines):
                txt(xs[1] + 1, y + 1 + i * 3.7, cols[1][1] - 2, 3.7, ln, 7.5)
            for i, ln in enumerate(p_lines):
                txt(xs[2] + 1, y + 1 + i * 3.7, cols[2][1] - 2, 3.7, ln, 7.5)
            txt(xs[3] + 1, y + 1, cols[3][1] - 1, 4, it.get("currency") or "USD", 7.5)
            if is_fda:
                est = float(it.get("estimated_amount") or 0)
                act = it.get("actual_amount")
                act = float(act) if act is not None else est
                var = act - est
                txt(xs[4], y + 1, cols[4][1] - 1, 4, _pda_num(est), 7.5, "", (0, 0, 0), "R")
                txt(xs[5], y + 1, cols[5][1] - 1, 4, _pda_num(act), 7.5, "", (0, 0, 0), "R")
                txt(xs[6], y + 1, cols[6][1] - 1, 4, (("+" if var > 0 else "") + _pda_num(var)) if var else "-", 7.5, "B" if var else "",
                    (190, 60, 50) if var > 0 else ((30, 130, 90) if var < 0 else (0, 0, 0)), "R")
            else:
                txt(xs[4], y + 1, cols[4][1] - 1, 4, _pda_num(it.get("rate")), 7.5, "", (0, 0, 0), "R")
                txt(xs[5], y + 1, cols[5][1] - 1, 4, _pda_qty_text(it.get("qty")), 7.5, "", (0, 0, 0), "R")
                txt(xs[6], y + 1, cols[6][1] - 1, 4, _pda_num(line["usd"]), 7.5, "", (0, 0, 0), "R")
                txt(xs[7], y + 1, cols[7][1] - 1, 4, _pda_num(line["sar"]), 7.5, "", (0, 0, 0), "R")
                for i, ln in enumerate(r_lines):
                    txt(xs[8] + 1, y + 1 + i * 3.7, cols[8][1] - 2, 3.5, ln, 7)
            y += h
            pdf.set_draw_color(*LINE)
            pdf.set_line_width(0.15)
            pdf.line(L, y, L + W, y)
        shown_any = True
        # sub total
        y = ensure(y, 14)
        txt(L + 1, y + 1.5, 40, 4, "SUB TOTAL", 8, "B")
        if is_fda:
            for ci, (key_usd, key_sar) in zip((4, 5, 6), (("est_usd", "est_sar"), ("act_usd", "act_sar"), ("var_usd", "var_sar"))):
                txt(xs[ci], y + 1.5, cols[ci][1] - 1, 4, "USD " + _pda_num(g[key_usd]), 7.5, "B", (0, 0, 0), "R")
                txt(xs[ci], y + 5.6, cols[ci][1] - 1, 4, "SAR " + _pda_num(g[key_sar]), 7.5, "B", (0, 0, 0), "R")
        else:
            txt(L + 100, y + 1.5, W - 100, 4, "USD " + _pda_num(g["est_usd"]), 8, "B", (0, 0, 0), "R")
            txt(L + 100, y + 5.6, W - 100, 4, "SAR " + _pda_num(g["est_sar"]), 8, "B", (0, 0, 0), "R")
        y += 11.5

    if not shown_any:
        txt(L + 1, y, W, 5, "No charges with an amount yet.", 8, "", GREY)
        y += 8

    # ---- grand total
    y = ensure(y, 20)
    pdf.set_draw_color(*NAVY)
    pdf.set_line_width(0.5)
    pdf.line(L, y, L + W, y)
    tot = calc["total"]
    txt(L + 1, y + 2.5, 40, 5, "TOTAL" + (" (ACTUAL)" if is_fda else ""), 10, "B", NAVY)
    if is_fda:
        for ci, (ku, ks) in zip((4, 5, 6), (("est_usd", "est_sar"), ("act_usd", "act_sar"), ("var_usd", "var_sar"))):
            txt(xs[ci], y + 2.5, cols[ci][1] - 1, 4.5, "USD " + _pda_num(tot[ku]), 8, "B", NAVY, "R")
            txt(xs[ci], y + 7, cols[ci][1] - 1, 4.5, "SAR " + _pda_num(tot[ks]), 8, "B", NAVY, "R")
    else:
        txt(L + 100, y + 2.5, W - 100, 5, "USD " + _pda_num(tot["est_usd"]), 10, "B", NAVY, "R")
        txt(L + 100, y + 7.5, W - 100, 5, "SAR " + _pda_num(tot["est_sar"]), 10, "B", NAVY, "R")
    y += 15
    fx_line = f"SAR amounts at an exchange rate of 1 USD = {calc['fx']:g} SAR."
    try:
        fx_line += "   Valid until " + datetime.strptime(doc.get("validity_date") or "", "%Y-%m-%d").strftime("%d-%b-%Y") + "."
    except ValueError:
        pass
    txt(L, y, W, 4, fx_line, 7, "", GREY)
    y += 8

    # ---- notes, sailing schedule, terms + bank details
    notes = str(doc.get("notes") or "").strip()
    bank_lines = [ln for ln in str(banks or "").replace("\r", "").split("\n")]
    need = 8 + (len(lines_for(notes, W, 8)) * 4 if notes else 0) + (len(bank_lines) * 4 + 10 if banks else 0)
    y = ensure(y, min(need, 60))
    txt(L, y, W, 5, "Additional Notes:", 9, "B")
    y += 6
    if notes:
        for ln in lines_for(notes, W, 8):
            y = ensure(y, 5)
            txt(L, y, W, 4, ln, 8)
            y += 4
        y += 3
    for title, key in (("Sailing Schedule:", "sailing_schedule"), ("Terms & Conditions:", "terms")):
        body = str(doc.get(key) or "").strip()
        if not body:
            continue
        y = ensure(y, 14)
        txt(L, y, W, 5, title, 9, "B")
        y += 6
        for ln in lines_for(body, W, 8):
            y = ensure(y, 5)
            txt(L, y, W, 4, ln, 8)
            y += 4
        y += 3
    if str(banks or "").strip():
        y = ensure(y, len(bank_lines) * 4 + 10)
        txt(L, y, W, 5, "Bank Details.", 9, "B")
        y += 6
        for ln in bank_lines:
            if ln.strip():
                pdf.set_font("Helvetica", "", 8)
                pdf.set_text_color(0, 0, 0)
                pdf.set_xy(L, y)
                pdf.cell(W, 4, ln.strip()[:120])
            y += 4

    return bytes(pdf.output(dest="S"))


def _sof_val(doc, key):
    v = (doc.get(key) or "").strip()
    return v if v else "-"


def build_sof_pdf(doc):
    """Mirrors the company's own Statement of Facts template field-for-
    field (see SOF_COLUMNS/SOF_TIMELINE_PAIRS), with the header restyled
    to match the Daily Vessel Line-Up report's look - logo + bold navy
    company name + muted subtitle + a right-aligned date block, under a
    gold divider - rather than the plain centered letterhead the original
    .doc used.

    The body is a real bordered table (fixed column widths, shaded label
    cells), not loose label/value text - an earlier label-left-value-right
    version let label width vary per field ("Anchored" vs. "Pilot Boarded
    (Departure)"), so values never lined up from one row to the next and
    long values (e.g. Owners) could run straight into the next column.
    A bordered grid makes every column's width explicit, so nothing drifts
    regardless of how long any one label or value happens to be."""
    pdf = SafeFPDF(format="A4")
    pdf.set_auto_page_break(auto=True, margin=16)
    pdf.add_page()
    pdf.set_margins(15, 12, 15)
    PAGE_L, PAGE_R = 15, 195
    CONTENT_W = PAGE_R - PAGE_L  # 180mm

    NAVY = (18, 58, 86)
    GOLD = (201, 162, 39)
    MUTED = (110, 120, 130)
    LABEL_FILL = (238, 242, 246)
    LINE = (210, 216, 222)

    try:
        logo_bytes = base64.b64decode(LOGO_B64)
        pdf.image(io.BytesIO(logo_bytes), x=15, y=12, w=18)
    except Exception:
        pass

    pdf.set_xy(37, 13)
    pdf.set_font("Helvetica", "B", 15)
    pdf.set_text_color(*NAVY)
    pdf.cell(130, 7, "SEA POWER FOR MARINE SERVICES CO LTD", new_x=XPos.LMARGIN, new_y=YPos.NEXT)
    pdf.set_x(37)
    pdf.set_font("Helvetica", "B", 10.5)
    pdf.set_text_color(*MUTED)
    pdf.cell(130, 5.5, "Statement of Facts", new_x=XPos.LMARGIN, new_y=YPos.NEXT)
    pdf.set_text_color(0, 0, 0)

    pdf.set_xy(150, 13)
    pdf.set_font("Helvetica", "B", 9)
    pdf.set_text_color(*NAVY)
    pdf.cell(45, 5, "Prepared", align="R", new_x=XPos.LMARGIN, new_y=YPos.NEXT)
    pdf.set_x(150)
    pdf.set_font("Helvetica", "", 9)
    pdf.set_text_color(0, 0, 0)
    pdf.cell(45, 5, str(doc.get("created_at") or "-"), align="R", new_x=XPos.LMARGIN, new_y=YPos.NEXT)

    pdf.set_y(32)
    pdf.set_draw_color(*GOLD)
    pdf.set_line_width(0.6)
    pdf.line(15, pdf.get_y(), 195, pdf.get_y())
    pdf.ln(7)

    ROW_H = 7.2

    def cell(w, text, bold=False, fill=False, align="L", size=9.5):
        pdf.set_font("Helvetica", "B" if bold else "", size)
        pdf.set_text_color(0, 0, 0)
        if fill:
            pdf.set_fill_color(*LABEL_FILL)
        pdf.set_draw_color(*LINE)
        pdf.cell(w, ROW_H, ("  " + text) if align == "L" else text, border=1, align=align, fill=fill)

    def section_heading(text):
        pdf.ln(2)
        pdf.set_font("Helvetica", "B", 11.5)
        pdf.set_text_color(*NAVY)
        pdf.cell(0, 7, text, new_x=XPos.LMARGIN, new_y=YPos.NEXT)
        pdf.set_text_color(0, 0, 0)
        pdf.ln(0.5)

    # ---------- Vessel Particulars ----------
    section_heading("Vessel Particulars")
    LW, VW = 32, (CONTENT_W / 2) - 32
    for pair in (
        [("Vessel", _sof_val(doc, "vessel")), ("Voyage", _sof_val(doc, "voyage"))],
        [("Port", _sof_val(doc, "port")), ("Berth", _sof_val(doc, "berth"))],
    ):
        for label, value in pair:
            cell(LW, label, bold=True, fill=True)
            cell(VW, value)
        pdf.ln(ROW_H)
    # Owners/Charterer get the full row width - registered company names
    # routinely run longer than a shared two-column cell can hold.
    for label, value in [("Owners", _sof_val(doc, "owners")), ("Charterer", _sof_val(doc, "charterer"))]:
        cell(LW, label, bold=True, fill=True)
        cell(CONTENT_W - LW, value)
        pdf.ln(ROW_H)

    # ---------- Event Timeline ----------
    section_heading("Event Timeline")
    TLW, TVW = 44, (CONTENT_W / 2) - 44
    for left_col, left_label, right_col, right_label in SOF_TIMELINE_PAIRS:
        cell(TLW, left_label, bold=True, fill=True)
        cell(TVW, _sof_val(doc, left_col))
        cell(TLW, right_label, bold=True, fill=True)
        cell(TVW, _sof_val(doc, right_col))
        pdf.ln(ROW_H)
    cell(TLW, "Berthed (All Fast)", bold=True, fill=True)
    cell(TVW, _sof_val(doc, "berthed_all_fast"))
    cell(TLW, "Cargo Discharged (Final)", bold=True, fill=True)
    cell(TVW, _sof_val(doc, "cargo_discharge_mtons"))
    pdf.ln(ROW_H)

    # ---------- Remaining On Board - a header row instead of cramming
    # four readings onto one line of "IFO: x  MDO: y  ..." text ----------
    section_heading("Remaining On Board (MT)")
    RLW = 34
    RCW = (CONTENT_W - RLW) / 4
    cell(RLW, "", bold=True, fill=True)
    for h in ["IFO", "MDO", "LUBS", "F/Water"]:
        cell(RCW, h, bold=True, fill=True, align="C")
    pdf.ln(ROW_H)
    cell(RLW, "ROB Arrival", bold=True, fill=True)
    for key in ["rob_arrival_ifo", "rob_arrival_mdo", "rob_arrival_lubs", "rob_arrival_fwater"]:
        cell(RCW, _sof_val(doc, key), align="C")
    pdf.ln(ROW_H)
    cell(RLW, "ROB Departure", bold=True, fill=True)
    for key in ["rob_departure_ifo", "rob_departure_mdo", "rob_departure_lubs", "rob_departure_fwater"]:
        cell(RCW, _sof_val(doc, key), align="C")
    pdf.ln(ROW_H)

    # ---------- Draft ----------
    section_heading("Draft (M)")
    DLW = 34
    DCW = (CONTENT_W - DLW) / 2
    cell(DLW, "", bold=True, fill=True)
    for h in ["Forward", "Aft"]:
        cell(DCW, h, bold=True, fill=True, align="C")
    pdf.ln(ROW_H)
    cell(DLW, "Arrival Draft", bold=True, fill=True)
    cell(DCW, _sof_val(doc, "arrival_draft_fwd"), align="C")
    cell(DCW, _sof_val(doc, "arrival_draft_aft"), align="C")
    pdf.ln(ROW_H)
    cell(DLW, "Departure Draft", bold=True, fill=True)
    cell(DCW, _sof_val(doc, "departure_draft_fwd"), align="C")
    cell(DCW, _sof_val(doc, "departure_draft_aft"), align="C")
    pdf.ln(ROW_H)

    if (doc.get("delays_remarks") or "").strip():
        section_heading("Delays / Remarks")
        pdf.set_font("Helvetica", "", 9.5)
        pdf.multi_cell(0, 6, doc.get("delays_remarks"), new_x=XPos.LMARGIN, new_y=YPos.NEXT)
        pdf.ln(1)

    if (doc.get("masters_remarks") or "").strip():
        section_heading("Master's Remarks")
        pdf.set_font("Helvetica", "", 9.5)
        pdf.multi_cell(0, 6, doc.get("masters_remarks"), new_x=XPos.LMARGIN, new_y=YPos.NEXT)
        pdf.ln(2)

    pdf.ln(8)
    y = pdf.get_y()
    pdf.set_font("Helvetica", "B", 10)
    pdf.set_draw_color(*GOLD)
    pdf.set_line_width(0.6)
    pdf.set_xy(15, y)
    pdf.cell(80, 6, "MASTER", border="T")
    pdf.set_xy(130, y)
    pdf.cell(65, 6, "AGENT", border="T", align="R")

    out = pdf.output(dest="S")
    return bytes(out)


def email_configured():
    return bool(os.environ.get("SMTP_HOST") and os.environ.get("SMTP_USER") and os.environ.get("SMTP_PASSWORD"))


def send_email(to_addrs, subject, body, attachments=None, cc=None, html=None, inline_images=None):
    """Sends through SMTP creds in the environment (SMTP_HOST/PORT/USER/
    PASSWORD/FROM, optional SMTP_FROM_NAME) - nothing is hardcoded here,
    same pattern as DATABASE_URL/APP_SECRET_KEY. Returns (ok, error_message)
    instead of raising, so a missing/misconfigured mail account degrades to
    "not sent" rather than a 500 on whatever triggered it.

    attachments: optional list of (filename, bytes, mime_type).
    Port 465 uses implicit TLS; anything else (587, Office 365 / Google
    Workspace) upgrades with STARTTLS. Either way the server's certificate
    is now VERIFIED (ssl.create_default_context) - the old bare
    starttls() encrypted the connection but accepted any certificate, so
    someone on the network could have posed as the mail server and
    collected the mailbox password."""
    host = os.environ.get("SMTP_HOST", "")
    port = int(os.environ.get("SMTP_PORT", "587") or 587)
    user = os.environ.get("SMTP_USER", "")
    password = os.environ.get("SMTP_PASSWORD", "")
    sender = os.environ.get("SMTP_FROM", user)
    sender_name = os.environ.get("SMTP_FROM_NAME", "Sea Power Marine Services")
    if not email_configured():
        return False, "Email isn't configured yet (SMTP_HOST/SMTP_USER/SMTP_PASSWORD missing)."
    if not to_addrs:
        return False, "No recipient configured."
    try:
        msg = EmailMessage()  # handles UTF-8 (Arabic) subjects, bodies and filenames
        msg["From"] = formataddr((sender_name, sender)) if sender_name else sender
        msg["To"] = ", ".join(to_addrs)
        msg["Subject"] = subject
        cc = [a for a in (cc or []) if a]
        if cc:
            msg["Cc"] = ", ".join(cc)
        msg.set_content(body)
        if html:
            msg.add_alternative(html, subtype="html")
            for cid, img in (inline_images or []):
                msg.get_payload()[-1].add_related(img, "image", "png", cid="<%s>" % cid)
        for fname, data, mime in (attachments or []):
            maintype, _, subtype = (mime or "application/octet-stream").partition("/")
            msg.add_attachment(data, maintype=maintype, subtype=subtype or "octet-stream", filename=fname)
        ctx = ssl.create_default_context()
        if port == 465:
            with smtplib.SMTP_SSL(host, port, timeout=12, context=ctx) as server:
                server.login(user, password)
                server.send_message(msg, from_addr=sender, to_addrs=list(to_addrs) + cc)
        else:
            with smtplib.SMTP(host, port, timeout=12) as server:
                server.starttls(context=ctx)
                server.login(user, password)
                server.send_message(msg, from_addr=sender, to_addrs=list(to_addrs) + cc)
        return True, None
    except smtplib.SMTPAuthenticationError:
        return False, "auth"
    except smtplib.SMTPRecipientsRefused:
        return False, "recipient"
    except ssl.SSLError as e:
        return False, f"secure connection failed ({e.reason or e})"
    except (socket.timeout, TimeoutError, ConnectionError, socket.gaierror, OSError):
        # Couldn't reach the mail server at all - wrong host/port, or the
        # hosting plan blocks outgoing mail (Render's free plan does).
        return False, "unreachable"
    except Exception as e:
        return False, str(e)


def get_setting(key, default=""):
    db = get_db()
    row = db.execute("SELECT value FROM app_settings WHERE key = ?", (key,)).fetchone()
    return row["value"] if row else default


def set_setting(key, value):
    db = get_db()
    db.execute(
        "INSERT INTO app_settings (key, value) VALUES (?, ?) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value",
        (key, value),
    )
    db.commit()


def find_overdue_vessel_groups():
    """A vessel group is overdue once its ETA has passed and at least one
    of its BLs still isn't fully through invoice/approval/DO - the same
    "left" count already shown on the DO Tracker board, just filtered to
    ETA < today and rolled up per port/vessel instead of per BL."""
    db = get_db()
    rows = db.execute(
        "SELECT * FROM records WHERE archived = 0 AND eta != '' ORDER BY port, vessel"
    ).fetchall()
    today = date.today().isoformat()
    groups = {}
    for r in rows:
        if r["eta"] >= today:
            continue
        key = (r["port"], r["vessel"])
        g_ = groups.setdefault(key, {"port": r["port"], "vessel": r["vessel"], "eta": r["eta"], "total": 0, "left": 0})
        g_["total"] += 1
        if not _bl_done(r):
            g_["left"] += 1
    return [g_ for g_ in groups.values() if g_["left"] > 0]


_USERS_SEEN = [0.0]


def any_users_exist():
    if time.time() - _USERS_SEEN[0] < 60:      # people do not disappear between two clicks: one read a minute is enough
        return True
    db = get_db()
    found = db.execute("SELECT 1 FROM users LIMIT 1").fetchone() is not None
    if found:
        _USERS_SEEN[0] = time.time()
    return found


def login_required(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        if not any_users_exist():
            return redirect(url_for("setup"))
        if "user_id" not in session:
            if request.path.startswith("/api/"):
                return jsonify({"error": "Please sign in again.", "error_code": "session_expired"}), 401
            return redirect(url_for("login"))
        return f(*args, **kwargs)
    return wrapper


def _role():
    """The signed-in person's level: owner, manager or staff ('admin' is the old name for the owner)."""
    r = session.get("role")
    return "owner" if r == "admin" else r


def _is_owner():
    return _role() == "owner"


def _oversees():
    """The Owner and the managers: may see history, step a job back, and see a workload breakdown."""
    return _role() in ("owner", "manager")


def _team():
    """Usernames whose records the signed-in person may see and change: None = everyone (the Owner);
    a manager = themselves and the staff who report to them; staff = themselves."""
    if _is_owner():
        return None
    cached = g.get("_team_names")
    if cached is None:
        names = [session.get("username") or ""]
        if _role() == "manager":
            for r in get_db().execute("SELECT username FROM users WHERE manager_id = ?", (session.get("user_id"),)).fetchall():
                names.append(r["username"])
        cached = g._team_names = names
    return cached


def _sees(created_by):
    t = _team()
    return t is None or (created_by or "") in t


def admin_required(f):
    """Kept under its old name: the page or action is for the Owner only."""
    @wraps(f)
    def wrapper(*args, **kwargs):
        if not _is_owner():
            return "Owner only.", 403
        return f(*args, **kwargs)
    return wrapper


