@app.route("/api/users", methods=["POST"])
@login_required
@admin_required
def add_user():
    data = request.get_json(force=True)
    full_name = (data.get("full_name") or "").strip()
    email, email_err = _check_company_email(data.get("email"))
    if email_err:
        return jsonify({"error": email_err}), 400
    username = (data.get("username") or "").strip()
    password = data.get("password", "")
    role = data.get("role", "staff")
    if role == "admin":
        role = "manager"
    if role not in ("manager", "staff"):
        role = "staff"
    db = get_db()
    if not username and email:
        base = _clean_username(full_name)                 # sign in with the name: "ahmed al baity"
        if len(base) < 2:                                 # a name with no Latin letters: fall back to the email name
            base = email.split("@")[0]
        username = _unique_username(db, base)
    if not username or not password:
        return jsonify({"error": "Missing fields"}), 400
    problem = _password_problem(password, username, email, full_name)
    if problem:
        return jsonify({"error": problem, "error_code": "weak_password"}), 400
    if db.execute("SELECT 1 FROM users WHERE LOWER(username) = LOWER(?)", (username,)).fetchone():
        return jsonify({"error": "Username already exists"}), 400
    if email and db.execute("SELECT 1 FROM users WHERE LOWER(email) = LOWER(?)", (email,)).fetchone():
        return jsonify({"error": "That email already has an account."}), 400
    try:
        db.execute(
            "INSERT INTO users (username, password_hash, role, created_at, full_name, email, manager_id, features) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            (username, generate_password_hash(password), role, datetime.utcnow().strftime("%Y-%m-%d %H:%M"), full_name, email,
             _valid_manager_id(db, data.get("manager_id")) if role == "staff" else None,
             _feat_store(data.get("features")) if "features" in data else None),
        )
        db.commit()
    except psycopg2.IntegrityError:
        db.conn.rollback()
        return jsonify({"error": "Username already exists"}), 400
    return jsonify({"ok": True, "username": username})


@app.route("/api/users/<int:user_id>", methods=["PATCH"])
@login_required
@admin_required
def edit_user(user_id):
    data = request.get_json(force=True) or {}
    db = get_db()
    u = db.execute("SELECT * FROM users WHERE id = ?", (user_id,)).fetchone()
    if not u:
        return jsonify({"error": "User not found."}), 404
    sets, vals = [], []
    if "full_name" in data:
        sets.append("full_name = ?"); vals.append((data.get("full_name") or "").strip())
    if "username" in data:
        nu = _clean_username(data.get("username"))
        if len(nu) < 2:
            return jsonify({"error": "Use at least 2 letters or numbers for the username."}), 400
        if db.execute("SELECT 1 FROM users WHERE LOWER(username) = LOWER(?) AND id <> ?", (nu, user_id)).fetchone():
            return jsonify({"error": "That username is already taken."}), 400
        if nu != (u["username"] or ""):
            if _username_in_use(db, u["username"]):
                return jsonify({"error": f"{u['username']} already has records saved under this username, so it can't be renamed."}), 400
            sets.append("username = ?"); vals.append(nu)
            if user_id == session.get("user_id"):
                session["username"] = nu
    if "email" in data:
        email, err = _check_company_email(data.get("email"))
        if err:
            return jsonify({"error": err}), 400
        if email and db.execute("SELECT 1 FROM users WHERE LOWER(email) = LOWER(?) AND id <> ?", (email, user_id)).fetchone():
            return jsonify({"error": "That email already has an account."}), 400
        sets.append("email = ?"); vals.append(email)
    if data.get("password"):
        problem = _password_problem(
            data["password"], u["username"],
            (data.get("email") if "email" in data else u["email"]) or "",
            (data.get("full_name") if "full_name" in data else u["full_name"]) or "",
            u["password_hash"],
        )
        if problem:
            return jsonify({"error": problem, "error_code": "weak_password"}), 400
        sets.append("password_hash = ?"); vals.append(generate_password_hash(data["password"]))
    new_role = data.get("role")
    if new_role == "admin":
        new_role = "manager"
    if new_role in ("manager", "staff"):
        if u["role"] == "owner":
            return jsonify({"error": "The Owner's level can't be changed."}), 400
        if user_id == session.get("user_id") and new_role != u["role"]:
            return jsonify({"error": "You can't change your own role."}), 400
        if new_role != u["role"]:
            sets.append("role = ?"); vals.append(new_role)
            if new_role == "manager":
                sets.append("manager_id = NULL")
            else:                                         # a manager moved down to staff: their team has no manager now
                db.execute("UPDATE users SET manager_id = NULL WHERE manager_id = ?", (user_id,))
    if "manager_id" in data and (new_role if new_role in ("manager", "staff") else u["role"]) == "staff":
        sets.append("manager_id = ?"); vals.append(_valid_manager_id(db, data.get("manager_id")))
    if "features" in data and u["role"] != "owner":
        sets.append("features = ?"); vals.append(_feat_store(data.get("features")))
    if "do_team" in data:
        sets.append("do_team = ?"); vals.append(1 if data.get("do_team") else 0)
    if data.get("reset_2fa"):
        sets += ["totp_secret = ''", "totp_enabled = 0", "totp_last_step = 0", "recovery_codes = ''"]
    if not sets:
        return jsonify({"ok": True})
    db.execute(f"UPDATE users SET {', '.join(sets)} WHERE id = ?", (*vals, user_id))
    if data.get("password") or data.get("reset_2fa"):
        # a new password or authenticator ends every sign-in that person has open
        # (except the admin's own current one, when they change their own password)
        db.execute("DELETE FROM user_sessions WHERE user_id = ? AND id <> ?", (user_id, session.get("sid") or ""))
    db.commit()
    return jsonify({"ok": True})


