# ---------- Invoice / DO file attachments ----------

def _extract_pdf_text(data):
    """All pages' text, concatenated. Fasah's Invoice and Delivery Order
    PDFs are text-layer PDFs (not scans), so pdfplumber's default
    extract_text() - the same approach already used for manifest/packing
    list PDFs elsewhere in this app - reads them cleanly without needing
    OCR."""
    import pdfplumber
    parts = []
    with pdfplumber.open(io.BytesIO(data)) as pdf:
        for page in pdf.pages:
            parts.append(page.extract_text() or "")
    return "\n".join(parts)


_ATT_IMAGE_EXTS = (".jpg", ".jpeg", ".png", ".webp", ".tif", ".tiff")
MAX_BL_UPLOAD_BYTES = 30 * 1024 * 1024        # a B/L scan can be big; it is cut down to its front page on arrival


_BL_PREVIEW_W = 820        # the hover card is 380 px wide: sharp on a high-density screen, light to load


def _bl_preview_jpeg(img):
    """The small picture of a B/L front page shown when hovering the B/L number."""
    from PIL import Image
    prev = img.convert("RGB")
    if prev.width > _BL_PREVIEW_W:
        prev = prev.resize((_BL_PREVIEW_W, max(1, round(prev.height * _BL_PREVIEW_W / prev.width))), Image.LANCZOS)
    pb = io.BytesIO()
    prev.save(pb, "JPEG", quality=80, optimize=True, progressive=True)
    return pb.getvalue()


def _bl_preview_of_pdf(raw):
    """Preview picture straight from a stored B/L copy (always a PDF)."""
    import pypdfium2 as pdfium
    page = pdfium.PdfDocument(raw)[0]
    return _bl_preview_jpeg(page.render(scale=_BL_PREVIEW_W / (page.get_width() or 595)).to_pil())


def _bl_front_page(raw, dpi=200, quality=85):
    """A B/L copy as Compass keeps it: the FRONT PAGE only (the back is the carrier's terms),
    and light. Page 1 is kept exactly as scanned or typed - full original quality - unless it
    is heavy (a high-resolution scan); then it is re-saved at 200 dpi in high-quality JPEG,
    as sharp to read and a fraction of the size (a 10 MB two-page scan comes out under 0.5 MB).
    A small scan is never made bigger. Returns (pdf_bytes, preview_jpeg_bytes)."""
    from PIL import Image, ImageOps
    Image.init()
    if raw[:4] == b"%PDF":
        import pypdfium2 as pdfium
        pdf = pdfium.PdfDocument(raw)
        page = pdf[0]
        typed = len((page.get_textpage().get_text_range() or "").strip()) > 200
        new = pdfium.PdfDocument.new()
        new.import_pages(pdf, [0])
        b = io.BytesIO()
        new.save(b)
        out = b.getvalue()
        preview = _bl_preview_jpeg(page.render(scale=_BL_PREVIEW_W / (page.get_width() or 595)).to_pil())
        if len(out) > (1_500_000 if typed else 600_000):
            img = page.render(scale=dpi / 72).to_pil().convert("RGB")
            rb = io.BytesIO()
            img.save(rb, "PDF", resolution=dpi, quality=quality, optimize=True)
            if len(rb.getvalue()) < len(out):
                out = rb.getvalue()
        return out, preview
    img = ImageOps.exif_transpose(Image.open(io.BytesIO(raw))).convert("RGB")
    if max(img.size) > 2400:
        img.thumbnail((2400, 2400), Image.LANCZOS)
    b = io.BytesIO()
    img.save(b, "PDF", resolution=dpi, quality=quality, optimize=True)
    return b.getvalue(), _bl_preview_jpeg(img)


def _image_to_pdf(raw):
    """A photo or scanned image (e.g. a receipt) as a one-page PDF, so every document opens the same way."""
    from PIL import Image, ImageOps
    Image.init()
    img = ImageOps.exif_transpose(Image.open(io.BytesIO(raw))).convert("RGB")
    if max(img.size) > 2400:
        img.thumbnail((2400, 2400), Image.LANCZOS)
    b = io.BytesIO()
    img.save(b, "PDF", resolution=200, quality=85, optimize=True)
    return b.getvalue()


def _scan_text(raw):
    """Best-effort text of a scanned page (the built-in OCR), to recognise a B/L copy and its number."""
    try:
        from PIL import Image
        if raw[:4] == b"%PDF":
            import pypdfium2 as pdfium
            img = pdfium.PdfDocument(raw)[0].render(scale=200 / 72).to_pil()
        else:
            img = Image.open(io.BytesIO(raw))
            img.load()
        tables, title = _ocr_tables_from_image(img)
        return "\n".join([title or ""] + [" ".join(str(c) for c in row) for t in tables for row in t])
    except Exception:
        return ""


def _pdf_text_head(data, pages=3):
    """Text of the first few pages only. Recognising a document and its B/L number never needs
    more, and a long multi-page scan bundle then reads in a moment instead of seconds."""
    import pdfplumber
    parts = []
    with pdfplumber.open(io.BytesIO(data)) as pdf:
        for page in pdf.pages[:pages]:
            parts.append(page.extract_text() or "")
    return "\n".join(parts)


def _pdf_text_fast(data, pages=3):
    """Same idea as _pdf_text_head, through the PDF engine's own text layer: about twenty
    times quicker on a long typed bundle. Detection tries this first and only falls back to
    the careful reader when it cannot settle the document."""
    import pypdfium2 as pdfium
    pdf = pdfium.PdfDocument(data)
    return "\n".join(pdf[i].get_textpage().get_text_range() or "" for i in range(min(pages, len(pdf))))


def _scan_top_text(raw):
    """Reads only the top-right corner of a scanned page - where a bill of lading prints
    "BILL OF LADING" and its B/L number - with the built-in text reader. A few lines, so it
    takes a fraction of a second instead of reading the whole page. Faint grey print counts."""
    try:
        import numpy as np
        from PIL import Image, ImageOps
        if raw[:4] == b"%PDF":
            import pypdfium2 as pdfium
            img = pdfium.PdfDocument(raw)[0].render(scale=200 / 72).to_pil()
        else:
            img = ImageOps.exif_transpose(Image.open(io.BytesIO(raw)))
            if max(img.size) > 3000:
                img.thumbnail((3000, 3000))
        gray = img.convert("L")
        W, H = gray.size
        G = np.asarray(gray.crop((int(W * 0.42), 0, W, max(1, int(H * 0.13)))))
        paper, dark = float(np.percentile(G, 90)), float(np.percentile(G, 1))
        if paper - dark < 40:
            return ""
        ink = G < dark + (paper - dark) * 0.55
        ink &= ~(ink.mean(axis=1) > 0.35)[:, None]          # ruled lines are not text
        ink &= ~(ink.mean(axis=0) > 0.5)[None, :]
        jobs, gaps = [], []
        _ocr_line_jobs(ink, G, jobs, gaps)
        return "\n".join(_ocr_read_lines(jobs, gaps)) if jobs else ""
    except Exception:
        return ""


_OCR_LOOKALIKE = str.maketrans("OQDILSBZG", "000115826")
# A B/L's title as the scan reader returns it: words often run together ("BILLOFLADING", "B/LNo").
# Used on scanned text only - typed documents keep the stricter _BL_DOC_RE.
_BL_SCAN_RE = re.compile(r"OF\s*LADING|BILL\s*OF\s*L|\bB\s*/?\s*L\s*N[O0]\b")


def _find_bl_in_scan(text, known_bls):
    """B/L numbers read off a scan. The reader can mistake look-alike characters (O for 0,
    Q for O, I for 1...), so a number counts when it equals one of the caller's own B/Ls with
    those characters treated alike. Same [(bl, exact)] shape as _find_bl_in_text."""
    toks = {t.translate(_OCR_LOOKALIKE) for t in re.findall(r"[A-Z0-9]+", _mf_norm(text)) if len(t) >= 5}
    if not toks:
        return []
    found, hits = [], {}
    for bl in known_bls:
        bl_u = (bl or "").strip().upper()
        if not bl_u:
            continue
        members = bl_members(bl_u)
        if bl_u.translate(_OCR_LOOKALIKE) in toks or members[0].translate(_OCR_LOOKALIKE) in toks:
            found.append((bl, True))
        else:
            h = [m for m in members[1:] if m.translate(_OCR_LOOKALIKE) in toks]
            if h:
                found.append((bl, False))
                hits[bl] = h
    return _mf_exact_wins(found, hits)


_RECEIPT_RE = re.compile(r"\bRECEIPT\b|PAYMENT\s+(?:SUCCESSFUL|CONFIRM|COMPLETED)|(?:PAYMENT\s+)?STATUS\s*[:：]?\s*PAID\b|\bPAID\s+SUCCESSFULLY\b")
_BL_DOC_RE = re.compile(r"BILL\s+OF\s+LADING|\bB\s*/\s*L\s+NO\b|SHIPPED\s+ON\s+BOARD|PORT\s+OF\s+LOADING.*PORT\s+OF\s+DISCHARGE", re.S)


def _detect_doc_kind(text, filename=""):
    """Invoice, paid receipt, Delivery Order or B/L copy - from the document's own wording,
    and for a scan with no readable text from its file name."""
    upper = (text or "").upper()
    if _RECEIPT_RE.search(upper) and ("PAID" in upper or "PAYMENT" in upper or "RECEIPT" in upper):
        if "DELIVERY ORDER NUMBER" not in upper and "DELIVERY ORDER SERIAL NUMBER" not in upper:
            return "receipt"
    kind = _detect_fasah_doc_kind(text or "")
    if kind:
        return kind
    if _BL_DOC_RE.search(upper):
        return "bl"
    name = re.sub(r"[^A-Z0-9]+", " ", (filename or "").upper())
    if re.search(r"\bRECEIPT\b|\bPAID\b|\bPAYMENT\b", name):
        return "receipt"
    if re.search(r"\bB ?L\b|\bBILL\b|\bLADING\b|\bOBL\b", name):
        return "bl"
    return None


def _detect_fasah_doc_kind(text):
    """Fasah's Invoice and Delivery Order documents are both fixed
    templates - the user confirmed only the BL number/vessel/amounts
    change between documents of the same kind - so a couple of fixed
    anchor phrases from the real templates reliably tell them apart
    without needing to parse the whole layout. Returns 'invoice', 'do',
    or None if neither anchor is found (an unrecognized/different kind
    of PDF, which gets held for manual review rather than guessed at)."""
    upper = text.upper()
    if "DELIVERY ORDER NUMBER" in upper or "DELIVERY ORDER SERIAL NUMBER" in upper:
        return "do"
    if "FASAH PAY INVOICE" in upper or "INVOICE REF" in upper:
        return "invoice"
    return None


def _find_bl_in_text(text, known_bls):
    """Which of the caller's own BL numbers appear in this document's
    text - matched as a whole token (not a bare substring) so one BL
    number that happens to be a prefix of another (e.g. "BO123" inside
    "BO1234") doesn't produce a false match. A combined board entry
    ("BO26215XJED001-003", "QCLYGJD26/27/28") also matches a document that
    names just one of the B/Ls it covers (see bl_members). Returns
    [(bl, exact)] - exact=False when only such a member matched; the caller
    treats exactly one as a confident auto-match and zero-or-many as
    needing a human to pick."""
    upper = _mf_norm(text)
    tokens = set(re.findall(r"[A-Z0-9]+", upper))

    def present(s):
        if s.isalnum():
            return s in tokens
        return re.search(r"(?<![A-Z0-9])" + re.escape(s) + r"(?![A-Z0-9])", upper) is not None

    found, hits = [], {}
    for bl in known_bls:
        bl_u = (bl or "").strip().upper()
        if not bl_u:
            continue
        members = bl_members(bl_u)
        if present(bl_u) or present(members[0]):
            found.append((bl, True))
        else:
            h = [m for m in members[1:] if present(m)]
            if h:
                found.append((bl, False))
                hits[bl] = h
    return _mf_exact_wins(found, hits)


def _mf_exact_wins(found, hits):
    """A document naming a B/L that has its own line on the board belongs to that line - not also
    to a combined entry whose range happens to include the same number (XT26220RJED026 vs
    XT26220RJED010-27, which is one B/L number in its own right)."""
    exact = {bl_match_key(b) for b, ex in found if ex}
    if not exact:
        return found
    return [(b, ex) for b, ex in found if ex or any(bl_match_key(h) not in exact for h in hits.get(b, []))]


@app.route("/api/attachments/detect", methods=["POST"])
@login_required
def detect_attachment():
    """Reads one dropped PDF and reports what it probably is, without
    saving anything - the frontend's "drop a batch of Invoices/DOs"
    flow calls this once per file, then either auto-uploads it (via the
    existing upload_attachment route, unique kind + unique BL match) or
    shows it for the user to confirm/correct by hand."""
    file = request.files.get("file")
    if not file or not file.filename:
        return jsonify({"error": "No file received."}), 400
    low = file.filename.lower()
    if not (low.endswith(".pdf") or low.endswith(_ATT_IMAGE_EXTS)):
        return jsonify({"error": "Only PDF files or scanned images are supported."}), 400
    data = file.read()
    if not data:
        return jsonify({"error": "That file is empty."}), 400
    if len(data) > MAX_BL_UPLOAD_BYTES:
        return jsonify({"error": "That file is larger than 30MB."}), 400

    text = ""
    if data[:4] == b"%PDF":
        try:
            text = _pdf_text_fast(data)
        except Exception:
            text = ""
    scanned = len(text.strip()) < 40            # a scan or a photo: no text to read
    name_text = re.sub(r"[_#]+", " ", os.path.splitext(file.filename)[0])   # "SURR BL# QCLYGJD14" names its B/L

    # Only match against BLs this user could actually upload to anyway
    # (same scope _owns_record would allow) - no point surfacing a match
    # the uploader isn't permitted to attach to.
    db = get_db()
    if _team() is None:
        bl_rows = db.execute("SELECT bl_number FROM records").fetchall()
    elif _is_do_team():
        bl_rows = db.execute(
            "SELECT bl_number FROM records WHERE created_by = ANY(?) OR " + DO_SEES_SQL, (_team(),)
        ).fetchall()
    else:
        bl_rows = db.execute(
            "SELECT bl_number FROM records WHERE created_by = ANY(?)", (_team(),)
        ).fetchall()
    known_bls = [r["bl_number"] for r in bl_rows]

    # The document's own text and its file name come first - instant. A scan is only read
    # (the slow part) when those two leave the kind or the B/L open, and then just its
    # top-right corner, where a B/L prints its number.
    kind = _detect_doc_kind(text, file.filename)
    found = _find_bl_in_text(text + "\n" + name_text, known_bls)
    if data[:4] == b"%PDF" and not (kind and len(found) == 1):
        try:                                    # an unusual layout: read it the careful way as well
            careful = _pdf_text_head(data)
        except Exception:
            careful = ""
        if careful.strip():
            text = (text + "\n" + careful).strip()
            scanned = len(text.strip()) < 40
            kind = _detect_doc_kind(text, file.filename)
            found = _find_bl_in_text(text + "\n" + name_text, known_bls)
    from_scan = set()
    if scanned and not (kind and len(found) == 1):
        top = _scan_top_text(data)
        if top:
            kind = _detect_doc_kind(text + "\n" + top, file.filename)
            if not kind and _BL_SCAN_RE.search(_mf_norm(top)):
                kind = "bl"
            have = {bl for bl, _ in found}
            for bl, exact in _find_bl_in_scan(top, known_bls):
                if bl not in have:
                    found.append((bl, exact))
                    from_scan.add(bl)
        if not kind:                            # still unknown (e.g. a photo of a receipt): read the whole page
            whole = _scan_text(data)
            kind = _detect_doc_kind(text + "\n" + top + "\n" + whole, file.filename)
            have = {bl for bl, _ in found}
            for bl, exact in _find_bl_in_text(whole, known_bls):
                if bl not in have:
                    found.append((bl, exact))
                    from_scan.add(bl)
    if kind != "bl" and len(data) > MAX_ATTACHMENT_BYTES:
        return jsonify({"error": "That file is larger than 10MB."}), 400
    matches = [bl for bl, _ in found]
    reason = None
    if len(found) == 1 and found[0][0] in from_scan:
        # Read off the scan itself, not from text or the file name: a misread digit could
        # point at a neighbouring B/L, so a person checks it (one click - it is pre-selected).
        reason = "scan_read"
    elif len(found) == 1 and not found[0][1]:
        # Matched only through a combined entry (the document names ONE of
        # the B/Ls it covers, e.g. 001 of "001-003"). Attaching it marks the
        # whole entry issued, so a person confirms instead of it happening
        # automatically - and if the entry already has this kind of file,
        # confirming would replace it, which the message says.
        reason = "member_match"
        if kind and db.execute(
            "SELECT 1 FROM record_attachments WHERE bl_number = ? AND kind = ?", (matches[0], kind)
        ).fetchone():
            reason = "already_attached"

    matched = matches[0] if len(matches) == 1 and not reason else None
    out = {
        "kind": kind,
        "matched_bl": matched,
        "candidates": matches if len(matches) > 1 or reason else [],
        "reason": reason,
    }
    # The batch drop asks to attach a clean match right here, so each file travels once
    # (it used to be sent twice: once to be read, again to be saved).
    if request.form.get("auto") == "1" and kind and matched:
        if not _may_attach(matched, kind):
            out["attach_error"] = "Not your record."
        else:
            payload, status = _store_attachment(db, matched, kind, file.filename, data)
            if status == 200:
                out["attached"] = payload
            else:
                out["attach_error"] = payload.get("error")
    return jsonify(out)


@app.route("/api/records/<path:bl_number>/attachment/<kind>", methods=["POST"])
@login_required
def upload_attachment(bl_number, kind):
    bl_number = bl_number.upper()
    if kind not in ATTACHMENT_KINDS:
        return jsonify({"error": "Invalid attachment kind."}), 400
    if not _may_attach(bl_number, kind):
        return jsonify({"error": "Not your record."}), 403
    file = request.files.get("file")
    if not file or not file.filename:
        return jsonify({"error": "No file was selected."}), 400
    payload, status = _store_attachment(get_db(), bl_number, kind, file.filename, file.read())
    return jsonify(payload), status


def _store_attachment(db, bl_number, kind, file_name, data):
    """Saves one document onto a B/L - shared by the Documents upload and the batch drop
    (which attaches a clean match in the same request it was read in). Returns (payload, status)."""
    low = file_name.lower()
    is_image = low.endswith(_ATT_IMAGE_EXTS)
    if not (low.endswith(".pdf") or (is_image and kind in ("bl", "receipt"))):
        return {"error": "Only PDF files are accepted." if kind in ("invoice", "do") else "Only PDF files or scanned images are accepted."}, 400
    if not data:
        return {"error": "That file is empty."}, 400
    if len(data) > (MAX_BL_UPLOAD_BYTES if kind == "bl" else MAX_ATTACHMENT_BYTES):
        return {"error": "That file is larger than 30MB." if kind == "bl" else "That file is larger than 10MB."}, 400

    preview = None
    filename = file_name
    original_size = len(data)
    if kind == "bl":
        try:
            data, preview = _bl_front_page(data)
        except Exception:
            return {"error": "Could not read this B/L copy. Try a PDF or a clear photo."}, 400
        filename = os.path.splitext(file_name)[0] + ".pdf"
    elif is_image:
        try:
            data = _image_to_pdf(data)
        except Exception:
            return {"error": "Could not read this image."}, 400
        filename = os.path.splitext(file_name)[0] + ".pdf"

    now = datetime.utcnow().strftime("%Y-%m-%d %H:%M")
    user = session.get("username", "Unknown")
    db.execute(
        """INSERT INTO record_attachments (bl_number, kind, filename, content_type, data, file_size, uploaded_by, uploaded_at, preview)
           VALUES (?, ?, ?, 'application/pdf', ?, ?, ?, ?, ?)
           ON CONFLICT (bl_number, kind) DO UPDATE SET
             filename = EXCLUDED.filename, data = EXCLUDED.data, file_size = EXCLUDED.file_size,
             uploaded_by = EXCLUDED.uploaded_by, uploaded_at = EXCLUDED.uploaded_at, preview = EXCLUDED.preview""",
        (bl_number, kind, filename, psycopg2.Binary(data), len(data), user, now, psycopg2.Binary(preview) if preview else None),
    )
    _log_audit(bl_number, "attachment", kind, "", filename)

    # Attaching the file *is* the real-world signal that the invoice/DO was
    # actually issued - no reason to also make someone flip the slider by
    # hand afterward. Only flips the status 0 -> 1 though: if it's already
    # marked issued and this upload is just a Replace (a corrected file),
    # that's not a fresh issuance, so the original by/at stays as-is rather
    # than being silently rewritten to whoever happened to replace the file.
    status_field = {"invoice": "invoice_issued", "do": "do_issued", "receipt": "paid"}.get(kind)
    status_by_at = {"invoice_issued": ("invoice_by", "invoice_at"), "do_issued": ("do_by", "do_at"), "paid": ("paid_by", "paid_at")}
    auto_issued = False
    if status_field:
        by_field, at_field = status_by_at[status_field]
        current = db.execute(f"SELECT {status_field} FROM records WHERE bl_number = ?", (bl_number,)).fetchone()
        if current and not current[status_field]:
            db.execute(
                f"UPDATE records SET {status_field} = 1, {by_field} = ?, {at_field} = ? WHERE bl_number = ?",
                (user, now, bl_number),
            )
            _log_audit(bl_number, "toggle", status_field, "", "1")
            auto_issued = True
        if kind == "receipt":                     # paid, and the receipt is the proof
            db.execute("UPDATE records SET paid_via = 'receipt' WHERE bl_number = ?", (bl_number,))

    if auto_issued and status_field in ("invoice_issued", "do_issued", "paid"):
        _notify_step(db, [bl_number], status_field, via="file")
    if auto_issued and status_field == "paid":
        _after_gate(db, [bl_number], "paid", 1)
    asked = _maybe_request_invoice(db, bl_number, "B/L copy attached") if kind == "bl" else None
    db.commit()
    return {
        "ok": True, "filename": filename, "uploaded_by": user, "uploaded_at": now,
        "auto_issued_field": status_field if auto_issued else None,
        "invoice_requested": asked is not None, "invoice_request_no_team": asked == "no_team",
        "size": len(data), "original_size": original_size,
    }, 200


@app.route("/api/records/<path:bl_number>/bl-preview", methods=["GET"])
@login_required
def bl_preview(bl_number):
    """The small picture of a B/L copy's front page, for the hover card on the board.
    Same access as downloading the file (any signed-in user who has the B/L number)."""
    bl_number = bl_number.upper()
    db = get_db()
    # Only the small picture is read - the stored PDF is pulled only when a picture has to be made again.
    row = db.execute("SELECT preview FROM record_attachments WHERE bl_number = ? AND kind = 'bl'", (bl_number,)).fetchone()
    if not row:
        return "No B/L copy yet.", 404
    pv = bytes(row["preview"]) if row["preview"] else None
    if not pv:                                    # e.g. restored with Undo: make it again
        try:
            full = db.execute("SELECT data FROM record_attachments WHERE bl_number = ? AND kind = 'bl'", (bl_number,)).fetchone()
            pv = _bl_preview_of_pdf(bytes(full["data"]))
            db.execute("UPDATE record_attachments SET preview = ? WHERE bl_number = ? AND kind = 'bl'", (psycopg2.Binary(pv), bl_number))
            db.commit()
        except Exception:
            return "Preview not available.", 404
    # The board asks for it with ?v=<upload time.size>, so a replaced copy gets a new address:
    # the browser can keep this one for a day and re-hovering is instant.
    return Response(pv, mimetype="image/jpeg", headers={"Cache-Control": "private, max-age=86400"})


@app.route("/api/records/<path:bl_number>/attachment/<kind>", methods=["GET"])
@login_required
def download_attachment(bl_number, kind):
    """Deliberately NOT gated by _owns_record - the whole point of this
    feature is the handoff between two different people (whoever issues
    the invoice/DO isn't necessarily who forwards it to the customs
    broker), so any signed-in user who already knows the BL number can
    pull the file, same as the /lookup route below."""
    bl_number = bl_number.upper()
    if kind not in ATTACHMENT_KINDS:
        return "Invalid attachment kind.", 400
    db = get_db()
    row = db.execute(
        "SELECT filename, content_type, data FROM record_attachments WHERE bl_number = ? AND kind = ?",
        (bl_number, kind),
    ).fetchone()
    if not row:
        return "No file attached yet.", 404
    filename = row["filename"] or f"{kind}_{bl_number}.pdf"
    return Response(
        bytes(row["data"]),
        mimetype=row["content_type"] or "application/pdf",
        headers={"Content-Disposition": _content_disposition(filename, f"{kind}_{bl_number}.pdf")},
    )


@app.route("/api/records/<path:bl_number>/attachment/<kind>", methods=["DELETE"])
@login_required
def delete_attachment(bl_number, kind):
    bl_number = bl_number.upper()
    if kind not in ATTACHMENT_KINDS:
        return jsonify({"error": "Invalid attachment kind."}), 400
    if not _owns_record(bl_number):
        return jsonify({"error": "Not your record."}), 403
    db = get_db()
    db.execute("DELETE FROM record_attachments WHERE bl_number = ? AND kind = ?", (bl_number, kind))
    _log_audit(bl_number, "attachment_removed", kind)
    db.commit()
    return jsonify({"ok": True})


@app.route("/api/records/<path:bl_number>/lookup", methods=["GET"])
@login_required
def lookup_record(bl_number):
    """Looks up one BL by its exact number for the Documents popup (the doc
    chips next to a BL's own row). Admins can open any BL; staff only
    their own."""
    bl_number = bl_number.strip().upper()
    if not bl_number:
        return jsonify({"error": "Enter a BL number."}), 400
    # Staff only ever see their own BLs on the board (cross-staff "Find a
    # BL" was removed on purpose), so this must not hand out another
    # user's consignee contacts or tracking link either.
    mine = _owns_record(bl_number)
    if not (mine or _do_access(bl_number)):
        return jsonify({"error": f'No BL found matching "{bl_number}".'}), 404
    db = get_db()
    row = db.execute(
        f"""SELECT bl_number, port, vessel, created_by, importer_no, inv_requested_at, invoice_issued, invoice_by, invoice_at,
                   do_issued, do_by, do_at, paid, paid_via, do_sent, do_sent_via, do_sent_to, do_sent_at,
                   consignee, consignee_email, consignee_phone,
                   broker_email, broker_phone, track_token{ATTACHMENT_FLAGS_SQL}
            FROM records r WHERE bl_number = ?""",
        (bl_number,),
    ).fetchone()
    if not row:
        return jsonify({"error": f'No BL found matching "{bl_number}".'}), 404
    result = dict(row)
    result["do_access"] = not mine           # a B/L the DO team was asked about: they may add the invoice, the receipt and the DO
    token = result.pop("track_token", "") or ""
    result["track_url"] = f"{_public_base_url()}/t/{token}" if token else ""
    result["email_configured"] = email_configured()
    # Attach filename/uploaded_by/uploaded_at per kind too - the has_invoice_file/
    # has_do_file flags above are enough for a status dot, but the Documents
    # modal and the Find-a-BL lookup both want to show who uploaded what and
    # when, not just whether something's there.
    atts = db.execute(
        "SELECT kind, filename, uploaded_by, uploaded_at FROM record_attachments WHERE bl_number = ?",
        (bl_number,),
    ).fetchall()
    result["attachments"] = {a["kind"]: dict(a) for a in atts}
    return jsonify(result)


# ---------- Customer sharing: contacts, tracking link, QR, notifications ----------

# Arabic port names for customer-facing text (the board stores the English,
# upper-case name; matches the DO Tracker's own Arabic labels).
PORT_NAMES_AR = {
    "DAMMAM PORT": "ميناء الدمام",
    "JUBAIL COMMERCIAL PORT": "ميناء الجبيل التجاري",
    "JEDDAH PORT": "ميناء جدة",
    "YANBU COMMERCIAL PORT": "ميناء ينبع التجاري",
    "YANBU INDUSTRIAL PORT": "ميناء ينبع الصناعي",
}
COMPANY_NAME_EN = "Sea Power Marine Services Co. Ltd"
COMPANY_NAME_AR = "شركة سي باور للخدمات البحرية المحدودة"


def _public_base_url():
    """Base URL for links sent to customers. PUBLIC_BASE_URL (env) wins if
    set - e.g. once Compass has its own domain; otherwise the address this
    request came in on. Render terminates HTTPS at its proxy, so the real
    scheme comes from X-Forwarded-Proto, not request.scheme ("http")."""
    env = os.environ.get("PUBLIC_BASE_URL", "").strip().rstrip("/")
    if env:
        return env
    proto = (request.headers.get("X-Forwarded-Proto") or request.scheme or "https").split(",")[0].strip()
    return f"{proto}://{request.host}"


def _ensure_track_tokens(db, bl_numbers):
    """{bl: tracking code} for several B/Ls at once: one read, and a write only for the ones that have no code yet."""
    bls = [b for b in dict.fromkeys(bl_numbers) if b]
    if not bls:
        return {}
    rows = db.execute("SELECT bl_number, track_token FROM records WHERE bl_number = ANY(?)", (bls,)).fetchall()
    out, made = {}, False
    for r in rows:
        tok = r["track_token"]
        if not tok:
            tok = secrets.token_urlsafe(16)
            db.execute("UPDATE records SET track_token = ? WHERE bl_number = ?", (tok, r["bl_number"]))
            made = True
        out[r["bl_number"]] = tok
    if made:
        db.commit()
    return out


def _ensure_track_token(db, bl_number, force_new=False):
    """The BL's tracking code, creating one on first use. 16 random bytes
    (~128 bits) - impossible to guess, so the link itself is the key."""
    row = db.execute("SELECT track_token FROM records WHERE bl_number = ?", (bl_number,)).fetchone()
    if not row:
        return None
    if row["track_token"] and not force_new:
        return row["track_token"]
    token = secrets.token_urlsafe(16)
    db.execute("UPDATE records SET track_token = ? WHERE bl_number = ?", (token, bl_number))
    db.commit()
    return token


@app.route("/api/records/<path:bl_number>/contacts", methods=["POST"])
@login_required
def update_contacts(bl_number):
    bl_number = bl_number.upper()
    if not _owns_record(bl_number):
        return jsonify({"error": "Not your record.", "error_code": "not_owner"}), 403
    data = request.get_json(force=True) or {}
    vals = {}
    for key in ("consignee_email", "broker_email"):
        raw = str(data.get(key) or "").strip()
        if raw and not _clean_email(raw):
            return jsonify({"error": f"That doesn't look like an email address: {raw}", "error_code": "bad_email", "field": key}), 400
        vals[key] = _clean_email(raw)
    for key in ("consignee_phone", "broker_phone"):
        raw = str(data.get(key) or "").strip()
        if raw and not _normalize_phone(raw):
            return jsonify({"error": f"That doesn't look like a phone number: {raw}", "error_code": "bad_phone", "field": key}), 400
        vals[key] = _normalize_phone(raw)
    if "consignee" in data:
        vals["consignee"] = str(data.get("consignee") or "").strip()[:120]
    db = get_db()
    db.execute(
        "UPDATE records SET " + ", ".join(f"{k} = ?" for k in vals) + " WHERE bl_number = ?",
        (*vals.values(), bl_number),
    )
    _log_audit(bl_number, "contacts")
    db.commit()
    return jsonify({"ok": True, **vals})


@app.route("/api/records/<path:bl_number>/share-link", methods=["POST"])
@login_required
def share_link(bl_number):
    """Returns the BL's public tracking link, creating it on first use.
    ?reset=1 replaces it with a new one - the old link stops working
    (use when a link has gone to the wrong person)."""
    bl_number = bl_number.upper()
    if not _owns_record(bl_number):
        return jsonify({"error": "Not your record.", "error_code": "not_owner"}), 403
    db = get_db()
    reset = request.args.get("reset") == "1"
    token = _ensure_track_token(db, bl_number, force_new=reset)
    if not token:
        return jsonify({"error": "BL not found."}), 404
    if reset:
        _log_audit(bl_number, "link_reset")
        db.commit()
    return jsonify({"ok": True, "url": f"{_public_base_url()}/t/{token}"})


@app.route("/api/records/<path:bl_number>/qr", methods=["GET"])
@app.route("/api/records/<path:bl_number>/qr/<fname>", methods=["GET"])
@login_required
def share_qr(bl_number, fname=None):
    """QR code of the tracking link - SVG to show on screen, ?format=png
    (and &download=1) for pasting into a message or printing.
    The second URL form ends in the file name (QR_<BL>.png); fname itself is
    ignored, it is there so that "Save image as..." on the on-screen QR, or
    any other way of saving it, also names the file after the BL - and the
    Download button's Content-Disposition does the same."""
    import segno
    bl_number = bl_number.upper()
    if not _owns_record(bl_number):
        return "Not your record.", 403
    db = get_db()
    token = _ensure_track_token(db, bl_number)
    if not token:
        return "BL not found.", 404
    qr = segno.make(f"{_public_base_url()}/t/{token}", error="m")
    buf = io.BytesIO()
    as_png = request.args.get("format") == "png"
    if as_png:
        qr.save(buf, kind="png", scale=10, border=3)
    else:
        qr.save(buf, kind="svg", scale=6, border=2, dark="#0b2740", xmldecl=False)
    headers = {"Cache-Control": "no-store"}
    if request.args.get("download") == "1":
        headers["Content-Disposition"] = _content_disposition(f"QR_{bl_number}.{'png' if as_png else 'svg'}", "qr.png")
    return Response(buf.getvalue(), mimetype="image/png" if as_png else "image/svg+xml", headers=headers)


def _notify_texts(rec, url):
    """Bilingual (English, then Arabic) customer messages. Formal, plain
    wording - reviewed Arabic should replace this draft if needed."""
    bl, vessel = rec["bl_number"], (rec["vessel"] or "-")
    port_en = (rec["port"] or "-").title()
    port_ar = PORT_NAMES_AR.get((rec["port"] or "").upper(), rec["port"] or "-")
    name = (rec["consignee"] or rec["notify_name"] or "").strip()
    subject = f"Delivery Order Issued - B/L {bl} - {vessel} | تم إصدار أمر التسليم - بوليصة {bl}"
    body = (
        f"Dear {name or 'Valued Customer'},\n\n"
        f"The Delivery Order for the shipment below has been issued and is attached to this email.\n\n"
        f"B/L No.: {bl}\nVessel: {vessel}\nPort of Discharge: {port_en}\n\n"
        f"Track the status of this shipment at any time:\n{url}\n\n"
        f"Regards,\n{COMPANY_NAME_EN}\n\n"
        f"------------------------------------------------------------\n\n"
        f"{('السادة ' + name) if name else 'عميلنا العزيز'}،\n\n"
        f"نفيدكم بأنه تم إصدار أمر التسليم للشحنة الموضحة أدناه، وتجدونه مرفقًا بهذه الرسالة.\n\n"
        f"رقم البوليصة: {bl}\nالسفينة: {vessel}\nميناء التفريغ: {port_ar}\n\n"
        f"يمكنكم متابعة حالة الشحنة في أي وقت عبر الرابط التالي:\n{url}\n\n"
        f"مع أطيب التحيات،\n{COMPANY_NAME_AR}\n"
    )
    if rec["do_issued"]:
        wa = (f"{COMPANY_NAME_EN}: The Delivery Order for B/L {bl} ({vessel}) has been issued. Track the shipment: {url}\n\n"
              f"{COMPANY_NAME_AR}: تم إصدار أمر التسليم للبوليصة {bl} ({vessel}). لمتابعة الشحنة: {url}")
    else:
        wa = (f"{COMPANY_NAME_EN}: Track the status of B/L {bl} ({vessel}) here: {url}\n\n"
              f"{COMPANY_NAME_AR}: لمتابعة حالة البوليصة {bl} ({vessel}): {url}")
    return subject, body, wa


@app.route("/api/records/<path:bl_number>/notify/email", methods=["POST"])
@login_required
def notify_email(bl_number):
    """Emails the attached Delivery Order (plus the tracking link) to the
    BL's consignee and/or broker. Only ever runs on a staff click - nothing
    is sent automatically."""
    bl_number = bl_number.upper()
    if not _owns_record(bl_number):
        return jsonify({"error": "Not your record.", "error_code": "not_owner"}), 403
    data = request.get_json(force=True) or {}
    who = [w for w in (data.get("to") or []) if w in ("consignee", "broker")]
    db = get_db()
    rec = db.execute("SELECT * FROM records WHERE bl_number = ?", (bl_number,)).fetchone()
    if not rec:
        return jsonify({"error": "BL not found."}), 404
    addrs = []
    for w in who:
        e = _clean_email(rec[f"{w}_email"])
        if e and e.lower() not in (a.lower() for a in addrs):
            addrs.append(e)
    if not addrs:
        return jsonify({"error": "Choose at least one recipient with an email address.", "error_code": "no_recipient"}), 400
    att = db.execute(
        "SELECT filename, data FROM record_attachments WHERE bl_number = ? AND kind = 'do'", (bl_number,)
    ).fetchone()
    if not att:
        return jsonify({"error": "Attach the Delivery Order PDF first.", "error_code": "no_do"}), 400
    if not email_configured():
        return jsonify({"error": "Email isn't set up yet.", "error_code": "email_not_configured"}), 400
    token = _ensure_track_token(db, bl_number)
    url = f"{_public_base_url()}/t/{token}"
    subject, body, _ = _notify_texts(rec, url)
    fname = att["filename"] or f"DO_{bl_number}.pdf"
    ok, err = send_email(addrs, subject, body, attachments=[(fname, bytes(att["data"]), "application/pdf")])
    if not ok:
        code = {"unreachable": "email_unreachable", "auth": "email_auth", "recipient": "email_recipient"}.get(err, "send_failed")
        return jsonify({"error": f"The email could not be sent: {err}", "error_code": code}), 502
    _log_audit(bl_number, "notified", "email", "", ", ".join(addrs))
    _mark_do_sent(db, [bl_number], ", ".join(addrs))
    db.commit()
    return jsonify({"ok": True, "sent_to": addrs})


def _mark_do_sent(db, bls, to, via="email"):
    now = datetime.utcnow().strftime("%Y-%m-%d %H:%M")
    for bl in bls:
        db.execute("UPDATE records SET do_sent = 1, do_sent_by = ?, do_sent_at = ?, do_sent_via = ?, do_sent_to = ? WHERE bl_number = ?",
                   (session.get("username", ""), now, via, to[:500], bl))
        _log_audit(bl, "toggle", "do_sent", "", "1")


def _my_email():
    row = get_db().execute("SELECT email FROM users WHERE username = ?", (session.get("username", ""),)).fetchone()
    return _clean_email(row["email"]) if row and row["email"] else ""


def _emails_from(value):
    out = []
    for part in re.split(r"[,;\s]+", str(value or "")):
        e = _clean_email(part)
        if e and e.lower() not in (x.lower() for x in out):
            out.append(e)
    return out


@app.route("/api/records/<path:bl_number>/send-do/draft", methods=["GET"])
@login_required
def send_do_draft(bl_number):
    """What the Send window shows: recipients on file, the message, the DO file."""
    bl_number = bl_number.upper()
    if not _owns_record(bl_number):
        return jsonify({"error": "Not your record.", "error_code": "not_owner"}), 403
    db = get_db()
    rec = db.execute("SELECT * FROM records WHERE bl_number = ?", (bl_number,)).fetchone()
    if not rec:
        return jsonify({"error": "BL not found."}), 404
    att = db.execute("SELECT filename, file_size FROM record_attachments WHERE bl_number = ? AND kind = 'do'", (bl_number,)).fetchone()
    token = _ensure_track_token(db, bl_number)
    subject, body, _ = _notify_texts(rec, f"{_public_base_url()}/t/{token}")
    to = []
    for w in ("consignee", "broker"):
        e = _clean_email(rec[f"{w}_email"])
        if e and e.lower() not in (x["email"].lower() for x in to):
            to.append({"email": e, "who": w, "name": (rec["consignee"] or "") if w == "consignee" else ""})
    return jsonify({"bl": bl_number, "to": to, "cc": [_my_email()] if _my_email() else [], "subject": subject, "body": body,
                    "file": {"name": att["filename"], "size": att["file_size"]} if att else None,
                    "consignee": rec["consignee"] or rec["notify_name"] or "",
                    "email_configured": email_configured(), "sent": bool(rec["do_sent"]), "sent_to": rec["do_sent_to"] or ""})


@app.route("/api/records/<path:bl_number>/send-do", methods=["POST"])
@login_required
def send_do(bl_number):
    """Emails the Delivery Order to the addresses in the Send window and marks the B/L 'DO sent'.
    A new consignee address typed there is kept on the B/L (and in the address book)."""
    bl_number = bl_number.upper()
    if not _owns_record(bl_number):
        return jsonify({"error": "Not your record.", "error_code": "not_owner"}), 403
    data = request.get_json(force=True) or {}
    db = get_db()
    rec = db.execute("SELECT * FROM records WHERE bl_number = ?", (bl_number,)).fetchone()
    if not rec:
        return jsonify({"error": "BL not found."}), 404
    if data.get("manual"):                        # sent outside Compass (WhatsApp, by hand)
        _mark_do_sent(db, [bl_number], "", via="manual")
        db.commit()
        return jsonify({"ok": True, "manual": True})
    to = _emails_from(" ".join(data.get("to") or []))
    cc = [e for e in _emails_from(" ".join(data.get("cc") or [])) if e.lower() not in (x.lower() for x in to)]
    if not to:
        return jsonify({"error": "Add the consignee's email address.", "error_code": "no_recipient"}), 400
    att = db.execute("SELECT filename, data FROM record_attachments WHERE bl_number = ? AND kind = 'do'", (bl_number,)).fetchone()
    if not att:
        return jsonify({"error": "Attach the Delivery Order PDF first.", "error_code": "no_do"}), 400
    if not email_configured():
        return jsonify({"error": "Email isn't set up yet.", "error_code": "email_not_configured"}), 400
    token = _ensure_track_token(db, bl_number)
    d_subject, d_body, _ = _notify_texts(rec, f"{_public_base_url()}/t/{token}")
    subject = re.sub(r"[\r\n]+", " ", str(data.get("subject") or "").strip())[:300] or d_subject
    body = str(data.get("body") or "").strip()[:20000] or d_body
    ok, err = send_email(to, subject, body, attachments=[(att["filename"] or f"DO_{bl_number}.pdf", bytes(att["data"]), "application/pdf")], cc=cc or None)
    if not ok:
        code = {"unreachable": "email_unreachable", "auth": "email_auth", "recipient": "email_recipient"}.get(err, "send_failed")
        return jsonify({"error": f"The email could not be sent: {err}", "error_code": code}), 502
    if not _clean_email(rec["consignee_email"]) and not _clean_email(rec["broker_email"]):
        db.execute("UPDATE records SET consignee_email = ? WHERE bl_number = ?", (to[0], bl_number))
        name = rec["consignee"] or rec["notify_name"]
        if name:
            try:
                _book_save(db, name, email=to[0], only_fill=True)
            except Exception:
                pass
    _log_audit(bl_number, "notified", "email", "", ", ".join(to))
    _mark_do_sent(db, [bl_number], ", ".join(to))
    db.commit()
    return jsonify({"ok": True, "sent_to": to})


@app.route("/api/do/send-batch", methods=["POST"])
@login_required
def send_do_batch():
    """'Send N DOs' on a vessel: every issued, not-yet-sent DO that has its PDF and an email on
    file goes out - one email per consignee, carrying all of that consignee's DOs."""
    data = request.get_json(force=True) or {}
    bls = [str(b).strip().upper() for b in (data.get("bl_numbers") or []) if str(b).strip()]
    if not email_configured():
        return jsonify({"error": "Email isn't set up yet.", "error_code": "email_not_configured"}), 400
    db = get_db()
    groups, skipped = {}, []
    for bl in bls:
        if not _owns_record(bl):
            continue
        rec = db.execute("SELECT * FROM records WHERE bl_number = ?", (bl,)).fetchone()
        if not rec or not rec["do_issued"] or rec["do_sent"]:
            continue
        att = db.execute("SELECT filename, data FROM record_attachments WHERE bl_number = ? AND kind = 'do'", (bl,)).fetchone()
        to = [e for e in (_clean_email(rec["consignee_email"]), _clean_email(rec["broker_email"])) if e]
        if not att:
            skipped.append({"bl": bl, "reason": "no_do"})
            continue
        if not to:
            skipped.append({"bl": bl, "reason": "no_email"})
            continue
        groups.setdefault(tuple(sorted({e.lower() for e in to})), []).append((rec, att, to))
    cc = [_my_email()] if _my_email() else None
    sent, failed = [], []
    for key, items in groups.items():
        recs = [r for r, _, _ in items]
        to = items[0][2]
        if len(items) == 1:
            rec = recs[0]
            token = _ensure_track_token(db, rec["bl_number"])
            subject, body, _ = _notify_texts(rec, f"{_public_base_url()}/t/{token}")
        else:
            vessel = recs[0]["vessel"] or "-"
            lines = "\n".join(f"  - {r['bl_number']}: {_public_base_url()}/t/{_ensure_track_token(db, r['bl_number'])}" for r in recs)
            subject = f"Delivery Orders Issued - {len(recs)} B/Ls - {vessel} | تم إصدار أوامر التسليم"
            name = (recs[0]["consignee"] or recs[0]["notify_name"] or "").strip()
            body = (f"Dear {name or 'Valued Customer'},\n\n"
                    f"The Delivery Orders for the shipments below, ex {vessel}, have been issued and are attached to this email.\n\n"
                    f"{lines}\n\nRegards,\n{COMPANY_NAME_EN}\n\n"
                    f"------------------------------------------------------------\n\n"
                    f"{('السادة ' + name) if name else 'عميلنا العزيز'}،\n\n"
                    f"نفيدكم بأنه تم إصدار أوامر التسليم للشحنات الموضحة أعلاه، وتجدونها مرفقة بهذه الرسالة.\n\n"
                    f"مع أطيب التحيات،\n{COMPANY_NAME_AR}\n")
        files = [(a["filename"] or f"DO_{r['bl_number']}.pdf", bytes(a["data"]), "application/pdf") for r, a, _ in items]
        ok, err = send_email(to, subject, body, attachments=files, cc=cc)
        if ok:
            for r in recs:
                _log_audit(r["bl_number"], "notified", "email", "", ", ".join(to))
            _mark_do_sent(db, [r["bl_number"] for r in recs], ", ".join(to))
            sent += [r["bl_number"] for r in recs]
        else:
            failed += [{"bl": r["bl_number"], "reason": err or "send_failed"} for r in recs]
    db.commit()
    return jsonify({"ok": True, "sent": sent, "skipped": skipped, "failed": failed, "emails": len([1 for k in groups])})


@app.route("/api/records/<path:bl_number>/notify/whatsapp", methods=["POST"])
@login_required
def notify_whatsapp(bl_number):
    """Builds the wa.me link (WhatsApp opens with the message ready - the
    staff member presses Send from their own WhatsApp) and records it in
    the BL's history. No WhatsApp Business account needed for this."""
    bl_number = bl_number.upper()
    if not _owns_record(bl_number):
        return jsonify({"error": "Not your record.", "error_code": "not_owner"}), 403
    who = (request.get_json(force=True) or {}).get("to")
    if who not in ("consignee", "broker"):
        return jsonify({"error": "Invalid recipient."}), 400
    db = get_db()
    rec = db.execute("SELECT * FROM records WHERE bl_number = ?", (bl_number,)).fetchone()
    if not rec:
        return jsonify({"error": "BL not found."}), 404
    phone = _normalize_phone(rec[f"{who}_phone"])
    if not phone:
        return jsonify({"error": "No phone number saved for that contact.", "error_code": "no_phone"}), 400
    token = _ensure_track_token(db, bl_number)
    _, _, text = _notify_texts(rec, f"{_public_base_url()}/t/{token}")
    _log_audit(bl_number, "notified", "whatsapp", "", phone)
    db.commit()
    return jsonify({"ok": True, "url": f"https://wa.me/{phone.lstrip('+')}?text={url_quote(text, safe='')}"})


