# ---------- Port line-ups: daily line-ups, berth plan by draft, port comparison ----------
# The three ports whose line-ups Sea Power receives. Each line-up upload is kept as a
# dated snapshot, so Compass can show what changed since the day before and learn the
# real waiting times. The berth plan is worked out by "simulating" the queue: vessels
# alongside keep their berth until they sail, then waiting vessels take the first free
# berth that accepts their draft, in arrival order.

LINEUP_PORTS = [
    ("JED", "Jeddah", "Jeddah Islamic Port"),
    ("YNB", "Yanbu", "Yanbu Commercial Port"),
    ("DMM", "Dammam", "King Abdulaziz Port Dammam"),
]
_LU_PORT = {k: (short, full) for k, short, full in LINEUP_PORTS}
_LU_SHOWN = [x for x in LINEUP_PORTS if x[0] in ("JED", "YNB")]       # Sea Power works Jeddah and Yanbu only
# Sailing time between the ports in days at about 12 knots (Jeddah-Yanbu ~190 nm;
# the Red Sea ports to Dammam go round the Arabian Peninsula, ~2,500-2,650 nm).
_LU_TRANSIT_DAYS = {("JED", "YNB"): 0.7, ("JED", "DMM"): 8.7, ("YNB", "DMM"): 9.2}
# Discharge rates used to estimate days alongside (MT per day), by cargo family.
_LU_RATES = {"steel": 4000, "bagged": 3500, "bulk": 6000, "project": 1200, "pulp": 3000, "wood": 1500, "general": 2500}
_LU_RATE_LABEL = {"steel": "Steel", "bagged": "Bagged cargo", "bulk": "Bulk", "project": "Project cargo", "pulp": "Wood pulp and paper",
                  "wood": "MDF and timber", "general": "General cargo"}
# Where a port's real pace is known it starts from that instead of the general figures above (tonnes a day, read from the
# ROB falling on the Jeddah line-ups of October 2026); learning from later line-ups takes over from there.
_LU_PORT_RATES = {"JED": {"steel": 1700, "bagged": 2000, "bulk": 3500, "project": 800, "pulp": 2800, "wood": 800, "general": 1500}}
_LU_TURNAROUND = timedelta(hours=6)     # one ship sails, the next is piloted in and made fast
_LU_CAT_STAY = {"roro": 1.5, "livestock": 1.0, "liquid": 2.0, "container": 1.5}   # days alongside when the line-up gives no tonnage
_LU_DRAFT_TIGHT = 0.3   # metres of margin under the berth limit that we call "tight"


def _lu_transit(a, b):
    if a == b:
        return 0.0
    return _LU_TRANSIT_DAYS.get((a, b)) or _LU_TRANSIT_DAYS.get((b, a)) or 0.0


def _lu_now():
    return datetime.utcnow() + timedelta(hours=3)


def _lu_cargo_family(text):
    t = (text or "").upper()
    if re.search(r"STEEL|COIL|PIPE|BILLET|PLATE|REBAR|BEAM|WIRE ROD|H-?BEAM|SLAB|TUBE|ANGLE|CHANNEL|IRON", t):
        return "steel"
    if re.search(r"PULP|PAPER|NEWSPRINT|TISSUE", t):
        return "pulp"
    if re.search(r"\bMDF\b|\bHDF\b|PLY\s*WOOD|\bPLY\b|TIMBER|LUMBER|\bWOOD\b|CHIPBOARD|PARTICLE\s*BOARD", t):
        return "wood"
    if re.search(r"BAG|RICE|SUGAR|FLOUR|FERTILI[SZ]ER|CEMENT IN|SACK", t):
        return "bagged"
    if re.search(r"PROJECT|HEAVY|MACHIN|EQUIPMENT|TRANSFORMER|VEHICLE|RO-?RO|UNIT", t):
        return "project"
    if re.search(r"\bBULK\b|CLINKER|GRAIN|WHEAT|BARLEY|CORN|MAIZE|SOYA|SULPHUR|UREA|COAL", t):
        return "bulk"
    return "general"


_LU_MONTHS = {m: i for i, m in enumerate(["JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"], 1)}


def _lu_parse_dt(s, ref):
    """A date/time from a line-up cell, read day-first (Saudi style). Returns a datetime or None.
    ref (a date) supplies the year when the cell leaves it out."""
    s = re.sub(r"\s+", " ", str(s or "").replace("\n", " ")).strip().upper()
    s = re.sub(r"(\d)\s*([-/.])\s*(\d)", r"\1\2\3", s)                      # '22 -10' -> '22-10'
    s = re.sub(r"\b(\d{1,2}[-/.]\d{1,2}[-/.]\d{2})(\d{2}:\d{2})", r"\1 \2", s)   # '28-10-2600:00' (scan) -> '28-10-26 00:00'
    s = re.sub(r"(?<!\d)(\d{1,2}):(\d{1,2}):(20\d{2})(?!\d)", r"\1/\2/\3", s)   # '24:10:2026 16:30' (RSGT) -> '24/10/2026 16:30'
    s = s.replace(".", "/")
    if not s or s in ("-", "--", "N/A", "NA", "TBA", "TBC", "NIL"):
        return None
    m = re.match(r"^(\d{4})[-/](\d{1,2})[-/](\d{1,2})(?:[T ](\d{1,2}):(\d{2}))?", s)
    if m:
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        hh, mm = int(m.group(4) or 12), int(m.group(5) or 0)
        try:
            return datetime(y, mo, d, hh, mm)
        except ValueError:
            return None
    t = re.search(r"(\d{1,2})[:H](\d{2})", s)
    hh, mm = (int(t.group(1)), int(t.group(2))) if t and int(t.group(1)) < 24 else (12, 0)
    s_dates = re.sub(r"(\d{1,2})[:H](\d{2})(?:\s*(?:HRS|HR|LT))?", " ", s)
    m = re.search(r"(\d{1,2})[/\-\s]?([A-Z]{3})[A-Z]*[/\-\s,]*(\d{2,4})?", s_dates)
    if m and m.group(2) in _LU_MONTHS:
        d, mo = int(m.group(1)), _LU_MONTHS[m.group(2)]
        y = int(m.group(3)) if m.group(3) else ref.year
    else:
        m = re.search(r"(\d{1,2})[/\-](\d{1,2})(?:[/\-](\d{2,4}))?", s_dates)
        if not m:
            return None
        d, mo = int(m.group(1)), int(m.group(2))
        y = int(m.group(3)) if m.group(3) else ref.year
        if mo > 12 and d <= 12:
            d, mo = mo, d
    if y < 100:
        y += 2000
    try:
        out = datetime(y, mo, d, hh, mm)
    except ValueError:
        return None
    if not (m and m.groups()[-1]):   # no year given: pick the one closest to the line-up date
        if (out.date() - ref).days > 180:
            out = out.replace(year=out.year - 1)
        elif (ref - out.date()).days > 180:
            out = out.replace(year=out.year + 1)
    return out


def _lu_num(s):
    m = re.search(r"-?\d[\d,]*(?:\.\d+)?", str(s or "").replace(" ", ""))
    if not m:
        return None
    try:
        return float(m.group(0).replace(",", ""))
    except ValueError:
        return None


_LU_HEADERS = [
    ("vessel", r"^(?:M\.?V\.?\s*)?(?:VESSEL|VSL|SHIP)(?:'?S)?(?:\s*NAME)?$|^NAME\s*OF\s*(?:THE\s+)?(?:VESSEL|SHIP)$|^VESSEL\s*/\s*VOY"),
    ("vtype", r"^O?\s*(?:VESSEL|VSL|SHIP)\s*TYPE$|^TYPE\s*OF\s*(?:VESSEL|SHIP)$"),
    ("agent", r"AGEN(?:T|TS|CY)(?:\s*NAME)?$|^LOCAL\s+AGENT$"),
    ("manifest", r"^MANIFEST\s*VOL|^CARGO\s*(?:&|AND)\s*(?:QTY|QUANTITY)$"),
    ("cargo", r"^(?:CARGO|COMMODITY|CARGO\s*TYPE|TYPE\s*OF\s*CARGO|CARGO\s*DESC(?:RIPTION)?|DESCRIPTION)$"),
    ("rob", r"^R\.?O\.?B\.?\b"),
    ("qty", r"^(?:QTY|QUANTITY|TONNAGE|TONN|TONS|MT|WEIGHT|CARGO\s*QTY|QTY\s*\(?MT\)?|QUANTITY\s*\(?(?:MT|TONS)\)?|DISCH(?:ARGE)?\s*QTY|TOTAL\s*QTY)$"),
    ("dftloa", r"^(?:DFT|DRAFT|DRAUGHT)\s*/+\s*L\.?O\.?A\.?$"),
    ("loa", r"^L\.?O\.?A\.?(?:\s*\(?M\)?)?$|^LENGTH"),
    ("draft", r"DRAFT|DRAUGHT|^DFT\.?$"),
    ("arrived", r"^E\.?T\.?A\.?\s*/\s*A\.?T\.?A\.?$|^A\.?T\.?A\.?\s*/\s*E\.?T\.?A\.?$|^(?:ARRIVED|ARRIVAL|A\.?T\.?A\.?|ARRIVAL\s+DATE|DATE\s+OF\s+ARRIVAL|ANCHORED|ARR(?:IVAL)?\s*(?:DATE|TIME)?|N\.?O\.?R\.?(?:\s+TENDERED)?)$"),
    ("eta", r"^E\.?T\.?A\.?(?:\s*DATE)?$|^EXPECTED(?:\s+ARRIVAL)?$"),
    ("etb", r"^E\.?T\.?B\.?$|EXPECTED\s+BERTH"),
    ("berth", r"^(?:BERTH|BERTH\s*N(?:O\.?)?|B\.?\s*NO\.?|BTH\.?|QUAY|JETTY)$"),
    ("berthed", r"^(?:BERTHED|BERTHING(?:\s+DATE)?|A\.?T\.?B\.?|ALONGSIDE(?:\s+DATE)?|ALL\s*FAST)$"),
    ("first_line", r"^FIRST\s*LINE"),
    ("etd", r"^(?:E\.?T\.?D\.?|E\.?T\.?S\.?|E\.?T\.?C\.?|EXPECTED\s+(?:SAILING|DEPARTURE|COMPLETION)|SAILING|COMPLETION)$"),
    ("status", r"^(?:STATUS|POSITION|VESSEL\s+STATUS)$"),
    ("remarks", r"^(?:REMARKS?|NOTES?|COMMENTS?)$"),
]


def _lu_header_map(row):
    found = {}
    for i, cell in enumerate(row):
        c = re.sub(r"\s+", " ", str(cell or "")).strip().upper().rstrip(":")
        if not c:
            continue
        for key, pat in _LU_HEADERS:
            if key not in found and re.search(pat, c):
                found[key] = i
                break
    return found


def _lu_section_status(row):
    """A section title row ('Working vessels alongside', 'Vessels at Drifting (presented NOR)',
    'Anchorage Vessels', 'Expected Vessels', Mawani's 'NEXT VESSEL DOCKING')."""
    cells = [str(c or "").strip() for c in row if str(c or "").strip()]
    if len(cells) != 1 or len(cells[0]) > 60:
        return None
    t = re.sub(r"\s+", " ", cells[0].upper())
    if re.search(r"NEXT\s*VESSELS?\s*(?:DOCKING|BERTHING)|NEXT\s*TO\s*BERTH", t):
        return "next"
    if re.search(r"ALONGSIDE|AT\s+BERTH|BERTHED|WORKING", t):
        return "alongside"
    if re.search(r"ANCHOR|WAITING|AWAITING|OUTER|DRIFT|\bNOR\b|ROADS", t):
        return "anchor"
    if re.search(r"EXPECT|ARRIVING|E\.?T\.?A", t):
        return "expected"
    return None


_LU_VACANT = re.compile(r"^(?:VACANT|EMPTY|FREE|NIL|NONE|N/?A|TBA|TBC|-+|\.+|IDLE|NO\s+VESSEL|MAINTENANCE)$")


def _lu_clean_name(raw):
    """'TEN MARS V.052' / 'LITTLE CYGNUS VJX2060E19' / 'M.V. EFFIE' -> 'MV TEN MARS' ... (voyage numbers dropped)."""
    n = re.sub(r"\s+", " ", str(raw or "").replace("\n", " ")).strip().upper()
    n = re.sub(r"^M\s*[./]?\s*[VT]\b[./]?\s*", "", n).strip()
    n = re.sub(r"\s*\((?:EX|VOY)[^)]*\)$", "", n)
    for _ in range(2):
        n = re.sub(r"[\s/]+(?:V(?:OY)?\.?\s?[A-Z0-9]*\d[A-Z0-9]*|VOY\.?\s*[A-Z0-9]+)$", "", n).strip()
    n = re.sub(r"[\s/.,-]+$", "", n)
    return "MV " + n if n else ""


def _lu_name_key(name):
    return re.sub(r"[^A-Z0-9]", "", re.sub(r"^MV\s+", "", str(name or "").upper()))


def _lu_transit_mt(text):
    """'( 2,910 mt transit )' / '( 1,033 mt , 461 pkgs transit )' -> tonnes of transit cargo that stay on board (None when none)."""
    t = re.sub(r"\s+", " ", str(text or "").replace("\n", " "))
    tot = 0.0
    for m in re.finditer(r"\(\s*([\d,]+(?:\.\d+)?)\s*M\.?T\.?S?\b[^()]*TRANSIT[^()]*\)", t, re.I):
        n = _lu_num(m.group(1))
        tot += n or 0.0
    return tot or None


def _lu_manifest(text):
    """'60,659 mt / 13,443 pkgs ( steel , coils , units ) DOC' -> (60659.0, 'steel, coils, units').
    '18150.000mt Bulk SILICA SAND ( export )' -> (18150.0, 'Bulk SILICA SAND')."""
    t = re.sub(r"\s+", " ", str(text or "").replace("\n", " ")).strip()
    if not t:
        return None, ""
    m = re.search(r"(\d[\d,]*(?:\.\d+)?)\s*(?:M\.?T\.?S?|TONS?|TONNES?)\b", t, re.I)
    qty = _lu_num(m.group(1)) if m else None
    noise = r"^(?:IMPORT|EXPORT|TRANSIT|LOAD(?:ING)?|DISCH(?:ARGE)?|MHC|STARBOARD|PORT\s*SIDE|[\d,.\s]*(?:MT|PKGS|PCS|UNITS?)?(?:\s*(?:IMPORT|TRANSIT|EXPORT))?)$"
    parts = [x.strip(" ,") for x in re.findall(r"\(([^()]*)\)", t)]

    def is_noise(x):
        rest = re.sub(r"\b(?:IMPORT|EXPORT|TRANSIT|LOAD(?:ING)?|LOD|DISCH(?:ARGE)?|MHC|STARBOARD|PORT\s*SIDE|STERN\s*RAMP|MT|PKGS?|PCS|UNITS?|UNTS|PLTS)\b|[\d,.\s/+-]", "", x, flags=re.I)
        return not rest or bool(re.search(r"\b(?:JIP|YCP|KFIP|JED|YNB)\b.*\bOR\b", x, re.I))
    parts = [x for x in parts if x and not re.match(noise, x, re.I) and not is_noise(x)]
    if parts:
        cargo = ", ".join(re.sub(r"\s*,\s*", ", ", x) for x in parts)
    else:
        rest = re.sub(r"\d[\d,]*(?:\.\d+)?\s*(?:M\.?T\.?S?|TONS?|TONNES?|PKGS?|PCS|UNITS?)\b\.?", " ", t, flags=re.I)
        rest = re.sub(r"\(.*?\)|\bDOC\b|/", " ", rest)
        cargo = re.sub(r"\s+", " ", rest).strip(" ,-")
    cargo = re.sub(r"\bDOC\b", "", cargo).strip(" ,")
    cargo = re.sub(r"^(?:M\.?T\.?S?|TONS?|PKGS?)\b\s*", "", cargo, flags=re.I).strip(" ,")
    return qty, cargo[:80]


_LU_ORD = {"1ST": 1, "FIRST": 1, "2ND": 2, "SECOND": 2, "3RD": 3, "THIRD": 3, "4TH": 4, "5TH": 5, "6TH": 6}


def _lu_berth_slot(berth):
    """'2(a)' -> ('2', 1); '35(B)' -> ('35', 2); '8/9' -> ('8', 0); '36 / N' -> ('36', 0); 'TBC' -> ('', 0)."""
    t = re.sub(r"\s+", "", str(berth or "").upper())
    if not t or _LU_VACANT.match(t):
        return "", 0
    m2 = re.match(r"^(\d+[A-Z]?)\(\d+[A-Z]?\)$", t)         # '3(34)': lying at 3 (she was at 34 before)
    if m2:
        return m2.group(1), 0
    m = re.search(r"\(([A-H])\)$", t)
    slot = (ord(m.group(1)) - 64) if m else 0
    if m:
        t = t[:m.start()]
    t = re.sub(r"^(?:BERTH|BERTHNO\.?|B\.?|NO\.?|BTH)[-#]?", "", t)
    m = re.match(r"^(\d+[A-Z]?)(?:[/&-].*)?$", t)
    return (m.group(1) if m else t), slot


def _lu_category(vtype, cargo):
    """What kind of ship this is for berth planning: general, bulk, liquid, roro, livestock or container."""
    ty = re.sub(r"\s+", " ", str(vtype or "").upper())
    c = re.sub(r"\s+", " ", str(cargo or "").upper())
    both = ty + " " + c + " " + re.sub(r"[^A-Z]", "", c)     # also without spaces: scans split words ('CON TAINER')
    if re.search(r"CONTAINER|\bCNTR\b|\bTEU", both):
        return "container"
    if re.search(r"RO-?RO|RO-?PAX|RO/RO|VEHICLE CARRIER|\bPCTC\b|CAR CARRIER", both) and not re.search(r"GENERAL", ty):
        return "roro"
    if re.search(r"LIVE\s*STOCK|SHEEP|CATTLE|CAMEL", both):
        return "livestock"
    if re.search(r"LIQUID|TANKER", ty):
        return "liquid"
    if re.search(r"GENERAL|MULTI\s*PURPOSE|\bMPP\b|BREAK\s*BULK", ty):
        return "general"
    if re.search(r"BULK", ty):
        return "bulk"
    if re.search(r"\bOIL\b|ACID|CHEMICAL|\bLPG\b|\bLNG\b|PETROL|DIESEL|GASOIL", c):
        return "liquid"
    if re.search(r"\bBULK\b|^B\.|IRON ORE|CLINKER|GRAIN|WHEAT|BARLEY|\bCORN\b|MAIZE|SOYA|SOYABEAN|UREA|COAL|PETCOKE|SLAG|CONCENTRATE|SAND|BENTONITE|PELLETS|RUTILE|GYPSUM|SULPHUR\b", c) and not re.search(r"BAG|STEEL|GENERAL", c):
        return "bulk"
    return "general"


_LU_CAT_LABEL = {"general": "General cargo", "bulk": "Bulk", "liquid": "Liquid bulk", "roro": "Ro-Ro", "livestock": "Livestock", "container": "Container"}


def _lu_rows_from_tables(tables, ref):
    """Finds the line-up table(s) and turns each vessel row into a dict. Knows the
    RSGT Jeddah/Yanbu layouts (sections, Vessel Type, Manifest Volume, ROB, First Line,
    All Fast, ETC, berth order 2(a)/2(b)) and Mawani's Dammam programme (berthing
    table, NEXT VESSEL DOCKING with 1ST/2ND, DFT/LOA, the 10-day arrivals list)."""
    out = []
    for t in tables:
        rows = t["rows"]
        hmap, section, block = {}, None, []
        blocks = []
        for r in rows:
            sec = _lu_section_status(r)
            if sec:
                section = sec
                continue
            m = _lu_header_map(r)
            if "vessel" in m and len(m) >= 3:          # a header row starts a block
                hmap = m
                continue
            if not hmap:
                continue
            block.append((section, hmap, r))
        for section, hmap, r in block:
            g = lambda k: (r[hmap[k]] if k in hmap and hmap[k] < len(r) else "")
            raw_name = re.sub(r"\s+", " ", str(g("vessel") or "").replace("\n", " ")).strip()
            if not raw_name or len(raw_name) < 3 or not re.search(r"[A-Za-z]", raw_name) or re.match(r"(?i)^(total|nil|none)\b", raw_name):
                continue
            if _LU_VACANT.match(raw_name.upper()):          # 'Vacant | 14 | Live stock': what that berth is for
                bk = _lu_berth_slot(g("berth"))[0]
                vt = re.sub(r"\s+", " ", str(g("vtype") or "")).strip()
                if bk and vt:
                    out.append({"_berth_kind": bk, "cat": _lu_category(vt, "")})
                continue
            name = _lu_clean_name(raw_name)
            if not name:
                continue
            txt = lambda k: re.sub(r"\s+", " ", str(g(k) or "").replace("\n", " ")).strip()
            arrived = _lu_parse_dt(txt("arrived"), ref)
            eta = _lu_parse_dt(txt("eta"), ref)
            berthed = _lu_parse_dt(txt("berthed"), ref)
            first_line = _lu_parse_dt(txt("first_line"), ref)
            etd = _lu_parse_dt(txt("etd"), ref)
            etb = _lu_parse_dt(txt("etb"), ref)
            remarks = txt("remarks")
            status_txt = txt("status").upper()
            berth = re.sub(r"\s+", " ", txt("berth")).upper()
            if _LU_VACANT.match(berth.replace(" ", "")):
                berth = ""
            cargo, qty = txt("cargo"), _lu_num(g("qty"))
            transit = None
            if "manifest" in hmap:
                mq, mc = _lu_manifest(g("manifest"))
                transit = _lu_transit_mt(g("manifest"))
                qty = qty if qty is not None else mq
                cargo = cargo or mc
            draft, loa = _lu_num(g("draft")), _lu_num(g("loa"))
            if "dftloa" in hmap:                          # Mawani 'DFT/LOA': draft over LOA in one cell
                nums = [float(x) for x in re.findall(r"\d+(?:\.\d+)?", str(g("dftloa") or "").replace(",", "."))]
                for x in nums:
                    if x <= 25 and draft is None:
                        draft = x
                    elif x > 25 and loa is None:
                        loa = x
            rem_u = remarks.upper()
            mo = re.search(r"\b(1ST|2ND|3RD|[4-6]TH|FIRST|SECOND|THIRD)\b", rem_u)
            if mo and berth and "(" not in berth:
                berth = f"{berth}({chr(64 + _LU_ORD[mo.group(1)])})"
            if not etd:
                ms = re.search(r"SAIL\w*\s*:?\s*(.+)", rem_u)
                if ms:
                    etd = _lu_parse_dt(ms.group(1), ref)
                elif re.search(r"READY\s*TO\s*SAIL|COMPLETED", rem_u):
                    etd = datetime(ref.year, ref.month, ref.day, 12, 0)
            if re.search(r"ALONGSIDE|BERTHED|WORKING|AT BERTH", status_txt):
                st = "alongside"
            elif re.search(r"ANCHOR|WAIT|AWAIT|OUTER|DRIFT", status_txt):
                st = "anchor"
            elif re.search(r"EXPECT|ETA|ARRIVING", status_txt):
                st = "expected"
            elif section == "next":                       # next to dock: arrived already, or still due
                when = eta or arrived
                st = "anchor" if (when and when.date() <= ref) else "expected"
                if st == "anchor" and not arrived:
                    arrived, eta = when, None
            elif section:
                st = section
            elif berthed or (berth and not etb and berth not in ("-", "TBA")):
                st = "alongside"
            elif arrived:
                st = "anchor"
            elif eta:
                st = "expected"
            else:
                st = "anchor"
            if st == "alongside" and first_line and (not berthed or (":" not in txt("berthed") and berthed.date() == first_line.date())):
                berthed = first_line                      # 'All Fast' given as a date only: the first line has the time
            if st == "expected" and arrived and not eta:
                eta, arrived = arrived, None
            out.append({
                "vessel": name[:80], "agent": txt("agent")[:80], "cargo": cargo[:80], "vtype": txt("vtype")[:40],
                "qty": qty, "loa": loa, "draft": draft, "rob": _lu_num(g("rob")) if "rob" in hmap else None, "transit": transit,
                "arrived": arrived.strftime("%Y-%m-%d %H:%M") if arrived else "",
                "eta": eta.strftime("%Y-%m-%d %H:%M") if eta else "",
                "etb": etb.strftime("%Y-%m-%d %H:%M") if etb else "",
                "berth": berth[:30] if berth not in ("-", "--", "TBA", "TBC", "NIL") else "",
                "berthed": berthed.strftime("%Y-%m-%d %H:%M") if berthed else "",
                "etd": etd.strftime("%Y-%m-%d %H:%M") if etd else "",
                "status": st, "remarks": remarks[:200],
                "_has_fast": "berthed" in hmap or "first_line" in hmap,
            })
    # Listed under 'working alongside' but not made fast yet while another vessel is made fast
    # at that berth: she is waiting outside, next for that berth (e.g. GREEN BULK at Jeddah 35).
    kinds = [r for r in out if "_berth_kind" in r]
    out = [r for r in out if "_berth_kind" not in r]
    fast = {}
    for r in out:
        if r["status"] == "alongside" and r["berthed"]:
            fast.setdefault(_lu_berth_slot(r["berth"])[0], []).append(r)
    for r in out:
        if r["status"] == "alongside" and not r["berthed"] and r.pop("_has_fast", False):
            k, slot = _lu_berth_slot(r["berth"])
            if k and fast.get(k):
                r["status"] = "anchor"
                if not slot:
                    r["berth"] = f"{k}(A)"
        r.pop("_has_fast", None)
    for r in out:   # a draft above 25 m is a typo or the column was mis-read (e.g. it held LOA)
        if r["draft"] and not (2 <= r["draft"] <= 25):
            r["draft"] = None
        if r["rob"] is not None and r["rob"] < 0:
            r["rob"] = None
    return out + kinds


# ---------- reading scanned line-ups (Mawani Dammam sends scans) ----------
# Ruled tables are found from their grid lines (numpy), and the text of each cell is read
# with a PP-OCR recognition model on onnxruntime - no system OCR program is needed, so it
# runs on Render as is (pip: onnxruntime + rapidocr_onnxruntime, which carries the model).
_OCR = {}
_OCR_LOCK = threading.Lock()


_OCR_WHEEL = ("rapidocr-onnxruntime", "1.4.4")      # carries the PP-OCRv4 text-recognition model (Apache-2.0)
_OCR_MODEL_NAME = "ch_PP-OCRv4_rec_infer.onnx"


def _ocr_model_path():
    """Where the text-recognition model is: the installed rapidocr package, a copy next to
    app.py (or OCR_MODEL_PATH), or - the first time a scan is read - downloaded once from
    PyPI (the package's wheel; checked against PyPI's sha256) and kept in a cache folder."""
    import importlib.util
    import tempfile
    try:
        spec = importlib.util.find_spec("rapidocr_onnxruntime")
    except (ImportError, ValueError):
        spec = None
    if spec and spec.submodule_search_locations:
        cand = os.path.join(list(spec.submodule_search_locations)[0], "models", _OCR_MODEL_NAME)
        if os.path.exists(cand):
            return cand
    here = os.path.dirname(os.path.abspath(__file__))
    for cand in (os.environ.get("OCR_MODEL_PATH") or "", os.path.join(here, _OCR_MODEL_NAME),
                 os.path.join(here, "models", _OCR_MODEL_NAME)):
        if cand and os.path.exists(cand):
            return cand
    cache = os.path.join(tempfile.gettempdir(), "compass_ocr")
    target = os.path.join(cache, _OCR_MODEL_NAME)
    if os.path.exists(target) and os.path.getsize(target) > 1_000_000:
        return target
    import urllib.request
    os.makedirs(cache, exist_ok=True)
    name, ver = _OCR_WHEEL
    with urllib.request.urlopen(f"https://pypi.org/pypi/{name}/{ver}/json", timeout=30) as r:
        meta = json.loads(r.read().decode("utf-8"))
    whl = next(u for u in meta["urls"] if u["filename"].endswith(".whl"))
    with urllib.request.urlopen(whl["url"], timeout=120) as r:
        data = r.read()
    if hashlib.sha256(data).hexdigest() != whl["digests"]["sha256"]:
        raise RuntimeError("OCR model download did not match PyPI's checksum")
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        member = next(n for n in z.namelist() if n.endswith("/" + _OCR_MODEL_NAME))
        tmp = target + ".part"
        with open(tmp, "wb") as fh:
            fh.write(z.read(member))
    os.replace(tmp, target)
    return target


class _LuOcrUnavailable(Exception):
    pass


def _ocr_session():
    with _OCR_LOCK:
        if "sess" not in _OCR:
            try:
                import onnxruntime  # noqa: F401
            except ImportError:
                raise _LuOcrUnavailable("onnxruntime is not installed")
            try:
                _ocr_model_path()
            except Exception as exc:
                raise _LuOcrUnavailable(f"text model unavailable: {exc}")
            import onnxruntime as ort
            import numpy as np
            path = _ocr_model_path()
            so = ort.SessionOptions()
            so.intra_op_num_threads = 2
            sess = ort.InferenceSession(path, so, providers=["CPUExecutionProvider"])
            chars = sess.get_modelmeta().custom_metadata_map["character"].splitlines()
            _OCR["chars"] = ["<blank>"] + chars + [" "]
            _OCR["ascii"] = np.array([i == 0 or (len(c) == 1 and 33 <= ord(c) < 127) for i, c in enumerate(_OCR["chars"])])
            _OCR["sess"] = sess
        return _OCR["sess"]


def _ocr_groups(mask, gap=0):
    """Runs of True in a 1-D array -> [(start, end)], allowing `gap` missing items inside a run."""
    import numpy as np
    idx = np.flatnonzero(mask)
    if not len(idx):
        return []
    out, a, p = [], int(idx[0]), int(idx[0])
    for v in idx[1:]:
        v = int(v)
        if v - p - 1 > gap:
            out.append((a, p))
            a = v
        p = v
    out.append((a, p))
    return out


def _ocr_read_lines(crops, gaps):
    """Reads text-line images (dark on light). gaps: word gaps per crop as (x0, x1, gap/height)."""
    import numpy as np
    from PIL import Image
    sess = _ocr_session()
    chars, allowed = _OCR["chars"], _OCR["ascii"]
    out = [""] * len(crops)
    items = []
    for i, c in enumerate(crops):
        h, w = c.shape
        nw = max(16, min(4000, int(round(w * 48.0 / max(h, 1)))))
        a = (np.asarray(Image.fromarray(c).resize((nw, 48), Image.BILINEAR), dtype=np.float32) / 255.0 - 0.5) / 0.5
        items.append((nw, i, a))
    items.sort(key=lambda x: x[0])
    k = 0
    while k < len(items):
        batch = [items[k]]
        k += 1
        while k < len(items) and len(batch) < 24 and (len(batch) + 1) * max(320, items[k][0]) <= 24000:
            batch.append(items[k])
            k += 1
        W = max(320, max(b[0] for b in batch))
        x = np.zeros((len(batch), 3, 48, W), dtype=np.float32)
        for j, (nw, i, a) in enumerate(batch):
            x[j, :, :, :nw] = a[None, :, :]
        prob = sess.run(None, {sess.get_inputs()[0].name: x})[0]
        prob = np.where(allowed[None, None, :], prob, 0.0)
        idx = prob.argmax(axis=2)
        T = idx.shape[1]
        step = W / float(T)
        for j, (nw, i, a) in enumerate(batch):
            scale = crops[i].shape[0] / 48.0
            found, last = [], 0
            for t, ci in enumerate(idx[j][: int(np.ceil(nw / step)) + 1]):
                if ci != last and ci != 0:
                    found.append(((t + 0.5) * step * scale, chars[ci]))
                last = ci
            txt = []
            for n, (xpos, ch) in enumerate(found):
                if n:
                    prev = found[n - 1][1]
                    numeric = (prev.isdigit() or prev in "-/:.,") and (ch.isdigit() or ch in "-/:.,")
                    if any(found[n - 1][0] < (g0 + g1) / 2.0 < xpos and r >= (0.8 if numeric else 0.36) for g0, g1, r in gaps[i]):
                        txt.append(" ")
                txt.append(ch)
            out[i] = "".join(txt)
    return out


def _ocr_line_jobs(ink, gray, jobs, gaps):
    """Splits a cell (or any region) into text lines and queues each line for reading.
    Returns the job indexes, one per text line."""
    import numpy as np
    out = []
    if ink.shape[0] > 30:                       # drop ruling/border remnants: columns inked most of the way down
        ink = ink & ~(ink.mean(axis=0) > 0.5)[None, :]
    for ly0, ly1 in _ocr_groups(ink.sum(axis=1) >= 1, 2):
        if ly1 - ly0 < 7:
            continue
        ln = ink[ly0:ly1 + 1]
        h = ln.shape[0]
        runs = _ocr_groups(ln.sum(axis=0) >= 1, 0)
        if not runs:
            continue
        gs = [(e + 1, a - 1) for (_, e), (a, _) in zip(runs, runs[1:])]
        widths = sorted(g1 - g0 + 1 for g0, g1 in gs)
        med = widths[len(widths) // 2] if widths else 0
        thr = max(h * 0.36, med * 2.0, 4)
        # very long gaps split a title line into separate pieces read one by one
        ox = max(0, runs[0][0] - 4)
        crop = gray[max(0, ly0 - 3):ly1 + 4, ox:runs[-1][1] + 5]
        gaps.append([(g0 - ox, g1 - ox, (g1 - g0 + 1) / float(h)) for g0, g1 in gs if g1 - g0 + 1 >= thr])
        jobs.append(crop)
        out.append(len(jobs) - 1)
    return out


def _ocr_tables_from_image(img):
    """A scanned, ruled line-up page -> (tables, title_text). Each table is a list of rows
    of cell text, the cells lined up under the header row's columns."""
    import numpy as np
    from PIL import Image
    gray = img.convert("L")
    if gray.width > 2600:
        gray = gray.resize((2600, int(gray.height * 2600 / gray.width)))
    small = gray.resize((max(1, gray.width // 3), max(1, gray.height // 3)))
    best = (-1.0, 0.0)
    for ang in np.arange(-2.0, 2.01, 0.2):                       # straighten a crooked scan
        b = np.asarray(small.rotate(float(ang), fillcolor=255, resample=Image.BILINEAR)) < 150
        sc = float(np.var(b.sum(axis=1)))
        if sc > best[0]:
            best = (sc, float(ang))
    if abs(best[1]) >= 0.05:
        gray = gray.rotate(best[1], fillcolor=255, resample=Image.BICUBIC)
    G = np.asarray(gray)
    H, W = G.shape
    B = G < 150
    # outer x-extent of the ruled area: columns holding a long vertical line
    Bv = G < 180
    L = max(60, H // 12)
    cs = np.cumsum(Bv, axis=0, dtype=np.int32)
    cols = np.flatnonzero(((cs[L:, :] - cs[:-L, :]) >= int(L * 0.9)).any(axis=0))
    cols = cols[(cols > 3) & (cols < W - 4)]
    x0, x1 = (int(cols.min()), int(cols.max())) if len(cols) >= 2 else (0, W)
    # row rulings: thin bands across the table (scans make them faint and broken)
    cov = (G[:, x0:x1] < 225).mean(axis=1)
    hl = []
    for a, b in _ocr_groups(cov >= 0.12, 0):
        seg = cov[a:b + 1]
        if b - a <= 6 and seg.max() >= 0.33:
            hl.append(a + int(seg.argmax()))
        else:
            for c, d in _ocr_groups(seg >= 0.6, 1):
                hl.append(a + (c + d) // 2)
    hl.sort()
    jobs, gaps, layout = [], [], []
    for y0, y1 in zip(hl, hl[1:]):
        if not (18 <= y1 - y0 <= 260):
            layout.append(None)                                   # gap between two tables
            continue
        sub = B[y0 + 4:y1 - 3, :]
        if sub.shape[0] < 6:
            continue
        vl = [(a + b) // 2 for a, b in _ocr_groups(sub.mean(axis=0) >= 0.75, 2)]
        cells = []
        for cx0, cx1 in zip(vl, vl[1:]):
            if cx1 - cx0 < 10:
                continue
            ink = B[y0 + 4:y1 - 3, cx0 + 4:cx1 - 3]
            g = G[y0 + 4:y1 - 3, cx0 + 4:cx1 - 3]
            cells.append((cx0, cx1, _ocr_line_jobs(ink, g, jobs, gaps)))
        layout.append((y0, y1, cells))
    # the title above the first table (port name, date)
    firsts = [it[0] for it in layout if it and len(it[2]) >= 2]
    top = firsts[0] if firsts else H // 5
    title_jobs = _ocr_line_jobs(B[:top, x0 + 3:x1 - 2], G[:top, x0 + 3:x1 - 2], jobs, gaps) if top > 20 else []
    if len(jobs) > 1500:
        raise ValueError("too much text for one line-up page")
    texts = _ocr_read_lines(jobs, gaps) if jobs else []
    title = "\n".join(texts[i] for i in title_jobs)
    tables, cur = [], []
    for item in layout:
        if item is None:
            if cur:
                tables.append(cur)
            cur = []
            continue
        y0, y1, cells = item
        cur.append([(cx0, cx1, "\n".join(texts[i] for i in ids).strip()) for cx0, cx1, ids in cells])
    if cur:
        tables.append(cur)
    out = []
    for bands in tables:
        rows, header = [], None
        for cells in bands:
            filled = [c for c in cells if c[2]]
            if header is None:
                hm = _lu_header_map([c[2] for c in cells])
                if "vessel" in hm and len(hm) >= 3:
                    header = [(cx0, cx1) for cx0, cx1, _ in cells]
                    rows.append([c[2] for c in cells])
                elif len(filled) == 1:
                    rows.append([filled[0][2].replace("\n", " ")])   # a section title, e.g. NEXT VESSEL DOCKING
                continue
            row = [""] * len(header)
            for cx0, cx1, t in filled:
                mid = (cx0 + cx1) / 2.0
                best_i = min(range(len(header)), key=lambda k: 0 if header[k][0] <= mid <= header[k][1] else min(abs(mid - header[k][0]), abs(mid - header[k][1])))
                row[best_i] = (row[best_i] + "\n" + t).strip() if row[best_i] else t
            rows.append(row)
        if rows:
            out.append(rows)
    return out, title


def _lu_scan_tables(raw, filename):
    """Tables (and title text) from a scanned PDF or a photo/scan image of a line-up."""
    from PIL import Image
    pages = []
    if raw[:4] == b"%PDF":
        import pdfplumber
        with pdfplumber.open(io.BytesIO(raw)) as pdf:
            for page in pdf.pages[:4]:
                pages.append(page.to_image(resolution=200).original)
    else:
        im = Image.open(io.BytesIO(raw))
        im.load()
        pages.append(im)
    tables, titles = [], []
    for n, im in enumerate(pages):
        tbs, title = _ocr_tables_from_image(im)
        titles.append(title)
        for k, rows in enumerate(tbs):
            tables.append(_mf_plain_table(f"Page {n + 1} table {k + 1}", rows))
    if tables:
        tables[0]["title"] = "\n".join(titles)
    return tables


def _lu_tables_from_upload(raw, filename):
    name = (filename or "").lower()
    if name.endswith((".png", ".jpg", ".jpeg", ".tif", ".tiff", ".bmp", ".webp")):
        return _lu_scan_tables(raw, filename)
    if name.endswith((".csv", ".txt", ".tsv")) or not name:
        text = _mf_decode_csv(raw)
        return [_mf_plain_table("Text", list(csv.reader(io.StringIO(text), delimiter=_mf_sniff_delimiter(text))))]
    if name.endswith(".docx"):
        import docx
        document = docx.Document(io.BytesIO(raw))
        return [_mf_plain_table(f"Table {n + 1}", [[c.text for c in r.cells] for r in tb.rows]) for n, tb in enumerate(document.tables)]
    if name.endswith(".pdf"):
        import pdfplumber
        tables, title, chars = [], "", 0
        with pdfplumber.open(io.BytesIO(raw)) as pdf:
            for page in pdf.pages:
                chars += len(page.chars)
                if page.page_number == 1:
                    title = (page.extract_text() or "")[:600]
                for tb in (page.extract_tables() or []):
                    if tb:
                        tables.append(_mf_plain_table(f"Page {page.page_number}", [[c or "" for c in r] for r in tb]))
        if chars < 40:                                  # a scan: no text inside the PDF
            return _lu_scan_tables(raw, filename)
        if tables:
            tables[0]["title"] = title
        return tables
    if name.endswith((".xlsx", ".xlsm", ".xls")):
        if raw[:4] == _ZIP_MAGIC or raw[:8] == _OLE_MAGIC:
            return _mf_tables_from_excel(raw, name)
        return _mf_tables_from_markup_or_text(raw)
    raise ValueError("unsupported file type")


def _lu_file_date(tables, filename, today):
    """The line-up's own date, from its title (Mawani 'DATE : 22-10-2026', RSGT
    'vessel Schedule - 20261019') or its file name ('..._LIVE_-_20261021.pdf')."""
    title = (tables[0].get("title") or "") if tables else ""
    head = []
    for line in title.splitlines():                  # only the heading, never the vessels' own dates
        if re.search(r"VESSEL|S\.?\s*NO\b|BERTH\s*NO", line, re.I) and not re.search(r"SCHEDULE|LINE\s*-?\s*UP|PROGRAMME|ARRIVALS", line, re.I):
            break
        head.append(line)
    texts = ["\n".join(head)]
    texts += [" ".join(str(c) for c in r if str(c).strip()) for t in tables[:2] for r in t["rows"][:6]
              if sum(1 for c in r if str(c).strip()) <= 2]
    texts.append(filename or "")
    pats = [r"DATE\s*:?\s*(\d{1,2})[-/.](\d{1,2})[-/.](20\d{2})",
            r"(?<!\d)(20\d{2})(\d{2})(\d{2})(?!\d)",
            r"(?<!\d)(\d{1,2})/(\d{1,2})/(20\d{2})(?!\d)"]
    for t in texts:
        u = str(t).upper()
        for n, pat in enumerate(pats):
            for m in re.finditer(pat, u):
                try:
                    a, b, c = (int(x) for x in m.groups())
                    d = date(a, b, c) if n == 1 else date(c, b, a)
                except ValueError:
                    continue
                if today - timedelta(days=120) <= d <= today + timedelta(days=3):
                    return d
    return None


def _lu_guess_port(text):
    t = (text or "").upper()
    if "YANBU" in t or "YCP" in t:
        return "YNB"
    if "DAMMAM" in t or "ABDULAZIZ" in t or "DMM" in t:
        return "DMM"
    if "JEDDAH" in t or "JEDDA" in t or "JIP" in t:
        return "JED"
    return ""


def _lu_norm_berth(name):
    """'BERTH NO. 5', 'B-5', 'B5', '5', '5(b)', '8/9', '36 / N' -> '5' / '8' / '36'; anything else upper-cased as is."""
    t = re.sub(r"\s+", " ", str(name or "")).strip().upper()
    m = re.match(r"^(?:BERTH|BERTH NO\.?|B\.?|NO\.?|BTH)?\s*[-#]?\s*(\d+[A-Z]?)(?:\s*\([A-H]\))?(?:\s*[/&-]\s*\w+)?$", t)
    return m.group(1) if m else t


def _lu_is_ours(agent):
    """Sea Power in any spelling the ports use: 'SEA POWER', 'SEAPOWER', 'Sea-Power Marine',
    Mawani's 'SPMSL' (Sea Power Marine Services Ltd)."""
    a = re.sub(r"[^A-Z]", "", str(agent or "").upper())
    return bool(a) and ("SEAPOWER" in a or a in ("SPMSL", "SPMS", "SPMSLTD", "SPM"))


# What Sea Power told Compass about a port's berths (used until set or learned otherwise):
# at Jeddah only Berth 3 takes deep general cargo; the other general cargo berths take up to 11.8 m.
# Jeddah Islamic Port: the only berths that take general cargo, and their maximum drafts (from Sea Power).
# Berth 3 is the one high-draft berth; Berth 11 is mostly livestock, sometimes general cargo.
_LU_PORT_HINTS = {"JED": {"fixed": {"3": 13.5, "10": 12.0, "11": 7.7, "21": 10.4, "27": 10.4, "34": 11.7,
                                    "35": 11.8, "36": 10.8, "37": 11.8, "38": 11.8},
                          "high": {"3"}, "occasional": {"11"}, "deep_alt": {"1", "2"}}}


def _lu_berths_raw(db, port):
    return [dict(r) for r in db.execute(
        "SELECT * FROM lu_berths WHERE port = ? AND active = 1 ORDER BY sort, id", (port,)).fetchall()]


def _lu_vcat(v):
    return v.get("cat") or _lu_category(v.get("vtype"), v.get("cargo"))


def _lu_bstats(db, port, now=None):
    """What the line-ups show about each berth: which kinds of ship use it and the
    deepest general cargo vessel seen there (alongside, or allocated by the terminal)."""
    cache = g.setdefault("_lu_bstats", {})
    if port in cache:
        return cache[port]
    now = now or _lu_now()
    hist = _lu_history(db, port, 60, now)
    stats = {}
    for d in sorted(hist):
        for v in hist[d].values():
            k = _lu_berth_slot(v["berth"])[0]
            if not k:
                continue
            st = stats.setdefault(k, {"cats": {}, "deep": None, "n_general": 0, "names": set(), "deep_any": None, "n_any": 0})
            if v["vessel"] in st["names"]:
                continue
            st["names"].add(v["vessel"])
            if v.get("draft") and 2 <= v["draft"] <= 25:       # any ship there proves the depth, whatever her cargo
                st["n_any"] += 1
                st["deep_any"] = max(st["deep_any"] or 0, v["draft"])
            c = _lu_vcat(v)
            st["cats"][c] = st["cats"].get(c, 0) + 1
            if c == "general":
                st["n_general"] += 1
                if v.get("draft") and 2 <= v["draft"] <= 25:
                    st["deep"] = max(st["deep"] or 0, v["draft"])
    for st in stats.values():
        st.pop("names", None)
    cache[port] = stats
    return stats


def _lu_berths(db, port, now=None):
    """The port's berths as Compass plans with them: whether each takes general cargo
    (as set, or learned from the line-ups) and the draft limit (as set, from what Sea
    Power told Compass about the port, or learned)."""
    raw = _lu_berths_raw(db, port)
    stats = _lu_bstats(db, port, now)
    hint = _LU_PORT_HINTS.get(port) or {}
    fixed = hint.get("fixed")
    out = []
    if fixed:                                  # fixed berths not seen on a line-up yet are still there
        have = {_lu_norm_berth(b["name"]) for b in raw}
        for k in sorted(fixed, key=lambda x: int(re.match(r"\d+", x).group(0)) if re.match(r"\d+", x) else 999):
            if k not in have:
                raw.append({"id": None, "port": port, "name": "Berth " + k, "max_draft": None, "active": 1,
                            "sort": int(re.match(r"\d+", k).group(0)) if re.match(r"\d+", k) else 999, "kind": "", "cargo_use": ""})
        raw.sort(key=lambda b: (b.get("sort") or 0, b.get("id") or 0))
    for b in raw:
        k = _lu_norm_berth(b["name"])
        st = stats.get(k) or {"cats": {}, "deep": None, "n_general": 0}
        use = (b.get("cargo_use") or "").strip()
        kind = (b.get("kind") or "").strip()
        if use:
            general = use == "general"
        elif kind:
            general = kind == "general"               # the terminal lists the berth as e.g. 'Live stock' or 'RoRo'
        else:
            general = st["n_general"] > 0 or not st["cats"]
        md, why = b.get("max_draft"), ("set" if b.get("max_draft") else "")
        if fixed:                                  # the port's own list: these berths and depths, nothing else
            general = k in fixed
            md, why = (fixed[k], "port") if general else (None, "")
        if md is None and general and st.get("n_any", 0) >= 3 and st.get("deep_any"):
            md, why = round(st["deep_any"] + 0.3, 1), "learned"       # the deepest ship seen there, plus a little
        e = dict(b)
        e["_seen_any"] = st.get("deep_any")
        e.update({"key": k, "set_draft": b.get("max_draft"), "max_draft": md, "draft_from": why, "general": general, "fixed": bool(fixed),
                  "high": k in (hint.get("high") or ()), "occasional": k in (hint.get("occasional") or ()), "deep_alt": k in (hint.get("deep_alt") or ()),
                  "use": use, "kind": kind, "cats": sorted(set(st["cats"]) | ({kind} if kind else set()), key=lambda c: -st["cats"].get(c, 0)), "seen_deep": st["deep"],
                  "seen_general": st["n_general"]})
        out.append(e)
    # a general berth seen only once or twice: at least as deep as the ships seen there, and as the port's shallowest known berth
    known = [e["max_draft"] for e in out if e["general"] and e.get("max_draft")]
    for e in out:
        seen = e.pop("_seen_any", None)
        if e["general"] and e.get("max_draft") is None and seen and known:
            e["max_draft"], e["draft_from"] = max(round(seen + 0.3, 1), min(known)), "learned"
    return out


def _lu_latest(db, port, before_id=None):
    if before_id:
        return db.execute("SELECT * FROM lu_snapshots WHERE port = ? AND id < ? ORDER BY lineup_date DESC, id DESC LIMIT 1",
                          (port, before_id)).fetchone()
    return db.execute("SELECT * FROM lu_snapshots WHERE port = ? ORDER BY lineup_date DESC, id DESC LIMIT 1", (port,)).fetchone()


def _lu_attach_pace(db, snap_id, vessels):
    """Gives each vessel alongside her recent discharge pace (cargo off per day), worked out from
    the cargo left on board (ROB) on the line-ups of the last nine days. A ship's own recent pace
    says more about when she will sail than any average for her kind of cargo."""
    try:
        snap = db.execute("SELECT port, lineup_date FROM lu_snapshots WHERE id = ?", (snap_id,)).fetchone()
        if not snap or not any(v.get("status") == "alongside" and v.get("rob") is not None for v in vessels):
            return
        last_day = date.fromisoformat(snap["lineup_date"])
        rows = db.execute(
            "SELECT s.lineup_date AS d, v.vessel, v.rob FROM lu_vessels v JOIN lu_snapshots s ON s.id = v.snapshot_id "
            "WHERE s.port = ? AND s.lineup_date >= ? AND s.lineup_date <= ? AND v.rob IS NOT NULL AND v.status = 'alongside' "
            "ORDER BY s.lineup_date, s.id", (snap["port"], (last_day - timedelta(days=9)).isoformat(), snap["lineup_date"])).fetchall()
        by = {}
        for r in rows:
            by.setdefault(r["vessel"], {})[r["d"]] = float(r["rob"])
        for v in vessels:
            pts = sorted(by.get(v["vessel"], {}).items())
            if len(pts) < 2 or pts[-1][0] != snap["lineup_date"]:
                continue
            chain = [pts[-1]]
            for d, rb in reversed(pts[:-1]):
                if rb >= chain[0][1]:                       # cargo only goes down; a rise means she was loaded or re-berthed
                    chain.insert(0, (d, rb))
                else:
                    break
            days = (last_day - date.fromisoformat(chain[0][0])).days
            drop = chain[0][1] - chain[-1][1]
            if days >= 1 and drop > 0 and 100 <= drop / days <= 20000:
                v["pace"] = round(drop / days)
    except Exception:
        app.logger.exception("line-up pace failed")


def _lu_vessels(db, snap_id):
    out = [dict(r) for r in db.execute(
        "SELECT v.*, s.lineup_date AS lu_date FROM lu_vessels v JOIN lu_snapshots s ON s.id = v.snapshot_id "
        "WHERE v.snapshot_id = ? ORDER BY v.seq, v.id", (snap_id,)).fetchall()]
    _lu_attach_pace(db, snap_id, out)
    return out


def _lu_dt(s):
    try:
        return datetime.strptime(s, "%Y-%m-%d %H:%M") if s else None
    except ValueError:
        return None


def _lu_days_alongside(cargo, qty, rates=None):
    fam = _lu_cargo_family(cargo)
    try:
        q = float(qty or 0)
    except (TypeError, ValueError):
        q = 0
    if q <= 0:
        return 2.0
    rate = (rates or {}).get(fam) or _LU_RATES[fam]
    return max(0.5, round(q / rate, 1))


def _lu_simulate(berths, vessels, now, extra=None, learn=None, force=None, shift=None, phantoms=None, use_bias=True, open_berths=False):
    """Works out the berth plan, first come first served by readiness, as the port runs it:
    each kind of ship only at the berths that kind uses, the terminal's own allocation
    followed (Jeddah's 2(a), 2(b) ...; Mawani's 1ST/2ND; Yanbu's ETB), the draft limits,
    and alongside vessels finishing on their remaining cargo (ROB) or the stated ETC.
    learn: what Compass has learned at this port (discharge rates, queue jumping,
    the bias of past estimates) - applied when given.
    force: {vessel_id: berth_key} - that waiting vessel may only use that berth.
    shift: {vessel_id: (berth_key, when)} - that alongside vessel shifts berth at `when`.
    phantoms: vessels not on the line-up yet but likely to arrive (from history).
    open_berths: waiting vessels may take any berth that suits them (first come first served),
    instead of the berth the terminal has pencilled in - how a NEW arrival's queue really works.
    Returns {vessel_id: {...}}; the extra (hypothetical) vessel keeps its own id."""
    learn = learn or {}
    rates = learn.get("rates_use")
    jr = learn.get("jump_rate_use") or 0.0
    bias = (learn.get("bias_use") or 0.0) if use_bias else 0.0
    force = force or {}
    shift = shift or {}
    # a vessel listed without her tonnage is not a 2-day call: take the typical tonnage on this line-up
    qs = {}
    for v in vessels:
        c = _lu_vcat(v)
        if c in ("general", "bulk") and v.get("qty"):
            try:
                qs.setdefault(c, []).append(float(v["qty"]))
            except (TypeError, ValueError):
                pass
    med_qty = {c: _lu_median(x) for c, x in qs.items() if len(x) >= 3}

    def stay(v):
        try:
            q = float(v.get("qty") or 0)
        except (TypeError, ValueError):
            q = 0
        if q <= 0:
            q = med_qty.get(_lu_vcat(v)) or 0
        if q <= 0 and _lu_vcat(v) in _LU_CAT_STAY:
            return _LU_CAT_STAY[_lu_vcat(v)]
        return _lu_days_alongside(v.get("cargo"), q, rates)
    bmap = {(b.get("key") or _lu_norm_berth(b["name"])): b for b in berths}
    free = {k: now for k in bmap}
    res = {}

    def rate_for(v):
        fam = _lu_cargo_family(v.get("cargo"))
        return (rates or {}).get(fam) or _LU_RATES[fam]

    # 1) vessels alongside hold their berth until they sail (or until a requested shift)
    later = []
    for v in vessels:
        if v["status"] != "alongside":
            continue
        k = _lu_berth_slot(v["berth"])[0]
        start = _lu_dt(v["berthed"]) or now
        end = _lu_dt(v["etd"])
        if end and end <= now:
            end = now + timedelta(hours=6)              # stated sailing time has passed (older line-up): about to sail
        if not end:
            if v.get("rob") is not None:
                rob_left = max(0.0, float(v["rob"]) - float(v.get("transit") or 0))     # transit cargo stays on board
                # her own pace so far (manifest - ROB since all fast), else the port's learned rate;
                # counted from the line-up's date, so an older line-up is not read as today's ROB
                asof = (datetime.strptime(v["lu_date"], "%Y-%m-%d") + timedelta(hours=7)) if v.get("lu_date") else now
                base = rate = rate_for(v)
                b0 = _lu_dt(v["berthed"])
                if b0 and v.get("qty") and _lu_days(asof, b0) >= 1 and float(v["qty"]) > float(v["rob"]):
                    done = float(v["qty"]) - float(v["rob"])
                    own = done / _lu_days(asof, b0)
                    if 100 <= own <= 20000:
                        w = min(1.0, done / float(v["qty"]) / 0.3)    # trust her own pace more as more cargo is worked
                        rate = max(0.5 * base, w * own + (1 - w) * base)
                recent = v.get("pace")                       # what she really discharged between the last line-ups
                if recent and 100 <= recent <= 20000:
                    rate = max(0.4 * base, 0.65 * recent + 0.35 * rate)
                end = max(now + timedelta(hours=6), asof + timedelta(days=rob_left / rate))
            else:
                end = max(now + timedelta(hours=6), start + timedelta(days=stay(v)))
        if v["id"] in shift:
            later.append((v, k, start, end))
            continue
        res[v["id"]] = {"berth": bmap[k]["name"] if k in bmap else (v["berth"] or ""), "berth_key": k, "start": start, "end": end,
                        "ready": _lu_dt(v["arrived"]) or start}
        if k in free:
            free[k] = max(free[k], end + _LU_TURNAROUND)
    for v, k, start, end in later:
        to, when = shift[v["id"]]
        when = max(when, now)
        s2 = max(free.get(to, now), when)                      # she cannot leave until the berth she is moving to is free
        if end <= s2 + timedelta(hours=6):                     # she finishes before that: no shift happens
            res[v["id"]] = {"berth": bmap[k]["name"] if k in bmap else (v["berth"] or ""), "berth_key": k, "start": start, "end": end,
                            "ready": _lu_dt(v["arrived"]) or start}
            if k in free:
                free[k] = max(free[k], end + _LU_TURNAROUND)
            continue
        if k in free:
            free[k] = max(free[k], s2 + timedelta(hours=2))
        end2 = end + timedelta(hours=6)                        # same remaining cargo work, plus the shifting time
        free[to] = end2
        fk = bmap[k]["name"] if k in bmap else v["berth"]
        res[v["id"]] = {"berth": bmap[to]["name"], "berth_key": to, "start": start, "end": end2, "ready": _lu_dt(v["arrived"]) or start,
                        "shifted_from": fk, "shift_at": s2,
                        "segs": [{"b": k, "s": start, "e": s2}, {"b": to, "s": s2, "e": end2}]}
    # 2) waiting and expected vessels, first come first served by readiness
    queue = []
    for v in vessels:
        if v["status"] == "alongside":
            continue
        if v["status"] == "expected" and not _lu_dt(v.get("eta")):
            res[v["id"]] = {"berth": "", "start": None, "end": None, "ready": None, "noeta": True}
            continue                                   # ETA 'TBA': not in the queue until she has one
        ready = _lu_dt(v["arrived"]) if v["status"] == "anchor" else _lu_dt(v["eta"])
        ready = ready or (now if v["status"] == "anchor" else now + timedelta(days=1))
        queue.append((ready, v.get("seq") or 0, v))
    for ph in (phantoms or []):
        queue.append((ph["ready"], 10 ** 5, ph))
    if extra:
        queue.append((extra["ready"], 10 ** 6, extra))
    queue.sort(key=lambda x: (x[0], x[1]))
    # the terminal's order at a berth (2(a) before 2(b)) overrides arrival order among those vessels
    slots = {}
    lettered = {_lu_berth_slot(v.get("berth"))[0] for _, _, v in queue if _lu_berth_slot(v.get("berth"))[1] and v["id"] not in force}
    for pos, (_, _, v) in enumerate(queue):
        if v["id"] in force:
            continue
        k, sl = _lu_berth_slot(v.get("berth"))
        if k in bmap and (sl or k in lettered) and not open_berths:
            slots.setdefault(k, []).append(pos)
    for k, poss in slots.items():
        items = sorted((queue[p] for p in poss), key=lambda q: _lu_berth_slot(q[2].get("berth"))[1] or 1)
        for p, it in zip(poss, items):
            queue[p] = it
    for ready, _, v in queue:
        draft = v.get("draft")
        cat = _lu_vcat(v)
        tk = _lu_berth_slot(v.get("berth"))[0] if v["id"] not in force else ""
        tk = tk if tk in bmap else ""
        if v["id"] in force and force[v["id"]] in bmap:
            allowed = [force[v["id"]]]
        elif tk and not open_berths:
            allowed = [tk]                                 # the terminal has allocated her berth
        else:
            kinds = [k for k, b in bmap.items() if ((b.get("general", True) and not b.get("occasional")) if cat == "general" else cat in (b.get("cats") or []))
                     or (cat == "general" and b.get("deep_alt") and draft and draft >= 12.0)]
            allowed = [k for k in kinds if not draft or not bmap[k].get("max_draft") or draft <= bmap[k]["max_draft"]]
            if tk and tk not in allowed:
                allowed.append(tk)                         # her allocated berth suits her, whatever our records say
            if not kinds and not allowed:
                res[v["id"]] = {"berth": "", "start": None, "end": None, "ready": ready, "elsewhere": True, "cat": cat}
                continue
            if not allowed:
                res[v["id"]] = {"berth": "", "start": None, "end": None, "ready": ready, "nofit": True, "cat": cat}
                continue
        etb = _lu_dt(v.get("etb") or "")
        best = None
        for k in allowed:
            start = max(free[k], ready, now)
            if etb and tk == k:
                start = max(etb, ready, now)                # the terminal's own berthing time for her berth
            score = (start, bmap[k].get("max_draft") or 99)       # earliest; on a tie keep deep berths for deep vessels
            if best is None or score < best[0]:
                best = (score, k, start)
        _, k, start = best
        dur = timedelta(days=stay(v))
        free[k] = max(free[k], start + dur + _LU_TURNAROUND)
        b = bmap[k]
        # what history says about this port: priority vessels stretch the wait, and past estimates ran early/late
        base = max(ready, now)
        adj = timedelta(days=max(0.0, _lu_days(start, base)) * jr + bias)
        shown = max(base, start + adj)
        margin = (b["max_draft"] - draft) if (draft and b.get("max_draft")) else None
        res[v["id"]] = {"berth": b["name"], "berth_key": k, "start": shown, "end": shown + dur, "ready": ready, "margin": margin,
                        "fits": [bmap[x]["name"] for x in allowed], "raw_start": start, "cat": cat, "allocated": bool(tk and tk in bmap)}
    return res


def _lu_t0(snap, now):
    """When the line-up was issued (its date, early morning); never after now."""
    try:
        t0 = datetime.strptime(snap["lineup_date"], "%Y-%m-%d") + timedelta(hours=7)
    except (TypeError, ValueError, KeyError):
        return now
    return min(now, t0)


def _lu_newcomer(berths, vessels, learn, now, t0, draft, cargo="general", qty=8000, ready=None, horizon=10):
    """When a vessel that is not on the line-up would berth. The line-up is played forward from
    the time it was issued (an older line-up still gives today's picture), and she queues behind
    every vessel that arrived before her, at any berth that suits her - first come, first served."""
    ready = ready or now
    gap = max(0.0, _lu_days(now, t0))
    sim = _lu_simulate(berths, vessels, t0, extra={"id": "__x__", "status": "anchor" if ready <= now else "expected",
                                                   "draft": draft, "cargo": cargo, "qty": qty, "ready": ready},
                       learn=learn, phantoms=_lu_phantoms(learn, vessels, t0, horizon_days=horizon + gap), open_berths=True,
                       use_bias=False)                  # the learned lean is measured on listed vessels, not on newcomers
    return sim, (sim.get("__x__") or {})


def _lu_band_step(berths, gen, vessels, learn, now, t0, draft, byid, deeper_than=None):
    """One estimate: when a vessel of this draft, arriving now, would berth, and who is ahead of her."""
    sim, x = _lu_newcomer(berths, vessels, learn, now, t0, draft)
    fit = [b for b in gen if not b.get("occasional") and (not b.get("max_draft") or draft <= b["max_draft"])]
    fit += [b for b in berths if b.get("deep_alt") and draft >= 12.0]
    st = {"draft": draft, "berths": [b["name"] for b in fit], "wait": None, "start": "", "berth": "", "ahead": 0, "ahead_names": []}
    if not x.get("start"):
        return st
    keys = {b["key"] for b in fit}
    ahead = []
    for vid, r in sim.items():
        v = byid.get(vid)
        if not v or not r.get("start") or r.get("berth_key") not in keys or not r.get("ready"):
            continue
        if deeper_than and v.get("draft") and v["draft"] > deeper_than:
            continue                                 # a high-draft ship is not in the low-draft queue
        if r["ready"] < now and now <= r["start"] <= x["start"]:     # already here, and berths before her
            ahead.append((r["start"], v["vessel"]))
    ahead.sort()
    st.update({"wait": round(max(0.0, _lu_days(x["start"], now)), 1), "start": x["start"].strftime("%Y-%m-%d %H:%M"),
               "berth": x.get("berth", ""), "ahead": len(ahead), "ahead_names": [n for _, n in ahead[:3]]})
    return st


def _lu_bands(berths, vessels, learn, now, t0, port=None):
    """How long a vessel arriving today waits, low draft and high draft. Where Sea Power has named the
    port's high-draft berths (Jeddah: Berth 3), those make the high band and every other general cargo
    berth the low band, broken down by draft (a 12 m ship has fewer berths than a 10 m one). Elsewhere
    the bands follow the berths' depths, at most three."""
    gen = [b for b in berths if b["general"]]
    if not gen:
        return []
    high = set((_LU_PORT_HINTS.get(port) or {}).get("high") or ())
    lows = [b for b in gen if b["key"] not in high and b.get("max_draft") and not b.get("occasional")]
    highs = [b for b in gen if b["key"] in high and b.get("max_draft")]
    if lows and highs:
        low_l = sorted({b["max_draft"] for b in lows})
        plan = [(None, low_l[-1], low_l, [b["name"] for b in gen if b["key"] not in high]),
                (low_l[-1], max(b["max_draft"] for b in highs), [max(b["max_draft"] for b in highs)],
                 [b["name"] for b in highs] + [b["name"] for b in berths if b.get("deep_alt")])]
    else:
        lims = sorted({b["max_draft"] for b in gen if b.get("max_draft")})
        open_top = any(not b.get("max_draft") for b in gen)
        if not lims:
            spans = [(None, None)]
        else:
            spans = [(None, lims[0])] + [(lims[i - 1], lims[i]) for i in range(1, len(lims))] + ([(lims[-1], None)] if open_top else [])
        if len(spans) > 3:
            spans = [spans[0], (spans[1][0], spans[-2][1]), spans[-1]]
        plan = []
        for lo, hi in spans:
            d = hi if hi else (round(lo + 0.3, 1) if lo else 10.0)
            plan.append((lo, hi, [d], [b["name"] for b in gen if not b.get("max_draft") or d <= b["max_draft"]]))
    byid = {v["id"]: v for v in vessels}
    out = []
    for i, (lo, hi, drafts, names) in enumerate(plan):
        top = i == len(plan) - 1
        steps, prev = [], lo
        for d in drafts:
            st = _lu_band_step(berths, gen, vessels, learn, now, t0, d, byid, deeper_than=None if top else hi)
            st["lo"], st["hi"] = prev, (d if (hi is not None or d != drafts[-1]) else None)
            prev = d
            if st["wait"] is not None:
                steps.append(st)
        merged = []                                   # drafts that wait (nearly) the same are one line
        for st in steps:
            m = merged[-1] if merged else None
            if m and abs(m["wait"] - st["wait"]) < 1:
                lo_ = m["lo"]
                m.clear()
                m.update(st)
                m["lo"] = lo_
                continue
            merged.append(st)
        band = {"lo": lo, "hi": hi, "berths": names, "steps": merged, "wait": None, "wait_min": None, "wait_max": None,
                "start": "", "berth": "", "draft": drafts[-1], "ahead": 0, "ahead_names": [], "recent": None, "n_recent": 0}
        if merged:
            typical = next((x for x in merged if x["hi"] is None or x["hi"] >= 10.0), merged[-1])   # a usual 10 m ship
            band.update({"wait": typical["wait"], "wait_min": min(x["wait"] for x in merged), "wait_max": max(x["wait"] for x in merged),
                         "start": typical["start"], "berth": typical["berth"], "draft": typical["draft"],
                         "ahead": typical["ahead"], "ahead_names": typical["ahead_names"]})
        out.append(band)
    if not (lows and highs):                          # neighbouring bands that come out the same are shown as one
        joined = []
        for b in out:
            prev = joined[-1] if joined else None
            if prev and prev["wait"] is not None and b["wait"] is not None and abs(prev["wait"] - b["wait"]) < 1:
                lo, names_ = prev["lo"], prev["berths"]
                prev.clear()
                prev.update(b)
                prev["lo"], prev["berths"] = lo, names_
                continue
            joined.append(b)
        out = joined
    return out


def _lu_median(xs):
    xs = sorted(xs)
    if not xs:
        return None
    m = len(xs) // 2
    return xs[m] if len(xs) % 2 else (xs[m - 1] + xs[m]) / 2


def _lu_history(db, port, days, now):
    """{date: {vessel: row}} for the latest line-up of each day in the window."""
    since = (now.date() - timedelta(days=days)).isoformat()
    rows = db.execute(
        "SELECT s.id AS sid, s.lineup_date, v.* FROM lu_vessels v JOIN lu_snapshots s ON s.id = v.snapshot_id "
        "WHERE s.port = ? AND s.lineup_date >= ? AND s.lineup_date <= ? ORDER BY s.lineup_date, s.id",
        (port, since, now.date().isoformat())).fetchall()
    last_sid = {}
    for r in rows:
        last_sid[r["lineup_date"]] = r["sid"]
    hist = {}
    for r in rows:
        if r["sid"] == last_sid[r["lineup_date"]]:
            hist.setdefault(r["lineup_date"], {})[r["vessel"]] = dict(r)
    return hist


def _lu_learn(db, port, now=None):
    """What Compass has learned at a port from the line-ups uploaded so far:
    real discharge rates, how often priority vessels jump the queue, how many
    vessels turn up that weren't on the line-up yet, and how accurate past
    berthing estimates were (and in which direction)."""
    cache = g.setdefault("_lu_learn", {})
    if port in cache:
        return cache[port]
    now = now or _lu_now()
    hist = _lu_history(db, port, 60, now)
    dates = sorted(hist)
    berths = {b["key"]: b for b in _lu_berths(db, port, now)}
    out = {"days": len(dates)}

    # 1) discharge rates: berthed -> gone from the line-up (or its last ETD)
    samples = {}
    seen = {}
    for i, d in enumerate(dates):
        for name, v in hist[d].items():
            if v["status"] == "alongside":
                seen.setdefault(name, []).append(i)
    for name, idxs in seen.items():
        last = idxs[-1]
        if last + 1 >= len(dates) or name in hist[dates[last + 1]]:
            continue                                   # still alongside, or no later line-up yet
        v = hist[dates[last]][name]
        berthed = _lu_dt(v["berthed"])
        if not berthed or not v["qty"]:
            continue
        nxt = datetime.strptime(dates[last + 1], "%Y-%m-%d") + timedelta(hours=7)
        etd = _lu_dt(v["etd"])
        dep = etd if (etd and datetime.strptime(dates[last], "%Y-%m-%d") <= etd <= nxt) else nxt
        days = _lu_days(dep, berthed)
        if 0.3 <= days <= 25 and not v.get("rob"):
            samples.setdefault(_lu_cargo_family(v["cargo"]), []).append(float(v["qty"]) / days)
    # cargo worked so far (manifest minus ROB) over the days since she was made fast: one line-up is enough
    worked = {}
    for d in dates:
        lu = datetime.strptime(d, "%Y-%m-%d") + timedelta(hours=7)
        for name, v in hist[d].items():
            b = _lu_dt(v["berthed"])
            if v["status"] != "alongside" or v.get("rob") is None or not v.get("qty") or not b:
                continue
            days = _lu_days(lu, b)
            done = float(v["qty"]) - float(v["rob"])
            if days >= 1 and done > 0 and done >= 0.2 * float(v["qty"]):     # a fifth worked: her pace has settled
                worked[name] = (_lu_cargo_family(v["cargo"]), done / days)
    # remaining cargo (ROB) falling from one line-up to the next is the real daily rate
    for name, idxs in seen.items():
        pts = [(datetime.strptime(dates[i], "%Y-%m-%d"), hist[dates[i]][name].get("rob")) for i in idxs]
        pts = [(d, r) for d, r in pts if r is not None]
        per = []
        for (d0, r0), (d1, r1) in zip(pts, pts[1:]):
            gap = (d1 - d0).days
            if 1 <= gap <= 7 and r0 > r1:
                per.append((r0 - r1) / gap)
        if per:
            r = _lu_median(per)
            if 150 <= r <= 20000:
                samples.setdefault(_lu_cargo_family(hist[dates[idxs[-1]]][name]["cargo"]), []).append(r)
                worked.pop(name, None)
    for fam, r in worked.values():
        if 100 <= r <= 20000:
            samples.setdefault(fam, []).append(r)
    rates_use, rates = {}, []
    # a cargo not learned yet is worked at this port's pace: the default scaled the way the learned ones are
    dflt = dict(_LU_RATES)
    dflt.update(_LU_PORT_RATES.get(port) or {})
    ratios = [_lu_median(samples[f]) / dflt[f] for f in _LU_RATE_LABEL if len(samples.get(f, [])) >= 3]
    factor = min(1.5, max(0.2, _lu_median(ratios))) if (ratios and not _LU_PORT_RATES.get(port)) else 1.0
    for fam, label in _LU_RATE_LABEL.items():
        s = samples.get(fam, [])
        learned = len(s) >= 3
        if learned:
            rate = round(_lu_median(s))
        else:
            rate = dflt[fam] * factor
            if s:                                        # one or two vessels seen: half their pace, half the port's
                rate = (rate + _lu_median(s)) / 2
            rate = round(rate)
        rates_use[fam] = rate
        rates.append({"fam": fam, "label": label, "rate": rate, "n": len(s), "learned": learned, "default": dflt[fam],
                      "scaled": (not learned) and (factor != 1.0 or bool(s))})
    out["rates"], out["rates_use"] = rates, rates_use

    # 2) queue jumping: a vessel berths while one that arrived earlier, and fits that berth, is still waiting
    jumps = berthings = 0
    for d0, d1 in zip(dates, dates[1:]):
        a, b = hist[d0], hist[d1]
        for name, v in b.items():
            if v["status"] != "alongside" or (name in a and a[name]["status"] == "alongside") or _lu_vcat(v) != "general":
                continue
            arr = _lu_dt(v["arrived"])
            if not arr:
                continue
            berthings += 1
            bk = berths.get(_lu_norm_berth(v["berth"]))
            limit = bk.get("max_draft") if bk else None
            for other in b.values():
                oa = _lu_dt(other["arrived"])
                ok_berth = _lu_berth_slot(other["berth"])[0] in ("", _lu_berth_slot(v["berth"])[0])
                if other["status"] == "anchor" and _lu_vcat(other) == "general" and ok_berth and oa and oa < arr - timedelta(hours=6) and (not limit or not other["draft"] or other["draft"] <= limit):
                    jumps += 1
                    break
    jr = (jumps / berthings) if berthings else 0.0
    out["jumps"] = {"jumps": jumps, "berthings": berthings, "rate": round(jr, 2), "active": berthings >= 5}
    out["jump_rate_use"] = round(jr, 2) if berthings >= 5 else 0.0

    # 3) vessels that appear on the line-up: how many a week, and how far ahead
    first, firsts_lead = {}, []
    for d in dates:
        for name, v in hist[d].items():
            if name not in first:
                first[name] = (d, v)
    new_names = [n for n, (d, v) in first.items() if dates and d != dates[0] and _lu_vcat(v) == "general"]
    span = (datetime.strptime(dates[-1], "%Y-%m-%d") - datetime.strptime(dates[0], "%Y-%m-%d")).days if len(dates) > 1 else 0
    for n in new_names:
        d, v = first[n]
        eta = _lu_dt(v["eta"])
        if v["status"] == "expected" and eta:
            firsts_lead.append(max(0.0, _lu_days(eta, datetime.strptime(d, "%Y-%m-%d") + timedelta(hours=7))))
        elif v["status"] != "expected":
            firsts_lead.append(0.0)                   # turned up without ever being listed as expected
    per_day = (len(new_names) / span) if span else 0.0
    lead = _lu_median(firsts_lead)
    out["arrivals"] = {"per_week": round(per_day * 7, 1), "lead": round(lead, 1) if lead is not None else None,
                       "days": span, "active": span >= 7 and per_day > 0}
    out["arrival_rate"] = per_day if span >= 7 else 0.0
    out["lead_use"] = lead if lead is not None else 3.0
    out["leads"] = sorted(firsts_lead)

    # 4) accuracy of past berthing estimates (made 0-10 days before the vessel actually berthed)
    actual = {}
    for d in dates:
        for name, v in hist[d].items():
            if v["status"] == "alongside" and _lu_dt(v["berthed"]):
                actual.setdefault(name, set()).add(v["berthed"])
    since = (now.date() - timedelta(days=45)).isoformat()
    errs = []
    for p in db.execute("SELECT vessel, made_on, pred_start FROM lu_predictions WHERE port = ? AND made_on >= ?", (port, since)).fetchall():
        made = datetime.strptime(p["made_on"], "%Y-%m-%d")
        pred = _lu_dt(p["pred_start"])
        if not pred:
            continue
        hits = sorted(b for b in (_lu_dt(x) for x in actual.get(p["vessel"], ())) if b and made <= b <= made + timedelta(days=10))
        if hits:
            errs.append(_lu_days(hits[0], pred))
    n = len(errs)
    acc = {"n": n, "active": n >= 10}
    if n:
        acc.update({"within1": round(100 * sum(1 for e in errs if abs(e) <= 1) / n), "mae": round(sum(abs(e) for e in errs) / n, 1),
                    "bias": round(sum(errs) / n, 1)})
    out["accuracy"] = acc
    out["bias_use"] = acc["bias"] if (n >= 10 and abs(acc.get("bias", 0)) >= 0.5) else 0.0     # only a clear, settled lean
    cache[port] = out
    return out


def _lu_phantoms(learn, vessels, now, horizon_days=10):
    """Vessels that are not on the line-up yet but, going by the last weeks, will
    arrive. A vessel due in x days is already listed if the port normally gives
    more than x days' notice, so only the share that is usually not listed yet
    is added (no double counting of vessels already on the line-up)."""
    rate = learn.get("arrival_rate") or 0.0
    if rate <= 0:
        return []
    leads = learn.get("leads") or []
    lead = learn.get("lead_use") or 3.0

    def unlisted(x):                                   # share of vessels due in x days not on the line-up yet
        if len(leads) >= 5:
            return sum(1 for d in leads if d < x) / len(leads)
        return 1.0 if x >= lead else 0.0
    gen = [v for v in vessels if _lu_vcat(v) == "general"]
    drafts = [v["draft"] for v in gen if v.get("draft")]
    qtys = [v["qty"] for v in gen if v.get("qty")]
    fams = [_lu_cargo_family(v["cargo"]) for v in gen if v.get("cargo")]
    fam = max(set(fams), key=fams.count) if fams else "general"
    out, cum, x, step = [], 0.0, 0.0, 1.0 / 24
    while x <= horizon_days and len(out) < 40:
        cum += rate * unlisted(x + step / 2) * step
        if cum >= len(out) + 0.5:
            out.append({"id": f"__p{len(out)}", "status": "expected", "draft": _lu_median(drafts) or 10.0,
                        "cargo": _LU_RATE_LABEL[fam], "qty": _lu_median(qtys) or 8000, "cat": "general",
                        "ready": now + timedelta(days=x), "phantom": True})
        x += step
    return out


def _lu_record_predictions(db, port, snap_id):
    """Keeps each day's estimated berthing time for every waiting/expected vessel,
    so Compass can later check itself against when they actually berthed."""
    snap = db.execute("SELECT * FROM lu_snapshots WHERE id = ?", (snap_id,)).fetchone()
    if not snap:
        return
    real_now = _lu_now()
    day_start = datetime.strptime(snap["lineup_date"], "%Y-%m-%d") + timedelta(hours=7)
    now = day_start if snap["lineup_date"] < real_now.date().isoformat() else real_now
    berths = _lu_berths(db, port, now)
    vessels = _lu_vessels(db, snap_id)
    learn = _lu_learn(db, port, now)
    sim = _lu_simulate(berths, vessels, now, learn=learn, phantoms=_lu_phantoms(learn, vessels, now), use_bias=False)
    for v in vessels:
        s = sim.get(v["id"]) or {}
        if v["status"] == "alongside" or not s.get("start"):
            continue
        db.execute("DELETE FROM lu_predictions WHERE port = ? AND vessel = ? AND made_on = ?", (port, v["vessel"], snap["lineup_date"]))
        db.execute("INSERT INTO lu_predictions (port, vessel, made_on, pred_start, pred_berth) VALUES (?, ?, ?, ?, ?)",
                   (port, v["vessel"], snap["lineup_date"], s["start"].strftime("%Y-%m-%d %H:%M"), s.get("berth", "")))
    db.commit()


def _lu_suggestions(port, berths, vessels, now, learn, phantoms, base):
    """Berth re-allocations the agent can ask the terminal for: under first come,
    first served nobody loses their turn, but a vessel can often take a smaller
    berth (or shift to one) and free the deep berth our vessel needs. Only moves
    that bring our vessel in at least half a day earlier, and delay nobody else by
    more than a few hours, are suggested."""
    bmap = {b["key"]: b for b in berths}
    if not bmap:
        return []
    real = {v["id"]: v for v in vessels}

    def fits(v, k):
        b = bmap[k]
        cat = _lu_vcat(v)
        kind_ok = b.get("general") if cat == "general" else cat in (b.get("cats") or [])
        return kind_ok and (not v.get("draft") or not b.get("max_draft") or v["draft"] <= b["max_draft"])

    out = []
    for o in vessels:
        if not o["ours"] or o["status"] == "alongside" or not (base.get(o["id"]) or {}).get("start"):
            continue
        o0 = base[o["id"]]["start"]
        cands = []
        ob = (base.get(o["id"]) or {}).get("berth_key")
        o_ok = [k for k in bmap if fits(o, k)]
        for k in o_ok:                                      # our vessel takes another berth that frees sooner
            if k != ob:
                cands.append(("move", o, k, None))
        for v in vessels:                                   # a vessel ahead of ours, at our berth, takes another berth
            if v["id"] == o["id"] or v["status"] == "alongside":
                continue
            bv = base.get(v["id"]) or {}
            if not bv.get("start") or bv["start"] > o0 + timedelta(hours=2) or bv.get("berth_key") not in o_ok:
                continue
            for k in bmap:
                if k != bv.get("berth_key") and fits(v, k):
                    cands.append(("reallocate", v, k, None))
        for v in vessels:                                   # a vessel alongside shifts to a smaller berth that frees first
            if v["id"] == o["id"] or v["status"] != "alongside":
                continue
            a = _lu_berth_slot(v["berth"])[0]
            bv = base.get(v["id"]) or {}
            if a not in bmap or a not in o_ok or not bv.get("end"):
                continue
            for k in bmap:
                if k == a or not fits(v, k):
                    continue
                busy_until = max([now] + [(base.get(x["id"]) or {}).get("end") or now for x in vessels
                                          if x["status"] == "alongside" and _lu_berth_slot(x["berth"])[0] == k])
                if busy_until < bv["end"] - timedelta(hours=12):
                    cands.append(("shift", v, k, busy_until))
        best_for_o = []
        for kind, v, k, when in cands:
            sim = _lu_simulate(berths, vessels, now, learn=learn, phantoms=phantoms,
                               force={v["id"]: k} if kind in ("reallocate", "move") else None,
                               shift={v["id"]: (k, when)} if kind == "shift" else None)
            o1 = (sim.get(o["id"]) or {}).get("start")
            if not o1:
                continue
            gain = _lu_days(o0, o1)
            if gain < 0.5:
                continue
            worst, who = 0.0, []
            o_ready = (base.get(o["id"]) or {}).get("ready")
            for vid, r0 in base.items():
                if vid not in real or vid == o["id"]:
                    continue
                r1 = sim.get(vid) or {}
                key = "end" if real[vid]["status"] == "alongside" else "start"
                if r0.get(key) and r1.get(key):
                    dly = _lu_days(r1[key], r0[key])
                    if dly > 0.1:
                        later = bool(o_ready and r0.get("ready") and r0["ready"] > o_ready)
                        who.append((real[vid]["vessel"], round(dly, 2), "later" if later else "earlier"))
                        if not later:                         # a vessel that arrived before ours loses her turn: not a fair request
                            worst = max(worst, dly)
            if worst > 0.25:
                continue
            nb = (sim.get(o["id"]) or {}).get("berth", "")
            if kind in ("reallocate", "move"):
                when = (sim.get(v["id"]) or {}).get("start")
            item = {"vessel_id": o["id"], "vessel": o["vessel"], "kind": kind, "other_id": v["id"], "other": v["vessel"],
                    "other_draft": v.get("draft"), "other_from": (base.get(v["id"]) or {}).get("berth") or v.get("berth") or "",
                    "to_berth": bmap[k]["name"], "when": when.strftime("%Y-%m-%d %H:%M") if when else "",
                    "o_from": o0.strftime("%Y-%m-%d %H:%M"), "o_to": o1.strftime("%Y-%m-%d %H:%M"), "o_berth": nb,
                    "gain": round(gain, 1), "delays": who, "worst": round(max(worst, 0.0), 2),
                    "o_fits": [bmap[x]["name"] for x in o_ok],
                    "o_alloc": (_lu_berth_slot(o.get("berth"))[0] if o.get("berth") else ""), "o_slot": _lu_berth_slot(o.get("berth"))[1]}
            item["message"] = _lu_request_message(port, o, v, item)

            def off(x):
                return round(_lu_days(x, now), 2)
            prev = []                                         # the berth plan with the change, for the preview
            for vid, r in sim.items():
                if vid not in real or not r.get("end") or not r.get("berth"):
                    continue
                if r.get("shifted_from"):
                    prev.append([vid, r["shifted_from"], off(r["start"]), off(r["shift_at"])])
                    prev.append([vid, r["berth"], off(r["shift_at"]), off(r["end"])])
                else:
                    prev.append([vid, r["berth"], off(r["start"]) if r.get("start") else None, off(r["end"])])
            item["preview"] = prev
            item["moved"] = [o["id"], v["id"]]
            best_for_o.append(item)
        best_for_o.sort(key=lambda x: (-x["gain"], x["worst"]))
        seen = set()
        for it in best_for_o:
            key = (it["kind"], it["other"])
            if key in seen:
                continue
            seen.add(key)
            out.append(it)
            if len([x for x in out if x["vessel_id"] == o["id"]]) >= 2:
                break
    out.sort(key=lambda x: -x["gain"])
    return out


def _lu_signer():
    try:
        return session.get("display_name") or session.get("username") or ""
    except RuntimeError:                                # outside a request (background work)
        return ""


def _lu_request_message(port, o, v, it):
    """Formal request to the terminal / harbour master for a berth re-allocation."""
    full = _LU_PORT[port][1]
    od = f" (arrival draft {o['draft']:.1f} m)" if o.get("draft") else ""
    if o["status"] == "anchor" and o.get("arrived"):
        since = f" has been waiting at anchorage since {_lu_fmt_day(o['arrived'])}"
    else:
        e = _lu_dt(o.get("eta") or "")
        since = (f" has been due since {_lu_fmt_day(o['eta'])}" if e and e < _lu_now() - timedelta(hours=12)
                 else " is expected" + (f" on {_lu_fmt_day(o['eta'])}" if o.get("eta") else ""))
    vd = f" (draft {v['draft']:.1f} m)" if v.get("draft") else ""
    if it["kind"] == "move":
        cur_b = it.get("o_alloc") and f"Berth {it['o_alloc']}" or it.get("other_from") or "her present allocation"
        place = f" ({_ord(it['o_slot'])} in line)" if it.get("o_slot") else ""
        ask = (f"I request that {o['vessel']} be allocated {it['to_berth']}, which becomes available on {_lu_fmt_day(it['o_to'])} "
               f"and accepts her draft, instead of {cur_b}{place}.")
    elif it["kind"] == "reallocate":
        on = f" when it becomes available on {_lu_fmt_day(it['when'])}" if it.get("when") else ""
        ask = f"I request that {v['vessel']}{vd} be allocated {it['to_berth']}{on}, instead of {it['other_from']}."
        if it.get("o_fits") == [it["other_from"]]:
            ask += (f" {it['other_from']} is the only berth able to accept {o['vessel']}'s draft, "
                    f"while {it['to_berth']} accepts {v['vessel']}'s.")
        else:
            ask += f" {it['to_berth']} accepts her draft."
    else:
        ask = (f"I request that {v['vessel']}{vd}, presently alongside {it['other_from']}, be shifted to {it['to_berth']} "
               f"when that berth becomes available on {_lu_fmt_day(it['when'])}, as it accepts her draft.")
    gain = (f"This allows {o['vessel']} to berth at {it['o_berth']} on {_lu_fmt_day(it['o_to'])} instead of "
            f"{_lu_fmt_day(it['o_from'])}, reducing her waiting time by approximately {_lu_n_days(it['gain'])}.")
    if it["kind"] == "move":
        gain = (f"This allows her to berth on {_lu_fmt_day(it['o_to'])} instead of {_lu_fmt_day(it['o_from'])}, "
                f"reducing her waiting time by approximately {_lu_n_days(it['gain'])}.")
    effects = []
    for name, d, *_ in it.get("delays", []):
        h = max(1, round(d * 24))
        if name == v["vessel"] and it["kind"] == "shift":
            effects.append(f"the only effect on {name} is the shifting time of approximately {h} hours")
        else:
            effects.append(f"{name} would berth approximately {h} hours later")
    if effects:
        fair = "Based on the current line-up, " + "; ".join(effects) + ". No vessel that arrived before her is delayed."
    elif it["kind"] == "move":
        fair = "Based on the current line-up, no other vessel is delayed."
    elif it["kind"] == "reallocate":
        fair = f"Based on the current line-up, {v['vessel']} keeps her turn and no other vessel is delayed."
    else:
        fair = f"Based on the current line-up, {v['vessel']} completes her cargo operations as planned and no other vessel is delayed."
    me = _lu_signer()
    return ("Dear Sir,\n\n"
            f"I write regarding the berthing sequence at {full}. {o['vessel']}{od}{since}.\n\n"
            f"{ask} {gain} {fair}\n\n"
            "Kindly confirm the revised allocation.\n\n"
            "Best regards,\n" + (me + "\n" if me else "") + COMPANY_NAME_EN)


def _lu_days(a, b):
    return (a - b).total_seconds() / 86400.0


def _lu_port_state(db, port, now=None, plan_extra=None):
    """Everything the page needs for one port, worked out from its latest line-up."""
    now = now or _lu_now()
    short, full = _LU_PORT[port]
    berths = _lu_berths(db, port, now)
    snap = _lu_latest(db, port)
    out = {"port": port, "name": short, "full": full, "berths": berths, "snapshot": None, "vessels": [],
           "changes": [], "alerts": [], "history": [], "outlook": [], "avg_wait": None, "avg_wait_prev": None}
    if not snap:
        return out
    vessels = _lu_vessels(db, snap["id"])
    learn = _lu_learn(db, port, now)
    phantoms = _lu_phantoms(learn, vessels, now)
    sim = _lu_simulate(berths, vessels, now, learn=learn, phantoms=phantoms)
    out["snapshot"] = {"id": snap["id"], "date": snap["lineup_date"], "source": snap["source"], "by": snap["created_by"], "at": snap["created_at"]}
    gen_keys = {b["key"] for b in berths if b["general"]}

    def relevant(v):
        """A general cargo vessel, or one taking a general cargo berth (e.g. bulk at Yanbu 8)."""
        if _lu_vcat(v) == "general":
            return True
        k = _lu_berth_slot(v.get("berth"))[0] or (sim.get(v["id"]) or {}).get("berth_key")
        return bool(k) and k in gen_keys
    rel = {v["id"]: relevant(v) for v in vessels}
    waiting = [v for v in vessels if v["status"] == "anchor" and rel[v["id"]]]
    waiting_sorted = sorted(waiting, key=lambda v: (sim.get(v["id"], {}).get("start") or now + timedelta(days=99), _lu_dt(v["arrived"]) or now))
    pos = {v["id"]: i + 1 for i, v in enumerate(waiting_sorted)}
    for v in vessels:
        s = sim.get(v["id"], {})
        cat = _lu_vcat(v)
        fits = [b["name"] for b in berths if (b["general"] if cat == "general" else cat in b["cats"]) and (not v["draft"] or not b.get("max_draft") or v["draft"] <= b["max_draft"])]
        ready = s.get("ready")
        tk, slot = _lu_berth_slot(v["berth"]) if v["status"] != "alongside" else ("", 0)
        if tk and not slot:
            same = sorted([x for x in vessels if x["status"] != "alongside" and _lu_berth_slot(x["berth"])[0] == tk],
                          key=lambda x: (sim.get(x["id"], {}).get("start") or now + timedelta(days=999)))
            slot = [x["id"] for x in same].index(v["id"]) + 1 if len(same) > 1 else 1
        item = dict(v)
        item.update({
            "cat": cat, "cat_label": _LU_CAT_LABEL.get(cat, cat), "relevant": rel[v["id"]],
            "alloc_berth": (("Berth " + tk) if re.match(r"^\d", tk) else tk.title()) if tk else "", "alloc_slot": slot,
            "noeta": bool(s.get("noeta")), "elsewhere": bool(s.get("elsewhere")), "plan_key": s.get("berth_key") or "",
            "est_berth": s.get("berth", ""), "nofit": bool(s.get("nofit")),
            "est_start": s["start"].strftime("%Y-%m-%d %H:%M") if s.get("start") else "",
            "est_end": s["end"].strftime("%Y-%m-%d %H:%M") if s.get("end") else "",
            "start_off": round(_lu_days(s["start"], now), 2) if s.get("start") else None,
            "end_off": round(_lu_days(s["end"], now), 2) if s.get("end") else None,
            "ready_off": round(_lu_days(ready, now), 2) if ready else None,
            "waited": round(max(0, _lu_days(now, _lu_dt(v["arrived"]))), 1) if v["status"] == "anchor" and _lu_dt(v["arrived"]) else None,
            "total_wait": round(max(0, _lu_days(s["start"], ready)), 1) if s.get("start") and ready and v["status"] != "alongside" else None,
            "margin": round(s["margin"], 2) if s.get("margin") is not None else None,
            "fits": fits, "position": pos.get(v["id"]),
            "shifted_from": s.get("shifted_from") or "",
            "segs": [{"b": x["b"], "s": round(_lu_days(x["s"], now), 2), "e": round(_lu_days(x["e"], now), 2)} for x in (s.get("segs") or [])],
        })
        out["vessels"].append(item)

    # how long a vessel arriving today waits, low draft and high draft (each band the berths make)
    t0 = _lu_t0(snap, now)
    out["bands"] = _lu_bands(berths, vessels, learn, now, t0, port)
    out["played_from"] = t0.strftime("%Y-%m-%d %H:%M")
    b0 = out["bands"][0] if out["bands"] else None
    bz = out["bands"][-1] if len(out["bands"]) > 1 else None
    out["probe"] = {"normal": b0["wait"] if b0 else None, "deep": bz["wait"] if bz else None, "deep_over": bz["lo"] if bz else None,
                    "ahead": b0["ahead"] if b0 else 0, "ahead_deep": bz["ahead"] if bz else 0}

    # outlook: vessels waiting at noon of each of the next 7 days (from today's line-up)
    for d in range(7):
        t = (now.replace(hour=12, minute=0) + timedelta(days=d)) if d else now
        n = 0
        for v in out["vessels"]:
            if v["status"] == "alongside" or not v["relevant"]:
                continue
            rd, st = v["ready_off"], v["start_off"]
            to = _lu_days(t, now)
            if rd is not None and rd <= to and (st is None or st > to):
                n += 1
        u = 0
        for ph in phantoms:                       # likely arrivals not on the line-up yet
            r = sim.get(ph["id"]) or {}
            if r.get("ready") and _lu_days(r["ready"], now) <= _lu_days(t, now) and (not r.get("start") or r["start"] > t):
                u += 1
        out["outlook"].append(n + u)
        out.setdefault("outlook_unlisted", []).append(u)

    # history (last 30 days of line-ups): waiting count per day, and real waiting times
    since = (now.date() - timedelta(days=30)).isoformat()
    snaps = db.execute("SELECT id, lineup_date FROM lu_snapshots WHERE port = ? AND lineup_date >= ? ORDER BY lineup_date, id", (port, since)).fetchall()
    per_day = {}
    for sn in snaps:
        per_day[sn["lineup_date"]] = sn["id"]
    for day, sid in sorted(per_day.items())[-14:]:
        n = sum(1 for v in _lu_vessels(db, sid) if v["status"] == "anchor" and (_lu_vcat(v) == "general" or _lu_berth_slot(v["berth"])[0] in gen_keys))
        out["history"].append({"date": day, "waiting": n})
    waits, waits_prev, seen = [], [], set()
    if per_day:
        rows = db.execute(
            "SELECT v.vessel, v.arrived, v.berthed, v.cargo, v.vtype, v.berth, v.draft, s.lineup_date FROM lu_vessels v JOIN lu_snapshots s ON s.id = v.snapshot_id "
            "WHERE s.port = ? AND s.lineup_date >= ? AND v.status = 'alongside' AND v.arrived <> '' AND v.berthed <> ''",
            (port, since)).fetchall()
        for r in rows:
            if _lu_vcat(r) != "general" and _lu_berth_slot(r["berth"])[0] not in gen_keys:
                continue
            key = (r["vessel"], r["arrived"][:10])
            if key in seen:
                continue
            seen.add(key)
            a, b = _lu_dt(r["arrived"]), _lu_dt(r["berthed"])
            if a and b and b >= a:
                w = _lu_days(b, a)
                (waits if (now - b).days < 14 else waits_prev).append(w)
                if (now - b).days < 14 and r["draft"]:
                    for band in out["bands"]:
                        if (band["lo"] is None or r["draft"] > band["lo"]) and (band["hi"] is None or r["draft"] <= band["hi"]):
                            band.setdefault("_recent", []).append(w)
    for band in out["bands"]:
        ws = band.pop("_recent", [])
        if ws:
            band["recent"], band["n_recent"] = round(_lu_median(ws), 1), len(ws)
    if len(waits) >= 2:
        out["avg_wait"] = round(sum(waits) / len(waits), 1)
    out["wait_today"] = out["probe"]["normal"]
    if len(waits_prev) >= 2:
        out["avg_wait_prev"] = round(sum(waits_prev) / len(waits_prev), 1)

    # changes since the previous line-up
    prev = _lu_latest(db, port, before_id=snap["id"])
    if prev:
        old_list = _lu_vessels(db, prev["id"])
        old = {v["vessel"]: v for v in old_list}
        new = {v["vessel"]: v for v in vessels}
        berth_moves = []
        old_sim = _lu_simulate(berths, old_list, now, learn=learn)    # yesterday's queue worked out the same way, so places compare like with like
        old_wait = [v["vessel"] for v in sorted([v for v in old_list if v["status"] == "anchor"],
                    key=lambda v: (old_sim.get(v["id"], {}).get("start") or now + timedelta(days=99), _lu_dt(v["arrived"]) or now))]
        new_pos = {v["vessel"]: v["position"] for v in out["vessels"] if v["position"]}
        for n, v in new.items():
            o = old.get(n)
            ours = " (ours)" if v["ours"] else ""
            if not o:
                kind = "Arrived" if v["status"] == "anchor" else ("Berthed" if v["status"] == "alongside" else "New")
                what = f"{n}{ours}" + (f", {v['cargo'].lower()}" if v["cargo"] else "") + (f" {int(v['qty']):,} MT" if v["qty"] else "")
                out["changes"].append({"kind": kind, "tone": "", "text": what})
            elif o["status"] != "alongside" and v["status"] == "alongside":
                out["changes"].append({"kind": "Berthed", "tone": "g", "text": f"{n}{ours}" + (f" at {v['berth'].title()}" if v["berth"] else "")})
            elif o["status"] == "expected" and v["status"] == "anchor":
                out["changes"].append({"kind": "Arrived", "tone": "", "text": f"{n}{ours} now at anchorage"})
            if o:
                ob, nb = _lu_berth_slot(o["berth"])[0], _lu_berth_slot(v["berth"])[0]
                if ob and nb and ob != nb and v["status"] != "expected":
                    what = "moved from" if (o["status"] == "alongside" and v["status"] == "alongside") else "now allocated"
                    txt = (f"{n}{ours} moved from Berth {ob} to Berth {nb}" if what == "moved from"
                           else f"{n}{ours} now allocated Berth {nb} (was Berth {ob})")
                    out["changes"].append({"kind": "Berth", "tone": "g" if v["ours"] else "", "text": txt})
                    if v["ours"]:
                        berth_moves.append((n, ob, nb, v["status"]))
            if v["ours"] and v["status"] == "anchor" and o and o["status"] == "anchor" and n in old_wait and n in new_pos:
                before, after = old_wait.index(n) + 1, new_pos[n]
                if after > before:
                    out["changes"].append({"kind": "Slipped", "tone": "r", "text": f"{n} (ours) from {_ord(before)} to {_ord(after)} in line"})
                    for item in out["vessels"]:
                        if item["vessel"] == n:
                            item["slipped_from"] = before
                elif after < before:
                    out["changes"].append({"kind": "Moved up", "tone": "g", "text": f"{n} (ours) from {_ord(before)} to {_ord(after)} in line"})
        for n, o in old.items():
            if n not in new:
                out["changes"].append({"kind": "Sailed" if o["status"] == "alongside" else "Left", "tone": "",
                                       "text": n + (f" from {o['berth'].title()}" if o["status"] == "alongside" and o["berth"] else " (no longer on the line-up)")})
        for n, ob, nb, st_ in berth_moves:
            out["alerts"].append({"tone": "info", "title": f"{n} " + ("moved to" if st_ == "alongside" else "now allocated") + f" Berth {nb}",
                                  "text": f"The previous line-up had Berth {ob}. The plan now follows the new berth."})
        order = {"Slipped": 0, "Berth": 1, "Berthed": 1, "Moved up": 2, "Arrived": 3, "New": 4, "Sailed": 5, "Left": 6}
        out["changes"].sort(key=lambda c: order.get(c["kind"], 9))

    # alerts about our vessels and the line-up itself
    limit = float(get_setting("lineup_wait_limit", "4") or 4)
    today = now.date().isoformat()
    if snap["lineup_date"] < today:
        out["alerts"].append({"tone": "warn", "title": f"Today's {short} line-up is not in yet", "text": f"Showing the line-up of {_lu_fmt_day(snap['lineup_date'])}, {_lu_n_days(max(1, (now.date() - datetime.strptime(snap['lineup_date'], '%Y-%m-%d').date()).days))} old. Cargo left on board (ROB) is counted from that day, so berthing and sailing times for vessels alongside may be out of date. Upload today's to refresh the plan."})
    if prev_snap_had_expected(db, port, snap) and not any(v["status"] == "expected" for v in vessels):
        out["alerts"].append({"tone": "info", "title": "No expected vessels on this line-up",
                              "text": "The previous line-up had some. If the expected-vessels list came as a separate file, upload it too; it is added to the same day."})
    if not berths:
        out["alerts"].append({"tone": "warn", "title": f"Add the {short} berths", "text": "Enter each general cargo berth with its maximum draft, so Compass can tell which berths a vessel fits."})
    elif any(b["general"] and not b.get("max_draft") and not b.get("seen_deep") for b in berths):
        miss = [b["name"] for b in berths if b["general"] and not b.get("max_draft") and not b.get("seen_deep")]
        missing = ", ".join(miss[:-1]) + " and " + miss[-1] if len(miss) > 1 else miss[0]
        out["alerts"].append({"tone": "info", "title": "Max draft not known for " + missing,
                              "text": "Set it in Berths and settings. Until then Compass lets any draft use " + ("them." if len(miss) > 1 else "it.")})
    over_limit, sailing, berthing = [], [], []
    for v in out["vessels"]:
        if not v["ours"]:
            continue
        if v["nofit"]:
            out["alerts"].append({"tone": "bad", "title": f"{v['vessel']} fits no berth here", "text": f"Her draft of {v['draft']:.1f} m is deeper than every {short} berth on record.", "vessel": v["id"], "msg": True})
        if v.get("slipped_from"):
            out["alerts"].append({"tone": "bad", "title": f"{v['vessel']} slipped from {_ord(v['slipped_from'])} to {_ord(v['position'])}",
                                  "text": "Estimated berthing now " + (_lu_fmt_day(v["est_start"]) if v["est_start"] else "unknown") + (f" at {v['est_berth']}" if v["est_berth"] else "") + ".",
                                  "vessel": v["id"], "msg": True})
        if v["status"] == "anchor" and (v["waited"] or 0) > limit:
            over_limit.append(v)
        if v["status"] != "alongside" and v["margin"] is not None and v["margin"] < _LU_DRAFT_TIGHT:
            over = v["margin"] < -0.005
            out["alerts"].append({"tone": "bad" if over else "warn", "title": f"{v['vessel']}: " + ("draft over the limit at " if over else "tight draft at ") + f"{v['est_berth']}",
                                  "text": (f"Her draft of {v['draft']:.1f} m is {-v['margin']:.2f} m over the berth's {v['draft'] + v['margin']:.1f} m limit." if over
                                           else f"Only {v['margin']:.2f} m under the berth limit." if v["margin"] >= 0.005 else "Her draft is at the berth's limit, with no margin.")
                                          + " Confirm with the harbour master before she shifts in.", "vessel": v["id"], "msg": True})
        if v["status"] == "alongside" and v["end_off"] is not None and v["end_off"] <= 1.5:
            sailing.append(v)
        if v["status"] != "alongside" and v["start_off"] is not None and 0 <= v["start_off"] <= 1.5:
            berthing.append(v)
    if len(over_limit) == 1:
        v = over_limit[0]
        out["alerts"].append({"tone": "warn", "title": f"{v['vessel']} is past your {limit:g}-day limit",
                              "text": f"{v['waited']:.0f} days at anchor so far" + (f", about {v['total_wait']:.0f} in total" if v["total_wait"] else "") + ". Tell the principal about the waiting time now.",
                              "vessel": v["id"], "msg": True})
    elif over_limit:
        over_limit.sort(key=lambda v: -(v["waited"] or 0))
        out["alerts"].append({"tone": "warn", "title": f"{len(over_limit)} of our vessels are past your {limit:g}-day limit",
                              "text": ", ".join(f"{v['vessel'].replace('MV ', '')} {v['waited']:.0f} d" for v in over_limit) + ". Keep their principals informed."})
    if len(sailing) == 1:
        v = sailing[0]
        out["alerts"].append({"tone": "info", "title": f"{v['vessel']} sails ~{_lu_fmt_day(v['est_end'])}", "text": "Prepare the remaining DOs before she sails."})
    elif sailing:
        out["alerts"].append({"tone": "info", "title": f"{len(sailing)} of our vessels sail within two days",
                              "text": ", ".join(f"{v['vessel'].replace('MV ', '')} ~{_lu_fmt_day(v['est_end'])}" for v in sailing) + ". Prepare the remaining DOs."})
    if len(berthing) == 1:
        v = berthing[0]
        out["alerts"].append({"tone": "info", "title": f"{v['vessel']} berths ~{_lu_fmt_day(v['est_start'])}", "text": "Book the surveyor and gangs."})
    elif berthing:
        out["alerts"].append({"tone": "info", "title": f"{len(berthing)} of our vessels berth within two days",
                              "text": ", ".join(f"{v['vessel'].replace('MV ', '')} ~{_lu_fmt_day(v['est_start'])}" for v in berthing) + ". Book surveyors and gangs."})
    rank = {"bad": 0, "warn": 1, "info": 2}
    out["alerts"].sort(key=lambda a: rank[a["tone"]])
    out["learn"] = {k: learn[k] for k in ("days", "rates", "jumps", "arrivals", "accuracy")}
    out["learn"]["bias_use"] = learn["bias_use"]
    out["learn"]["jump_use"] = learn["jump_rate_use"]
    try:
        out["suggestions"] = _lu_suggestions(port, berths, vessels, now, learn, phantoms, sim)
    except Exception:
        app.logger.exception("line-up suggestions failed")
        out["suggestions"] = []
    for sgt in out["suggestions"]:
        for item in out["vessels"]:
            if item["id"] == sgt["vessel_id"]:
                item["best_gain"] = max(item.get("best_gain") or 0, sgt["gain"])
    return out


def prev_snap_had_expected(db, port, snap):
    prev = _lu_latest(db, port, before_id=snap["id"])
    return bool(prev) and bool(db.execute("SELECT 1 FROM lu_vessels WHERE snapshot_id = ? AND status = 'expected' LIMIT 1", (prev["id"],)).fetchone())


def _ord(n):
    n = int(n)
    return f"{n}{'th' if 10 <= n % 100 <= 20 else {1: 'st', 2: 'nd', 3: 'rd'}.get(n % 10, 'th')}"


def _lu_fmt_day(s):
    d = _lu_dt(s) if s and len(s) > 10 else (datetime.strptime(s, "%Y-%m-%d") if s else None)
    return f"{d.day} {d.strftime('%b')}" if d else ""


def _lu_plan(db, draft, cargo, qty, eta, at_port="", vessel_name=""):
    """Compares the three ports for one vessel. eta: datetime she can arrive at the
    nearest port (or now, if she is already lying at at_port)."""
    now = _lu_now()
    res = []
    for port, short, full in _LU_SHOWN:
        berths = _lu_berths(db, port, now)
        snap = _lu_latest(db, port)
        vessels = _lu_vessels(db, snap["id"]) if snap else []
        learn = _lu_learn(db, port, now)
        phantoms = _lu_phantoms(learn, vessels, now, horizon_days=20)
        arrive = (max(now, eta) + timedelta(days=_lu_transit(at_port, port))) if at_port else eta
        cat = "bulk" if cargo == "bulk" else "general"
        usable = [b for b in berths if (b["general"] if cat == "general" else cat in b["cats"])]
        item = {"port": port, "name": short, "full": full, "arrive": arrive.strftime("%Y-%m-%d %H:%M"),
                "transit": _lu_transit(at_port, port) if at_port else 0, "has_lineup": bool(snap),
                "lineup_date": snap["lineup_date"] if snap else "", "berths": len(usable)}
        if not usable:
            item.update({"ok": False, "reason": "No berths set up yet" if not berths else f"No {_LU_CAT_LABEL[cat].lower()} berths seen here yet"})
            res.append(item)
            continue
        fits = [b for b in usable if not b.get("max_draft") or draft <= b["max_draft"]]
        item["fit_count"] = len(fits)
        if not fits:
            deepest = max((b.get("max_draft") or 0) for b in usable)
            item.update({"ok": False, "reason": f"No berth takes {draft:.1f} m (deepest {deepest:.1f} m)"})
            res.append(item)
            continue
        mine = next((v for v in vessels if vessel_name and v["vessel"] == vessel_name), None) if port == at_port else None
        if mine:   # she is already in this port's queue: keep her real place in line
            x = _lu_simulate(berths, vessels, now, learn=learn, phantoms=phantoms).get(mine["id"]) or {}
            arrive = _lu_dt(mine["arrived"]) or now
            item["arrive"] = arrive.strftime("%Y-%m-%d %H:%M")
        else:
            _, x = _lu_newcomer(berths, vessels, learn, now, _lu_t0(snap, now) if snap else now, draft, cargo=cargo, qty=qty,
                                ready=arrive, horizon=20)
        if not x.get("start"):
            item.update({"ok": False, "reason": "No berth available"})
            res.append(item)
            continue
        wait = max(0, _lu_days(x["start"], arrive))
        item.update({"ok": True, "berth": x["berth"], "start": x["start"].strftime("%Y-%m-%d %H:%M"), "end": x["end"].strftime("%Y-%m-%d %H:%M"),
                     "wait": round(wait, 1), "days_alongside": _lu_days_alongside(cargo, qty, learn.get("rates_use")),
                     "tight": x.get("margin") is not None and x["margin"] < _LU_DRAFT_TIGHT, "margin": round(x["margin"], 2) if x.get("margin") is not None else None,
                     "from_now": round(max(0, _lu_days(x["start"], now)), 1)})
        res.append(item)
    ok = [r for r in res if r.get("ok")]
    best = min(ok, key=lambda r: (r["start"], r["wait"])) if ok else None
    if best:
        best["best"] = True
    return res


def _lu_n_days(x):
    n = int(round(x))
    return "1 day" if n == 1 else f"{n} days"


def _lu_plan_message(results, vessel, draft, cargo, qty, at_port):
    ok = sorted([r for r in results if r.get("ok")], key=lambda r: r["start"])
    if not ok:
        return ""
    best = ok[0]
    name = vessel.strip().upper() or "the vessel"
    if name != "the vessel" and not name.startswith("MV "):
        name = "MV " + name
    cargo_txt = (f"{int(qty):,} MT of " if qty else "") + (cargo or "cargo").lower()
    lines = []
    if at_port and best["port"] == at_port:
        head = (f"I have reviewed whether shifting {name} (arrival draft {draft:.1f} m, {cargo_txt}) to another port would shorten her waiting time. "
                f"Based on today's line-ups, remaining at {best['full']} gives the earliest berthing, estimated on {_lu_fmt_day(best['start'])}"
                + (f" at {best['berth']}." if best.get("berth") else "."))
    elif at_port and best["port"] != at_port:
        cur = next((r for r in results if r["port"] == at_port), None)
        head = (f"Further to my review of today's line-ups, I recommend shifting {name} (arrival draft {draft:.1f} m, {cargo_txt}) "
                f"from {_LU_PORT[at_port][1]} to {best['full']}.")
        if cur and cur.get("ok"):
            saved = _lu_days(_lu_dt(cur["start"]), _lu_dt(best["start"]))
            head += (f" Allowing about {_lu_n_days(best['transit']) if best['transit'] >= 1 else 'one day'} for the passage, she is expected to berth at {best['full']} on {_lu_fmt_day(best['start'])}, "
                     f"against {_lu_fmt_day(cur['start'])} if she remains at {_LU_PORT[at_port][1]}, which saves approximately {_lu_n_days(max(0, saved))}.")
    else:
        head = (f"Further to my review of today's line-ups for {name} (arrival draft {draft:.1f} m, {cargo_txt}), "
                f"I recommend {best['full']}, where she is expected to berth on {_lu_fmt_day(best['start'])}"
                + (" on arrival." if best["wait"] < 0.5 else f", after approximately {_lu_n_days(best['wait'])} at anchorage."))
    lines.append(head)
    lines.append("")
    lines.append("Comparison of the three ports based on her draft:")
    for r in results:
        if r.get("ok"):
            if at_port:
                where = " (present position)" if r["port"] == at_port else f" (about {_lu_n_days(r['transit']) if r['transit'] >= 1 else 'one day'} passage)"
                when = "berthing within the day" if r["from_now"] < 0.5 else f"berthing in approximately {_lu_n_days(r['from_now'])}"
                lines.append(f"- {r['full']}{where}: estimated berthing {_lu_fmt_day(r['start'])}, {when}; {r['fit_count']} of {r['berths']} berths accept her draft.")
                continue
            w = "berthing on arrival" if r["wait"] < 0.5 else f"approximately {_lu_n_days(r['wait'])} at anchorage"
            lines.append(f"- {r['full']}: estimated berthing {_lu_fmt_day(r['start'])}, {w}; {r['fit_count']} of {r['berths']} berths accept her draft.")
        else:
            lines.append(f"- {r['full']}: {r.get('reason', 'not available')}.")
    lines.append("")
    lines.append("These estimates are based on the line-ups published today and on current berth occupancy, and remain subject to port authority allocation, priority vessels and weather.")
    me = _lu_signer()
    return ("Dear Sir,\n\n" + "\n".join(lines) + "\n\nI shall keep you updated on any change.\n\nBest regards,\n"
            + (me + "\n" if me else "") + COMPANY_NAME_EN)


# ----- routes -----

@app.route("/lineups")
@login_required
def lineups_page():
    return render_template_string(LINEUP_HTML, username=session.get("username"), role=session.get("role"))


@app.route("/api/lineups", methods=["GET"])
@login_required
def lineups_overview():
    db = get_db()
    return jsonify({
        "now": _lu_now().strftime("%Y-%m-%d %H:%M"),
        "ports": [_lu_port_state(db, p) for p, _, _ in _LU_SHOWN],
        "settings": {"our_names": get_setting("lineup_our_names", "SEA POWER"), "wait_limit": float(get_setting("lineup_wait_limit", "4") or 4)},
        "rates": _LU_RATES, "rate_labels": _LU_RATE_LABEL, "me": _lu_signer(),
    })


_LU_STATUS_RANK = {"alongside": 3, "anchor": 2, "expected": 1}
_LU_FIELDS = ("vessel", "agent", "cargo", "qty", "loa", "draft", "arrived", "eta", "etb", "berth", "berthed", "etd", "status", "remarks", "vtype", "rob", "transit")


def _lu_merge(a, b):
    """One vessel listed in two files (e.g. Dammam's berthing line-up and its
    expected-vessels list): keep the most advanced status (alongside > at anchor >
    expected) with its berth and dates, and fill any blank detail from the other."""
    hi, lo = (a, b) if _LU_STATUS_RANK.get(a["status"], 0) >= _LU_STATUS_RANK.get(b["status"], 0) else (b, a)
    out = dict(hi)
    for k in _LU_FIELDS:
        if out.get(k) in (None, "") and lo.get(k) not in (None, ""):
            out[k] = lo[k]
    return out


@app.route("/api/lineups/import", methods=["POST"])
@login_required
def lineups_import():
    """Reads one or more line-up files (Excel, CSV, Word, text PDFs and scanned PDFs or
    photos). Each file's own date and port are read from it where it states them.
    Files for the same port and date are combined into that day's line-up (Dammam sends
    a berthing programme and a separate 10-day arrivals list); uploading again the same
    day adds to it and updates vessels already on it, and never drops the others."""
    port = (request.form.get("port") or "").upper()
    form_day = (request.form.get("date") or "").strip() or _riyadh_today().isoformat()
    try:
        form_ref = datetime.strptime(form_day, "%Y-%m-%d").date()
    except ValueError:
        return jsonify({"error": "Choose the line-up date."}), 400
    sources = []
    for f in request.files.getlist("files"):
        raw = f.read()
        if not raw:
            continue
        if len(raw) > 25 * 1024 * 1024:
            return jsonify({"error": f"{f.filename} is larger than 25 MB."}), 400
        sources.append((f.filename or "file", raw))
    text = (request.form.get("text") or "").strip()
    if text:
        sources.append(("pasted text", text.encode("utf-8")))
    if not sources:
        return jsonify({"error": "Add a line-up file."}), 400

    results, by_key = [], {}
    today = _riyadh_today()
    for fname, raw in sources:
        try:
            tables = _lu_tables_from_upload(raw, fname if fname != "pasted text" else "")
        except _LuOcrUnavailable:
            app.logger.exception("scan reader unavailable: %s", fname)
            results.append({"source": fname, "error": "This is a scanned line-up, and the scan reader could not start on the server. Try again in a minute; if it keeps failing, check that requirements.txt was deployed."})
            continue
        except Exception:
            app.logger.exception("line-up file could not be read: %s", fname)
            results.append({"source": fname, "error": "This file could not be read. Upload the line-up as the port sends it (PDF, scan, Excel or Word)."})
            continue
        fday = _lu_file_date(tables, fname, today)
        ref = fday or form_ref
        rows = _lu_rows_from_tables(tables, ref)
        kinds = [r for r in rows if "_berth_kind" in r]
        rows = [r for r in rows if "_berth_kind" not in r]
        title = (tables[0].get("title") or "") if tables else ""
        p = port or _lu_guess_port(fname) or _lu_guess_port(title) or _lu_guess_port(" ".join(" ".join(r) for t in tables for r in t["rows"][:8]))
        if p not in _LU_PORT:
            results.append({"source": fname, "error": "Which port is this line-up for? Choose the port and upload again."})
            continue
        if not rows:
            results.append({"source": fname, "error": "No vessel table found in this file."})
            _ai_event("lineups", "gap", "No vessel table found in " + fname[:90], "The line-up layout is not recognised yet.")
            continue
        day = ref.isoformat()
        results.append({"source": fname, "port": p, "port_name": _LU_PORT[p][0], "vessels": len(rows), "date": day, "date_from_file": bool(fday)})
        by_key.setdefault((p, day), []).append((fname, rows))
        kinds_by_port = by_key.setdefault(("_kinds", p), [])
        kinds_by_port.extend(kinds)

    db = get_db()
    for (p, day), kinds in list(by_key.items()):
        if p != "_kinds":
            continue
        by_key.pop((p, day))
        port_k = day
        have_b = {_lu_norm_berth(b["name"]): b for b in _lu_berths_raw(db, port_k)}
        for kd in kinds:
            k = kd["_berth_kind"]
            if k in have_b:
                db.execute("UPDATE lu_berths SET kind = ? WHERE id = ?", (kd["cat"], have_b[k]["id"]))
            else:
                db.execute("INSERT INTO lu_berths (port, name, max_draft, active, sort, kind) VALUES (?, ?, NULL, 1, ?, ?)",
                           (port_k, ("Berth " + k) if re.match(r"^\d+[A-Z]?$", k) else k.title(),
                            int(re.match(r"\d+", k).group(0)) if re.match(r"\d+", k) else 999, kd["cat"]))
                have_b[k] = {"id": None}
    for (p, day), files in by_key.items():
        # vessel names as already known at this port (scans can drop or add a space: 'TE N MARS')
        known_names = {}
        for r in db.execute("SELECT DISTINCT v.vessel FROM lu_vessels v JOIN lu_snapshots s ON s.id = v.snapshot_id WHERE s.port = ? AND s.lineup_date >= ?",
                            (p, (date.fromisoformat(day) - timedelta(days=60)).isoformat())).fetchall():
            known_names.setdefault(_lu_name_key(r["vessel"]), r["vessel"])
        # combine this upload's files, one entry per vessel
        merged, order = {}, []
        for fname, rows in files:
            for r in rows:
                key = _lu_name_key(r["vessel"])
                if key in known_names:
                    r["vessel"] = known_names[key]
                if key in merged:
                    a = merged[key]
                    best = max((a["vessel"], r["vessel"]), key=lambda n: n.count(" "))
                    merged[key] = _lu_merge(a, r)
                    merged[key]["vessel"] = known_names.get(key) or best
                else:
                    merged[key] = r
                    order.append(key)
        now_txt = datetime.utcnow().strftime("%Y-%m-%d %H:%M")
        names = ", ".join(f for f, _ in files)
        existing = db.execute("SELECT * FROM lu_snapshots WHERE port = ? AND lineup_date = ? ORDER BY id DESC LIMIT 1", (p, day)).fetchone()
        if existing:
            snap_id = existing["id"]
            src = existing["source"] or ""
            add = [f for f, _ in files if f not in src]
            if add:
                db.execute("UPDATE lu_snapshots SET source = ? WHERE id = ?", ((src + ", " + ", ".join(add)).strip(", ")[:300], snap_id))
            have = {_lu_name_key(v["vessel"]): v for v in _lu_vessels(db, snap_id)}
        else:
            snap_id = db.execute("INSERT INTO lu_snapshots (port, lineup_date, source, created_by, created_at) VALUES (?, ?, ?, ?, ?) RETURNING id",
                                 (p, day, names[:300], _who(), now_txt)).fetchone()["id"]
            have = {}
        prev = _lu_latest(db, p, before_id=snap_id)
        prev_rows = {_lu_name_key(v["vessel"]): v for v in _lu_vessels(db, prev["id"])} if prev else {}
        known = {_lu_norm_berth(b["name"]) for b in db.execute("SELECT name FROM lu_berths WHERE port = ?", (p,)).fetchall()}
        seq = (db.execute("SELECT MAX(seq) AS m FROM lu_vessels WHERE snapshot_id = ?", (snap_id,)).fetchone()["m"] or 0) + 1 if have else 0
        for key in order:
            r = merged[key]
            old = have.get(key)
            if old:
                m = _lu_merge({k: old.get(k) for k in _LU_FIELDS}, r) if _LU_STATUS_RANK.get(old["status"], 0) > _LU_STATUS_RANK.get(r["status"], 0) else _lu_merge(r, {k: old.get(k) for k in _LU_FIELDS})
                m["vessel"] = old["vessel"]
                ours = 1 if (old["ours"] or _lu_is_ours(m["agent"])) else 0
                db.execute(f"UPDATE lu_vessels SET {', '.join(k + ' = ?' for k in _LU_FIELDS)}, ours = ? WHERE id = ?",
                           (*[m[k] for k in _LU_FIELDS], ours, old["id"]))
            else:
                pv = prev_rows.get(key, {})
                if pv and r["status"] in ("anchor", "alongside") and pv.get("status") in ("anchor", "alongside"):
                    if not r.get("arrived") and pv.get("arrived"):
                        r["arrived"] = pv["arrived"]
                    if r["status"] == "alongside" and pv.get("status") == "alongside" and not r.get("berthed") and pv.get("berthed"):
                        r["berthed"] = pv["berthed"]
                ours = 1 if (_lu_is_ours(r["agent"]) or pv.get("ours")) else 0
                db.execute(
                    "INSERT INTO lu_vessels (snapshot_id, seq, vessel, agent, cargo, qty, loa, draft, arrived, eta, etb, berth, berthed, etd, status, ours, principal, remarks, vtype, rob, transit) "
                    "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    (snap_id, seq, r["vessel"], r["agent"], r["cargo"], r["qty"], r["loa"], r["draft"], r["arrived"], r["eta"], r["etb"], r["berth"],
                     r["berthed"], r["etd"], r["status"], ours, pv.get("principal") or "", r["remarks"], r.get("vtype") or "", r.get("rob"), r.get("transit")))
                seq += 1
            k = _lu_berth_slot(r["berth"])[0]
            if k and k not in known:
                known.add(k)
                db.execute("INSERT INTO lu_berths (port, name, max_draft, active, sort) VALUES (?, ?, NULL, 1, ?)",
                           (p, ("Berth " + k) if re.match(r"^\d+[A-Z]?$", k) else k.title(), int(re.match(r"\d+", k).group(0)) if re.match(r"\d+", k) else 999))
        db.commit()
        g.pop("_lu_learn", None)
        g.pop("_lu_bstats", None)
        try:
            _lu_record_predictions(db, p, snap_id)
        except Exception:
            app.logger.exception("recording line-up predictions failed")
        total = db.execute("SELECT COUNT(*) AS n FROM lu_vessels WHERE snapshot_id = ?", (snap_id,)).fetchone()["n"]
        for res in results:
            if res.get("port") == p and res.get("date") == day and "error" not in res:
                res["snapshot"] = snap_id
                res["total"] = total
                res["combined"] = bool(existing) or len(files) > 1
    return jsonify({"results": results})


def _lu_vessel_fields(data):
    f = {}
    for k in ("vessel", "agent", "cargo", "principal", "remarks", "berth"):
        if k in data:
            f[k] = str(data.get(k) or "").strip()[:120]
    if "vessel" in f:
        bare = re.sub(r"^M\s*[./]?\s*[VT]\b[./]?\s*", "", f["vessel"].upper()).strip()
        f["vessel"] = ("MV " + bare) if bare else ""
    for k in ("qty", "loa", "draft"):
        if k in data:
            f[k] = _lu_num(data.get(k))
    for k in ("arrived", "eta", "etb", "berthed", "etd"):
        if k in data:
            v = str(data.get(k) or "").strip().replace("T", " ")
            d = _lu_dt(v[:16]) if len(v) >= 16 else (_lu_dt(v + " 12:00") if len(v) == 10 else None)
            f[k] = d.strftime("%Y-%m-%d %H:%M") if d else ""
    if "status" in data and data["status"] in ("alongside", "anchor", "expected"):
        f["status"] = data["status"]
    if "ours" in data:
        f["ours"] = 1 if data.get("ours") else 0
    return f


@app.route("/api/lineups/vessels/<int:vid>", methods=["PUT", "DELETE"])
@login_required
def lineups_vessel(vid):
    db = get_db()
    if not db.execute("SELECT 1 FROM lu_vessels WHERE id = ?", (vid,)).fetchone():
        return jsonify({"error": "Not found."}), 404
    if request.method == "DELETE":
        db.execute("DELETE FROM lu_vessels WHERE id = ?", (vid,))
        db.commit()
        return jsonify({"ok": True})
    f = _lu_vessel_fields(request.get_json(force=True) or {})
    if "vessel" in f and not f["vessel"]:
        return jsonify({"error": "Enter the vessel name."}), 400
    if f:
        db.execute(f"UPDATE lu_vessels SET {', '.join(k + ' = ?' for k in f)} WHERE id = ?", (*f.values(), vid))
        db.commit()
    return jsonify({"ok": True})


@app.route("/api/lineups/<port>/vessels", methods=["POST"])
@login_required
def lineups_add_vessel(port):
    port = port.upper()
    if port not in _LU_PORT:
        return jsonify({"error": "Unknown port."}), 404
    db = get_db()
    f = _lu_vessel_fields(request.get_json(force=True) or {})
    if not f.get("vessel"):
        return jsonify({"error": "Enter the vessel name."}), 400
    snap = _lu_latest(db, port)
    today = _riyadh_today().isoformat()
    if not snap or snap["lineup_date"] != today:
        # start today's line-up as a copy of the last one, so adding a vessel never loses the others
        sid = db.execute("INSERT INTO lu_snapshots (port, lineup_date, source, created_by, created_at) VALUES (?, ?, ?, ?, ?) RETURNING id",
                         (port, today, "entered by hand", _who(), datetime.utcnow().strftime("%Y-%m-%d %H:%M"))).fetchone()["id"]
        if snap:
            for v in _lu_vessels(db, snap["id"]):
                cols = [c for c in v if c not in ("id", "snapshot_id", "lu_date")]
                db.execute(f"INSERT INTO lu_vessels (snapshot_id, {', '.join(cols)}) VALUES (?, {', '.join('?' for _ in cols)})", (sid, *[v[c] for c in cols]))
        snap_id = sid
    else:
        snap_id = snap["id"]
    f.setdefault("status", "anchor")
    f["ours"] = 1 if (f.get("ours") or _lu_is_ours(f.get("agent"))) else 0
    seq = (db.execute("SELECT MAX(seq) AS m FROM lu_vessels WHERE snapshot_id = ?", (snap_id,)).fetchone()["m"] or 0) + 1
    cols = ["snapshot_id", "seq"] + list(f.keys())
    db.execute(f"INSERT INTO lu_vessels ({', '.join(cols)}) VALUES ({', '.join('?' for _ in cols)})", (snap_id, seq, *f.values()))
    db.commit()
    return jsonify({"ok": True})


@app.route("/api/lineups/<port>/berths", methods=["PUT"])
@login_required
def lineups_berths(port):
    """Replaces the berth list of one port: [{id?, name, max_draft}]."""
    port = port.upper()
    if port not in _LU_PORT:
        return jsonify({"error": "Unknown port."}), 404
    items = (request.get_json(force=True) or {}).get("berths") or []
    db = get_db()
    keep = []
    for i, b in enumerate(items):
        name = re.sub(r"\s+", " ", str(b.get("name") or "")).strip()[:40]
        if not name:
            continue
        md = _lu_num(b.get("max_draft"))
        if md is not None and not (3 <= md <= 25):
            return jsonify({"error": f"Max draft for {name} looks wrong ({md} m)."}), 400
        use = b.get("cargo_use") if b.get("cargo_use") in ("general", "other") else ""
        if b.get("id"):
            db.execute("UPDATE lu_berths SET name = ?, max_draft = ?, cargo_use = ?, active = 1, sort = ? WHERE id = ? AND port = ?", (name, md, use, i, int(b["id"]), port))
            keep.append(int(b["id"]))
        else:
            keep.append(db.execute("INSERT INTO lu_berths (port, name, max_draft, cargo_use, active, sort) VALUES (?, ?, ?, ?, 1, ?) RETURNING id", (port, name, md, use or "general", i)).fetchone()["id"])
    if keep:
        db.execute(f"DELETE FROM lu_berths WHERE port = ? AND id NOT IN ({', '.join('?' for _ in keep)})", (port, *keep))
    else:
        db.execute("DELETE FROM lu_berths WHERE port = ?", (port,))
    db.commit()
    return jsonify({"ok": True})


@app.route("/api/lineups/settings", methods=["POST"])
@login_required
def lineups_settings():
    data = request.get_json(force=True) or {}
    if "our_names" in data:
        names = ", ".join(x.strip().upper() for x in str(data["our_names"]).split(",") if x.strip())[:200]
        set_setting("lineup_our_names", names or "SEA POWER")
    if "wait_limit" in data:
        try:
            set_setting("lineup_wait_limit", str(max(0.5, min(30.0, float(data["wait_limit"])))))
        except (TypeError, ValueError):
            return jsonify({"error": "Enter the waiting limit in days."}), 400
    return jsonify({"ok": True})


@app.route("/api/lineups/plan", methods=["POST"])
@login_required
def lineups_plan():
    data = request.get_json(force=True) or {}
    draft = _lu_num(data.get("draft"))
    if not draft or not (2 <= draft <= 25):
        return jsonify({"error": "Enter the arrival draft in metres."}), 400
    qty = _lu_num(data.get("qty")) or 0
    cargo = str(data.get("cargo") or "general")
    cargo_txt = _LU_RATE_LABEL.get(cargo, cargo)
    at_port = (data.get("at_port") or "").upper()
    if at_port and at_port not in _LU_PORT:
        at_port = ""
    now = _lu_now()
    if at_port:
        eta = now
    else:
        e = str(data.get("eta") or "")
        eta = _lu_dt(e + " 12:00") if len(e) == 10 else None
        eta = eta or now
        if eta < now:
            eta = now
    db = get_db()
    res = _lu_plan(db, draft, cargo_txt, qty, eta, at_port, (data.get("vessel_in_lineup") or "").upper())
    msg = _lu_plan_message(res, str(data.get("vessel") or ""), draft, cargo_txt, qty, at_port)
    return jsonify({"results": res, "message": msg})



